INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-1-u1-C1','soc',6,1,'u1',1,'분단의 과정 — 광복 이후 대한민국 정부와 북한 정권이 각각 세워지며 남북이 나뉘었고, 6·25 전쟁을 겪으면서 분단이 굳어짐 · 그 뒤 70여 년이 흐름 · 분단 때문에 옛날처럼 금강산에 마음대로 갈 수 없게 됨',ARRAY['[6사07-01] 분단으로 나타난 문제와 평화 통일을 위한 다양한 노력을 살펴보고, 평화 통일을 위해 할 수 있는 일을 실천한다(차시 머리 주석 기준)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-1-u1-C2','soc',6,1,'u1',1,'분단으로 나타난 문제점 — ① 고향을 잃은 실향민과 가족이 흩어진 이산가족의 아픔 ② 시간이 흐를수록 커지는 생활 방식과 언어의 차이(같은 것을 다르게 부름 → 의사소통이 어려워짐) ③ 군사적 위협에 따른 전쟁의 긴장감 ④ 많은 국방비 지출 · 분단 비용은 군대를 유지하는 돈만이 아니라 자원을 쓰지 못하는 비용, 대륙으로 길이 이어지지 않아 돌아가는 비용, 이산가족의 아픔과 약해진 국력까지 여러 갈래 · 문제는 분단이라는 상황이지 북한 사람이 아님',ARRAY['[6사07-01] 분단으로 나타난 문제와 평화 통일을 위한 다양한 노력을 살펴보고, 평화 통일을 위해 할 수 있는 일을 실천한다(차시 머리 주석 기준)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-1-u1-C3','soc',6,1,'u1',2,'분단의 아픔이 담긴 장소 — 6·25 전쟁의 흔적이 남은 곳이나 분단으로 생긴 곳 · 휴전선(전쟁 뒤 한반도를 가로지름), 아바이 마을(피란 왔다가 돌아가지 못한 사람들이 모여 만든 마을), 백마고지 전적지(희생된 군인을 기리는 기념관·기념비), 장사 상륙 작전 전승 기념관(학생 신분으로 참전한 군인을 추모) · 비무장 지대는 정전 협정에 따라 군사 충돌을 막으려고 정한 지대로 군사적 행위가 금지되고, 자연환경이 잘 보전되어 희귀 생물이 삶',ARRAY['[6사07-01] 분단으로 나타난 문제와 평화 통일을 위한 다양한 노력을 살펴보고, 평화 통일을 위해 할 수 있는 일을 실천한다(차시 머리 주석 기준)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-1-u1-C4','soc',6,1,'u1',2,'평화의 장소로 바꾸는 노력과 답사 — 아픔이 담긴 장소를 없애거나 잊는 것이 아니라 평화의 장소로 바꾸려고 노력함: DMZ 평화의 길(남북 합의로 일부 구간을 열어 관람), 오산 죽미령 평화 공원(평화의 중요성을 알리는 공간) · 판문점은 정전 협정 체결과 남북 정상 회담의 장소로 분단과 평화의 상징 · 인터넷 답사는 장소 고르기 → 누리집 방문 → 의미 → 일어난 사건 → 주요 시설 → 시설이 어떤 곳인지 확인 → 느낀 점 · 통일 뒤 비무장 지대를 평화 생태 학습 공간 등으로 활용하는 상상',ARRAY['[6사07-01] 분단으로 나타난 문제와 평화 통일을 위한 다양한 노력을 살펴보고, 평화 통일을 위해 할 수 있는 일을 실천한다(차시 머리 주석 기준)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-1-u1-C5','soc',6,1,'u1',3,'평화 통일을 위한 정치적 노력 — 7·4 남북 공동 성명(분단 이후 처음으로 통일 원칙에 관한 합의를 담아 발표) → 남북 기본 합의서(남북 화해·평화·교류와 협력 등의 내용을 담아 채택) → 여러 차례의 남북 정상 회담 · 남과 북이 대화와 약속으로 신뢰를 쌓음',ARRAY['[6사07-01] 분단으로 나타난 문제와 평화 통일을 위한 다양한 노력을 살펴보고, 평화 통일을 위해 할 수 있는 일을 실천한다(차시 머리 주석 기준)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-1-u1-C6','soc',6,1,'u1',3,'평화 통일을 위한 사회·문화적 노력 — 남북 학자들의 문화유산 공동 발굴(고려의 궁궐터 개성 만월대), 국제 대회 단일팀 구성과 동시 입장(통일의 희망을 전함), 『겨레말큰사전』 공동 편찬(달라진 남북 언어문화를 이해하고 한민족임을 잊지 않으며 통일을 준비)',ARRAY['[6사07-01] 분단으로 나타난 문제와 평화 통일을 위한 다양한 노력을 살펴보고, 평화 통일을 위해 할 수 있는 일을 실천한다(차시 머리 주석 기준)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-1-u1-C7','soc',6,1,'u1',3,'평화 통일을 위한 경제적 노력 — 금강산 관광 사업, 개성 공업 단지 운영 사업(남한의 자본과 기술 + 북한의 노동력을 합해 상품 생산), 남북 철도·도로 연결 사업(끊어진 길을 이어 왕래를 도움, 이어지면 육로로 대륙까지) · 까닭: 남북의 장점이 결합하면 더 큰 경제적 이익, 서로 잘 살려면 협력이 필요, 평화 통일의 밑바탕 · 협력은 한쪽이 일방적으로 돕는 것이 아니라 두 몫이 나란히 있어야 이루어짐 · 지금은 중단되었으나 다시 하려고 노력 중',ARRAY['[6사07-01] 분단으로 나타난 문제와 평화 통일을 위한 다양한 노력을 살펴보고, 평화 통일을 위해 할 수 있는 일을 실천한다(차시 머리 주석 기준)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-1-u1-C8','soc',6,1,'u1',4,'평화 통일을 위해 할 수 있는 일 — ① 남북 관계·통일의 필요성을 알아보며 올바른 인식 갖기 ② 편지 쓰기·그림 그리기 대회에 참가하며 통일을 바라는 마음 키우기 ③ 알뜰 시장·캠페인으로 어려움을 겪는 북한 주민 돕기 ④ 통일 퀴즈 대회·북한 문화유산 알아보기로 평화 통일의 의미와 중요성 알리기 · 북한에 관심을 갖는 것도 실천 · 실천 방법(통일 밥상 그리기·종이비행기 날리기·뮤직비디오 만들기)은 저마다 고르고 그 차례를 끝까지 밟음, 노래를 쓰면 출처를 밝히고 저작권 존중 · 북한 연구자에게는 남북의 차이를 이해하고 받아들이는 포용력과 폭넓은 시각이 필요',ARRAY['[6사07-01] 분단으로 나타난 문제와 평화 통일을 위한 다양한 노력을 살펴보고, 평화 통일을 위해 할 수 있는 일을 실천한다(차시 머리 주석 기준)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-1-u1-C9','soc',6,1,'u1',5,'4·19 혁명의 원인과 전개 — 첫 대통령 이승만이 헌법을 바꿔 가며 오래 집권하고 전쟁 뒤 경제가 어려워 국민의 불만이 높아짐 → 정부가 선거 운동에 개입하자 대구의 고등학생들이 처음 맞섬 → 3·15 부정 선거(돈·물건 주기, 조를 짜 투표 확인, 미리 표시한 투표지) → 선거 무효를 외친 시위, 마산 시위에 참여한 고등학생 김주열의 죽음이 알려지며 전국으로 퍼짐 → 4월 19일 여러 도시에서 초등학생부터 대학교수까지 각계각층이 시위 → 이승만이 물러나고 3·15 부정 선거는 무효 · 부정 선거는 국민의 뜻이 제대로 전달되지 않고 국민이 결과를 믿지 못하게 함',ARRAY['[6사07-02] 민주화와 산업화의 과정을 주요 사건을 중심으로 살펴보고, 그에 따른 생활 모습의 변화를 탐구한다(차시 머리 주석 기준)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-1-u1-C10','soc',6,1,'u1',5,'4·19 혁명의 의의 — 시민과 학생의 힘으로 민주적 절차를 무시한 정권을 무너뜨린 사건으로 우리나라 민주주의 발전의 밑거름이 됨 · 역사는 일어난 일을 차례로 외우는 것이 아니라 왜 그렇게 되었는지 원인에서 결과로 되짚는 공부',ARRAY['[6사07-02] 민주화와 산업화의 과정을 주요 사건을 중심으로 살펴보고, 그에 따른 생활 모습의 변화를 탐구한다(차시 머리 주석 기준)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-1-u1-C11','soc',6,1,'u1',6,'5·18 민주화 운동 — 4·19 혁명 뒤 군인들이 정변(법에 맞지 않는 방법으로 일어난 정치적 변화)을 일으켜 정권을 잡고 오래 집권 → 또다시 군인들이 정변으로 권력을 장악하자 시민들이 퇴진과 민주화를 요구 → 광주에서 대규모 민주화 시위, 계엄군(국가 비상사태에 질서 유지를 목적으로 활용한 군대)이 폭력적으로 진압 → 광주 시민은 시민군을 만들어 맞서며 광주의 일을 다른 지역에 알리려 했으나 계엄군이 길을 막고 신문·방송을 통제(광주는 고립됨), 많은 시민이 희생됨 → 외국인 기자들이 목숨을 걸고 진실을 알림 · 의의: 폭력적인 정부에 맞서 민주주의를 지키려는 시민의 의지를 보여 주었고, 우리나라뿐 아니라 세계 여러 나라의 민주화 운동에 영향을 줌',ARRAY['[6사07-02] 민주화와 산업화의 과정을 주요 사건을 중심으로 살펴보고, 그에 따른 생활 모습의 변화를 탐구한다(차시 머리 주석 기준)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-1-u1-C12','soc',6,1,'u1',7,'6월 민주 항쟁의 원인과 전개 — 간선제(일정 수의 선거인단이 대표를 뽑음)로 대통령이 된 정부가 언론을 통제하고 민주화 운동을 탄압 → 대학생 박종철이 경찰 조사 중 목숨을 잃자 시민들이 직선제(국민이 직접 대표를 뽑음) 개헌(헌법을 고침)을 요구 → 정부는 간선제를 유지하겠다며 거부 → 대학생 이한열이 시위 중 크게 다친 일을 계기로 독재 반대와 직선제를 요구하는 시위가 전국으로 퍼짐 → 정부가 직선제를 포함한 국민의 민주화 요구를 받아들임 · 요구는 그대로였고 달라진 것은 함께한 사람의 수',ARRAY['[6사07-02] 민주화와 산업화의 과정을 주요 사건을 중심으로 살펴보고, 그에 따른 생활 모습의 변화를 탐구한다(차시 머리 주석 기준)']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-1-u1-C13','soc',6,1,'u1',7,'민주화로 달라진 모습 — 6월 민주 항쟁은 여러 분야에 민주적인 제도가 만들어지는 데 큰 역할 · 대통령 직선제 시행(오늘날까지 이어짐), 지방 자치제 다시 시행(지역 주민이 뽑은 대표가 지역의 일을 처리), 시민 단체를 만들어 사회문제 해결에 참여하는 시민 참여 확대 → 시민의 영향력이 커지고 민주주의가 더욱 발전, 시민의 힘으로 민주주의를 지킬 수 있다는 자신감 · 직선제로 치른 선거에 많은 사람이 줄지어 주권(국가의 중요한 일을 결정하는 권리)을 행사',ARRAY['[6사07-02] 민주화와 산업화의 과정을 주요 사건을 중심으로 살펴보고, 그에 따른 생활 모습의 변화를 탐구한다(차시 머리 주석 기준)']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-1-u1-C14','soc',6,1,'u1',8,'시대별 산업의 발달 — 1950년대: 전쟁으로 산업 시설이 파괴되어 여러 나라에서 식량·물자를 지원받고 밀가루·설탕·면직물 등 생활에 필요한 물건을 만드는 산업 발달 → 1960년대: 경제 개발 5개년 계획으로 수출을 통해 농업 중심 산업구조를 공업 중심으로 바꾸려 함, 풍부한 노동력으로 신발·가발·의류 같은 경공업(무게가 적게 나가는 물건) 제품 수출 → 1970년대: 철강·조선·석유 화학 같은 중화학 공업(무게가 많이 나가는 물건과 화학 제품) 발달 → 1980년대: 자동차·정밀 기계·전자 제품 산업 발달, 수출 규모가 커져 국민 소득이 급격히 늘고 생활 수준 향상',ARRAY['[6사07-02] 민주화와 산업화의 과정을 주요 사건을 중심으로 살펴보고, 그에 따른 생활 모습의 변화를 탐구한다(차시 머리 주석 기준)']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-1-u1-C15','soc',6,1,'u1',8,'산업화를 이끈 사람들의 노력 — 정부: 경제 개발 계획, 생산·운반·수출에 필요한 발전소·고속 국도·항만 건설, 교육 시설·연구소 설립, 기업 지원과 대규모 공업 단지 · 독일로 간 광부와 간호사가 벌어들인 외화가 산업화의 밑거름(가족과 나라를 생각하며 힘든 일을 견뎌 냄) · 기업: 세계에서 경쟁하려고 기술을 연구·개발 · 같은 물건(라면)도 시대 상황에 따라 만든 목적이 다름(식량 부족 해결 → 수출 상품)',ARRAY['[6사07-02] 민주화와 산업화의 과정을 주요 사건을 중심으로 살펴보고, 그에 따른 생활 모습의 변화를 탐구한다(차시 머리 주석 기준)']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-1-u1-C16','soc',6,1,'u1',9,'산업화로 달라진 생활 모습 — 짧은 기간의 경제성장 · ① 도시화: 일자리를 찾아 도시로 몰려 도시 인구 급증 → 좁은 땅에 여럿이 사는 아파트 단지 ② 교통의 발달: 지하철 개통, 고속 국도 확대 → 전국이 일일생활권(하루에 볼일을 마치고 되돌아올 수 있는 범위), 고속 국도로 이동 시간이 크게 줄어 지역 간 이동이 활발 ③ 소득 수준 향상: 텔레비전·냉장고·세탁기 등 가전제품 보급, 승용차 보유 증가 ④ 대중 매체(많은 사람에게 정보를 전하는 수단) 보급으로 가요·영화·드라마·스포츠 같은 대중문화 성장',ARRAY['[6사07-02] 민주화와 산업화의 과정을 주요 사건을 중심으로 살펴보고, 그에 따른 생활 모습의 변화를 탐구한다(차시 머리 주석 기준)']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-1-u1-C17','soc',6,1,'u1',9,'산업화로 나타난 문제와 노력 — 도시로 사람이 몰려 일자리와 주택이 부족, 안정된 일자리를 찾지 못한 사람들의 가난한 생활(도시 변두리·달동네) · 도시와 농촌의 소득 격차가 벌어지고 농촌 인구 감소 · 1960~70년대 수출품 가격을 낮춰 경쟁력을 유지하려고 근로자의 권리를 제한하고 임금을 낮게 유지 → 근로자는 열악한 환경에서 장시간 노동·낮은 임금 → 전태일의 편지처럼 많은 사람이 근무 환경 개선·임금 인상 등 근로자의 권리를 보호하려고 노력 · 산업화에는 긍정적인 면과 부정적인 면이 함께 나타남 · 도시 재생 전문가는 낡은 도시를 지역의 문화·역사를 살려 주민과 함께 되살림',ARRAY['[6사07-02] 민주화와 산업화의 과정을 주요 사건을 중심으로 살펴보고, 그에 따른 생활 모습의 변화를 탐구한다(차시 머리 주석 기준)']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-1-u1-C18','soc',6,1,'u1',10,'숨은 글씨 그림으로 표현하기 — 사건에 어울리는 글씨를 떠올리고, 떠오르는 장면 속에 글씨를 숨겨 그리는 활동 · ① 단원에서 공부한 역사적 사건 하나와 관련 낱말 쓰기 ② 그림으로 나타낼 낱말을 정하고 장면 속에 글씨를 어떻게 숨길지 생각하기 ③ 숨긴 글씨는 진하게, 나머지는 색칠해 완성 ④ 친구 그림에서 숨은 글씨를 찾고 느낀 점 나누기 · 장면을 이루는 획이 그대로 글씨의 획이 되게 함 · 사건과 실제로 이어지는 장면을 고름',ARRAY['[6사07-02] 민주화와 산업화의 과정을 주요 사건을 중심으로 살펴보고, 그에 따른 생활 모습의 변화를 탐구한다(차시 머리 주석 기준)']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u1-X01','soc',6,'u1',ARRAY['SO6-1-u1-C1']::text[],'분단의 과정을 거꾸로 안다(6·25 전쟁으로 남북이 처음 나뉘었다고, 광복이 분단을 굳혔다고 여기는 등)','광복 뒤 각각 수립 → 전쟁으로 굳어짐') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u1-X02','soc',6,'u1',ARRAY['SO6-1-u1-C2']::text[],'분단 뒤 시간이 흐르면 남북의 언어·생활 방식 차이가 저절로 줄어든다고 여긴다','시간이 흐를수록 차이는 커져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u1-X03','soc',6,'u1',ARRAY['SO6-1-u1-C2']::text[],'분단 비용을 군대를 유지하는 돈으로만 여겨 자원·길·이산가족의 아픔·국력 같은 갈래를 놓친다','돈으로만 헤아릴 수 없어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u1-X04','soc',6,'u1',ARRAY['SO6-1-u1-C2','SO6-1-u1-C8']::text[],'분단의 문제를 북한 사람 탓으로 돌리거나 북한 사람을 적·이겨야 할 상대로 여긴다','문제는 분단이라는 상황이에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u1-X05','soc',6,'u1',ARRAY['SO6-1-u1-C3']::text[],'분단의 아픔이 담긴 장소와 그 설명을 바꾸어 짝짓거나, 전쟁·분단과 관계없는 곳을 넣는다','전쟁의 흔적 · 분단으로 생긴 곳') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u1-X06','soc',6,'u1',ARRAY['SO6-1-u1-C3']::text[],'비무장 지대의 뜻을 잘못 안다(군대가 모여 있는 곳, 사람이 살 수 없어 생물도 없는 곳으로 여기는 등)','군사 충돌을 막으려는 지대 · 자연이 잘 보전됨') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u1-X07','soc',6,'u1',ARRAY['SO6-1-u1-C4']::text[],'아픔이 담긴 장소는 없애거나 잊어야 한다고 여겨, 평화의 장소로 바꾸는 노력을 놓친다','없애기가 아니라 평화의 장소로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u1-X08','soc',6,'u1',ARRAY['SO6-1-u1-C4']::text[],'답사를 미리 아는 것을 확인하는 일로 여기거나, 의미·사건·시설을 살피는 차례 없이 둘러보기만 한다','가서 알게 되는 일 · 차례대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u1-X09','soc',6,'u1',ARRAY['SO6-1-u1-C5','SO6-1-u1-C6','SO6-1-u1-C7']::text[],'평화 통일 노력과 그 분야(정치·사회문화·경제)를 바꾸어 짝짓는다','약속 · 문화와 교류 · 경제 협력') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u1-X10','soc',6,'u1',ARRAY['SO6-1-u1-C5']::text[],'7·4 남북 공동 성명과 남북 기본 합의서의 내용을 바꾸어 안다','처음 통일 원칙 · 화해·교류와 협력') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u1-X11','soc',6,'u1',ARRAY['SO6-1-u1-C7']::text[],'개성 공업 단지에서 남북이 내놓은 몫(자본과 기술·노동력)을 뒤바꾼다','남한 자본·기술 + 북한 노동력') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u1-X12','soc',6,'u1',ARRAY['SO6-1-u1-C7']::text[],'남북 협력을 한쪽이 일방적으로 돕는 일로 여기거나, 협력의 까닭(장점 결합·왕래·통일의 밑바탕)을 놓친다','두 몫이 나란히 · 서로 잘 살려면') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u1-X13','soc',6,'u1',ARRAY['SO6-1-u1-C8']::text[],'평화 통일은 나라나 어른만 할 일이라 어린이가 일상에서 할 일은 없다고 여긴다','관심 갖기도 실천이에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u1-X14','soc',6,'u1',ARRAY['SO6-1-u1-C8']::text[],'평화 통일을 위한 실천 활동과 그 목적·방법을 잘못 짝짓거나, 남의 노래를 출처 없이 쓴다','인식 · 마음 · 돕기 · 알리기 · 출처 밝히기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u1-X15','soc',6,'u1',ARRAY['SO6-1-u1-C9']::text[],'4·19 혁명의 원인을 잘못 안다(3·15 부정 선거가 아닌 다른 일 때문이라고, 결과를 원인으로 여기는 등)','장기 집권 → 3·15 부정 선거') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u1-X16','soc',6,'u1',ARRAY['SO6-1-u1-C9']::text[],'4·19 혁명의 전개 차례를 뒤바꾸거나, 일부 사람(대학생만)이 참여했다고 여긴다','대구 학생 → 부정 선거 → 전국 시위 → 물러남 · 각계각층') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u1-X17','soc',6,'u1',ARRAY['SO6-1-u1-C10']::text[],'4·19 혁명의 결과·의의를 잘못 안다(부정 선거 결과가 인정되었다고, 민주주의와 관계없다고 여기는 등)','정권이 물러남 · 민주주의의 밑거름') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u1-X18','soc',6,'u1',ARRAY['SO6-1-u1-C11']::text[],'5·18 민주화 운동의 원인을 다른 사건과 섞는다(부정 선거 때문이라고, 직선제를 요구했다고 여기는 등)','군인들의 정변과 권력 장악') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u1-X19','soc',6,'u1',ARRAY['SO6-1-u1-C11']::text[],'5·18 민주화 운동에서 시민과 계엄군이 한 일을 바꾸어 안다(계엄군이 광주의 일을 알렸다고 여기는 등)','알리려 한 쪽 · 막은 쪽') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u1-X20','soc',6,'u1',ARRAY['SO6-1-u1-C11']::text[],'5·18 민주화 운동의 의의를 한 도시의 일로만 여겨 세계 민주화 운동에 준 영향을 놓친다','시민의 의지 · 세계에도 영향') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u1-X21','soc',6,'u1',ARRAY['SO6-1-u1-C12']::text[],'간선제와 직선제의 뜻을 바꾸어 안다','간선제 — 선거인단 · 직선제 — 국민이 직접') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u1-X22','soc',6,'u1',ARRAY['SO6-1-u1-C12']::text[],'6월 민주 항쟁의 요구와 정부의 대응을 잘못 안다(간선제를 요구했다고, 처음부터 받아들였다고 여기는 등)','직선제 개헌 요구 → 거부 → 전국 시위 → 받아들임') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u1-X23','soc',6,'u1',ARRAY['SO6-1-u1-C13']::text[],'6월 민주 항쟁으로 달라진 모습(직선제·지방 자치제·시민 참여)을 놓치거나 그전 모습과 바꾼다','직선제 · 지방 자치제 · 시민 참여') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u1-X24','soc',6,'u1',ARRAY['SO6-1-u1-C9','SO6-1-u1-C11','SO6-1-u1-C12']::text[],'세 민주화 운동(4·19 혁명·5·18 민주화 운동·6월 민주 항쟁)의 원인·결과·차례를 서로 섞는다','부정 선거 → 정변 → 직선제 요구') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u1-X25','soc',6,'u1',ARRAY['SO6-1-u1-C14']::text[],'경공업과 중화학 공업의 뜻이나 예를 바꾸어 안다','가벼운 물건 · 무거운 물건과 화학 제품') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u1-X26','soc',6,'u1',ARRAY['SO6-1-u1-C14']::text[],'시대별 산업 발달의 차례를 뒤바꾼다(중화학 공업이 경공업보다 먼저라고 여기는 등)','생활용품 → 경공업 → 중화학 → 자동차·전자') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u1-X27','soc',6,'u1',ARRAY['SO6-1-u1-C15']::text[],'산업화를 정부나 기업 한쪽만 이룬 일로 여겨, 기반 시설·근로자·기술 개발 같은 여러 사람의 노력을 놓친다','정부 · 근로자 · 기업이 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u1-X28','soc',6,'u1',ARRAY['SO6-1-u1-C16']::text[],'산업화로 달라진 생활 모습(도시화·교통·소득·대중문화)을 놓치거나 거꾸로 안다(사람들이 농촌으로 몰렸다고 여기는 등)','도시로 · 일일생활권 · 가전 · 대중문화') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u1-X29','soc',6,'u1',ARRAY['SO6-1-u1-C16','SO6-1-u1-C17']::text[],'산업화에 좋은 점만 있었다고, 또는 나쁜 점만 있었다고 한쪽으로만 본다','밝은 면과 그늘이 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u1-X30','soc',6,'u1',ARRAY['SO6-1-u1-C17']::text[],'산업화 시기 근로자의 어려움과 그 까닭(수출품 가격을 낮추려 임금을 낮게 유지)을 잘못 알거나, 권리를 지키려는 노력을 놓친다','낮은 임금·긴 노동 · 권리를 지키려는 노력') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u1-X31','soc',6,'u1',ARRAY['SO6-1-u1-C9','SO6-1-u1-C10','SO6-1-u1-C14']::text[],'역사 공부를 연도·숫자를 외우는 것으로 여겨 원인과 결과를 되짚는 것을 놓친다','외우기보다 왜 그렇게 되었는지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u1-X32','soc',6,'u1',ARRAY['SO6-1-u1-C18']::text[],'숨은 글씨 그림의 방법을 잘못 안다(그림만 그리거나 글씨만 쓰고, 사건과 관계없는 장면을 고르거나, 숨긴 글씨를 흐리게 하는 등)','사건 → 낱말 → 장면 속에 숨기기 → 진하게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L01_basic#1','soc',6,1,'u1','L01','g6_1_soc_u1_L01_basic','lesson_basic','SO6-1-u1-C1',1,'mc','auto','광복 이후 남과 북에 각각 정부가 세워지며 나뉜 우리나라의 분단이 더욱 굳어지게 된 일은 무엇인가요?',ARRAY['SO6-1-u1-X01']::text[],false,'{"seq":1,"concept":"SO6-1-u1-C1","difficulty":1,"kind":"mc","stem":"광복 이후 남과 북에 각각 정부가 세워지며 나뉜 우리나라의 분단이 더욱 굳어지게 된 일은 무엇인가요?","options":[{"t":"6·25 전쟁","correct":true},{"t":"금강산 수학여행","mis":"SO6-1-u1-X01"},{"t":"도시 건설","mis":"SO6-1-u1-X01"},{"t":"국어사전 만들기","mis":"SO6-1-u1-X01"}],"explanation":["나뉜 뒤에 일어난 큰일이에요.","전쟁을 겪으며 굳어졌어요.","6·25 전쟁이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L01_basic#2','soc',6,1,'u1','L01','g6_1_soc_u1_L01_basic','lesson_basic','SO6-1-u1-C2',1,'sa','auto','분단으로 고향을 잃어 고향에 갈 수 없게 된 사람을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-1-u1-C2","difficulty":1,"kind":"sa","stem":"분단으로 고향을 잃어 고향에 갈 수 없게 된 사람을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["실향민"],"explanation":["고향을 잃은 사람이에요.","실◯민이에요.","실향민이에요."],"mis":"SO6-1-u1-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L01_basic#3','soc',6,1,'u1','L01','g6_1_soc_u1_L01_basic','lesson_basic','SO6-1-u1-C2',1,'mc','auto','나라를 지키고 군대를 유지하는 데 드는 모든 비용을 무엇이라고 하나요?',ARRAY['SO6-1-u1-X03']::text[],false,'{"seq":3,"concept":"SO6-1-u1-C2","difficulty":1,"kind":"mc","stem":"나라를 지키고 군대를 유지하는 데 드는 모든 비용을 무엇이라고 하나요?","options":[{"t":"국방비","correct":true},{"t":"급식비","mis":"SO6-1-u1-X03"},{"t":"교통비","mis":"SO6-1-u1-X03"},{"t":"관람료","mis":"SO6-1-u1-X03"}],"explanation":["나라를 지키는 데 써요.","군대를 유지하는 데 들어요.","국방비예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L01_basic#4','soc',6,1,'u1','L01','g6_1_soc_u1_L01_basic','lesson_basic','SO6-1-u1-C2',1,'ox','auto','분단으로 가족이 남과 북에 흩어져 만나지 못하는 이산가족의 아픔은 지금도 이어지고 있어요.',ARRAY['SO6-1-u1-X02']::text[],false,'{"seq":4,"concept":"SO6-1-u1-C2","difficulty":1,"kind":"ox","stem":"분단으로 가족이 남과 북에 흩어져 만나지 못하는 이산가족의 아픔은 지금도 이어지고 있어요.","answer":"O","reason_options":[{"t":"분단 때문에 가족이 서로 자유롭게 오갈 수 없기 때문에","correct":true},{"t":"분단 뒤 가족들이 모두 자유롭게 만나고 있기 때문에","mis":"SO6-1-u1-X02"}],"mis":"SO6-1-u1-X02","explanation":["가족이 흩어졌어요.","자유롭게 오갈 수 없어요.","아픔이 이어지고 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L01_basic#5','soc',6,1,'u1','L01','g6_1_soc_u1_L01_basic','lesson_basic','SO6-1-u1-C2',2,'match','auto','남한에서 부르는 말과 북한에서 부르는 말을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO6-1-u1-C2","difficulty":2,"kind":"match","stem":"남한에서 부르는 말과 북한에서 부르는 말을 알맞게 이으세요.","pairs":[{"l":"도넛","r":"가락지빵"},{"l":"삼겹살","r":"돼지세겹살"},{"l":"주스","r":"과일단물"},{"l":"양파","r":"둥글파"}],"mis":"SO6-1-u1-X02","explanation":["같은 것을 다르게 불러요.","북한은 특징을 순우리말로 많이 나타내요.","차이가 커지고 있어요."],"asset":{"type":"passage","lines":["남한 「도넛」 — 북한 「가락지빵」","남한 「삼겹살」 — 북한 「돼지세겹살」","남한 「주스」 — 북한 「과일단물」","남한 「양파」 — 북한 「둥글파」"],"title":"같은 것을 다르게 부르는 남북의 말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L01_basic#6','soc',6,1,'u1','L01','g6_1_soc_u1_L01_basic','lesson_basic','SO6-1-u1-C2',2,'mc','auto','남과 북의 말 차이가 계속 커진다면 어떤 일이 생길까요?',ARRAY['SO6-1-u1-X02']::text[],false,'{"seq":6,"concept":"SO6-1-u1-C2","difficulty":2,"kind":"mc","stem":"남과 북의 말 차이가 계속 커진다면 어떤 일이 생길까요?","options":[{"t":"같은 민족인데도 서로 의사소통하기 어려워진다","correct":true},{"t":"두 곳의 말이 저절로 같아진다","mis":"SO6-1-u1-X02"},{"t":"말이 달라도 아무 일도 생기지 않는다","mis":"SO6-1-u1-X02"},{"t":"한쪽 말이 저절로 사라진다","mis":"SO6-1-u1-X02"}],"explanation":["같은 것을 다르게 불러요.","차이가 쌓이면 알아듣기 어려워요.","의사소통이 어려워져요."],"asset":{"type":"passage","lines":["남한 「도넛」 — 북한 「가락지빵」","남한 「삼겹살」 — 북한 「돼지세겹살」","남한 「주스」 — 북한 「과일단물」","남한 「양파」 — 북한 「둥글파」"],"title":"같은 것을 다르게 부르는 남북의 말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L01_basic#7','soc',6,1,'u1','L01','g6_1_soc_u1_L01_basic','lesson_basic','SO6-1-u1-C1',2,'mc','auto','세 친구의 말 가운데 분단의 과정을 바르게 말한 친구끼리 묶은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X01']::text[],false,'{"seq":7,"concept":"SO6-1-u1-C1","difficulty":2,"kind":"mc","stem":"세 친구의 말 가운데 분단의 과정을 바르게 말한 친구끼리 묶은 것은 어느 것인가요?","options":[{"t":"친구 나, 친구 다","correct":true},{"t":"친구 가, 친구 나","mis":"SO6-1-u1-X01"},{"t":"친구 가, 친구 다","mis":"SO6-1-u1-X01"},{"t":"친구 가, 친구 나, 친구 다","mis":"SO6-1-u1-X01"}],"explanation":["나뉜 것은 광복 뒤예요.","전쟁은 분단을 굳혔어요.","친구 가의 말이 틀렸어요."],"asset":{"type":"speech","turns":[{"who":"친구 가","text":"분단은 6·25 전쟁 때 처음 시작됐어."},{"who":"친구 나","text":"광복 뒤에 남과 북에 따로 정부가 세워지며 나뉘었어."},{"who":"친구 다","text":"나뉜 뒤 전쟁을 겪으면서 분단이 더 굳어졌지."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L01_basic#8','soc',6,1,'u1','L01','g6_1_soc_u1_L01_basic','lesson_basic','SO6-1-u1-C2',2,'blank','auto','분단 이후 70여 년이 흐르면서 남과 북의 생활 방식과 (    ) 등의 차이가 커지고 있어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-1-u1-X02']::text[],false,'{"seq":8,"concept":"SO6-1-u1-C2","difficulty":2,"kind":"blank","stem":"분단 이후 70여 년이 흐르면서 남과 북의 생활 방식과 (    ) 등의 차이가 커지고 있어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"언어","correct":true},{"t":"기후","mis":"SO6-1-u1-X02"},{"t":"지형","mis":"SO6-1-u1-X02"},{"t":"계절","mis":"SO6-1-u1-X02"}],"explanation":["말이 달라졌어요.","도넛과 가락지빵처럼요.","언어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L01_basic#9','soc',6,1,'u1','L01','g6_1_soc_u1_L01_basic','lesson_basic','SO6-1-u1-C2',2,'mc','auto','분단으로 나타난 문제점으로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X02','SO6-1-u1-X03']::text[],false,'{"seq":9,"concept":"SO6-1-u1-C2","difficulty":2,"kind":"mc","stem":"분단으로 나타난 문제점으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"남북의 생활 방식이 점점 똑같아지고 있다","correct":true},{"t":"실향민과 이산가족의 아픔이 이어진다","mis":"SO6-1-u1-X02"},{"t":"전쟁의 긴장감이 이어진다","mis":"SO6-1-u1-X02"},{"t":"많은 국방비를 지출한다","mis":"SO6-1-u1-X03"}],"explanation":["차이는 커지고 있어요.","똑같아지는 것이 아니에요.","나머지 셋은 문제점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L01_basic#10','soc',6,1,'u1','L01','g6_1_soc_u1_L01_basic','lesson_basic','SO6-1-u1-C2',3,'error','auto','분단으로 나타난 문제를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u1-X04','SO6-1-u1-X03','SO6-1-u1-X02']::text[],false,'{"seq":10,"concept":"SO6-1-u1-C2","difficulty":3,"kind":"error","stem":"분단으로 나타난 문제를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「분단의 문제는 북한 사람들이 나빠서 생긴 거야.」","correct":true,"mis_target":"SO6-1-u1-X04"},{"t":"친구 가 — 「분단 때문에 많은 국방비를 쓰고 있어.」","mis":"SO6-1-u1-X03"},{"t":"친구 나 — 「고향에 가지 못하는 실향민의 아픔이 있어.」","mis":"SO6-1-u1-X02"}],"explanation":["문제는 분단이라는 상황이에요.","사람을 탓하는 것이 아니에요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L01_challenge#1','soc',6,1,'u1','L01','g6_1_soc_u1_L01_challenge','lesson_challenge','SO6-1-u1-C2',2,'sa','auto','북한에서 「과일단물」이라고 부르는 것을 남한에서는 무엇이라고 부르나요?','{}'::text[],false,'{"seq":1,"concept":"SO6-1-u1-C2","difficulty":2,"kind":"sa","stem":"북한에서 「과일단물」이라고 부르는 것을 남한에서는 무엇이라고 부르나요?","answer":["주스"],"explanation":["과일로 만든 단 물이에요.","남한에서는 외래어로 불러요.","주스예요."],"mis":"SO6-1-u1-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L01_challenge#2','soc',6,1,'u1','L01','g6_1_soc_u1_L01_challenge','lesson_challenge','SO6-1-u1-C2',2,'ox','auto','분단 비용은 군대를 유지하는 데 드는 돈만을 가리켜요.',ARRAY['SO6-1-u1-X03']::text[],false,'{"seq":2,"concept":"SO6-1-u1-C2","difficulty":2,"kind":"ox","stem":"분단 비용은 군대를 유지하는 데 드는 돈만을 가리켜요.","answer":"X","reason_options":[{"t":"자원을 쓰지 못하는 비용, 돌아가며 드는 비용, 이산가족의 아픔까지 여러 갈래가 있기 때문에","correct":true},{"t":"분단 비용은 돈으로만 셀 수 있기 때문에","mis":"SO6-1-u1-X03"}],"mis":"SO6-1-u1-X03","explanation":["여러 갈래가 있어요.","아픔과 국력도 들어가요.","돈만이 아니에요."],"asset":{"type":"passage","lines":["㉠ 나라를 지키고 군대를 유지하는 데 드는 비용","㉡ 북한 지역의 자원을 함께 쓰지 못해 생기는 비용","㉢ 대륙으로 길이 이어지지 않아 멀리 돌아가며 드는 비용","㉣ 가족을 만나지 못하는 이산가족의 아픔","㉤ 힘을 모으지 못해 약해진 국력"],"title":"분단 비용 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L01_challenge#3','soc',6,1,'u1','L01','g6_1_soc_u1_L01_challenge','lesson_challenge','SO6-1-u1-C2',3,'mc','auto','분단 비용 메모에서 돈으로만 헤아리기 어려운 것끼리 묶은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X03']::text[],false,'{"seq":3,"concept":"SO6-1-u1-C2","difficulty":3,"kind":"mc","stem":"분단 비용 메모에서 돈으로만 헤아리기 어려운 것끼리 묶은 것은 어느 것인가요?","options":[{"t":"㉣, ㉤","correct":true},{"t":"㉠, ㉡","mis":"SO6-1-u1-X03"},{"t":"㉡, ㉢","mis":"SO6-1-u1-X03"},{"t":"㉠, ㉢","mis":"SO6-1-u1-X03"}],"explanation":["㉠~㉢은 비용으로 셀 수 있어요.","아픔과 국력은 돈으로 다 셀 수 없어요.","㉣, ㉤이에요."],"asset":{"type":"passage","lines":["㉠ 나라를 지키고 군대를 유지하는 데 드는 비용","㉡ 북한 지역의 자원을 함께 쓰지 못해 생기는 비용","㉢ 대륙으로 길이 이어지지 않아 멀리 돌아가며 드는 비용","㉣ 가족을 만나지 못하는 이산가족의 아픔","㉤ 힘을 모으지 못해 약해진 국력"],"title":"분단 비용 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L01_challenge#4','soc',6,1,'u1','L01','g6_1_soc_u1_L01_challenge','lesson_challenge','SO6-1-u1-C1',3,'mc','auto','옛날에는 금강산으로 수학여행을 갔지만 오늘날에는 마음대로 갈 수 없는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X01']::text[],false,'{"seq":4,"concept":"SO6-1-u1-C1","difficulty":3,"kind":"mc","stem":"옛날에는 금강산으로 수학여행을 갔지만 오늘날에는 마음대로 갈 수 없는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"남과 북이 분단되어 자유롭게 오갈 수 없기 때문에","correct":true},{"t":"금강산이 사라졌기 때문에","mis":"SO6-1-u1-X01"},{"t":"수학여행이 법으로 금지되었기 때문에","mis":"SO6-1-u1-X01"},{"t":"금강산까지 가는 길이 원래 없었기 때문에","mis":"SO6-1-u1-X01"}],"explanation":["금강산은 지금도 있어요.","분단으로 오가기 어려워요.","그래서 갈 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L01_challenge#5','soc',6,1,'u1','L01','g6_1_soc_u1_L01_challenge','lesson_challenge','SO6-1-u1-C2',3,'mc','auto','분단 비용 메모의 ㉢이 생기는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X03']::text[],false,'{"seq":5,"concept":"SO6-1-u1-C2","difficulty":3,"kind":"mc","stem":"분단 비용 메모의 ㉢이 생기는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"남북이 막혀 있어 육로로 대륙에 바로 갈 수 없기 때문에","correct":true},{"t":"대륙에는 길이 하나도 없기 때문에","mis":"SO6-1-u1-X03"},{"t":"바다로 가는 것이 법으로 금지되었기 때문에","mis":"SO6-1-u1-X03"},{"t":"군대를 유지하는 비용이기 때문에","mis":"SO6-1-u1-X03"}],"explanation":["㉢은 길에 관한 비용이에요.","분단으로 북쪽 길이 막혔어요.","그래서 돌아가요."],"asset":{"type":"passage","lines":["㉠ 나라를 지키고 군대를 유지하는 데 드는 비용","㉡ 북한 지역의 자원을 함께 쓰지 못해 생기는 비용","㉢ 대륙으로 길이 이어지지 않아 멀리 돌아가며 드는 비용","㉣ 가족을 만나지 못하는 이산가족의 아픔","㉤ 힘을 모으지 못해 약해진 국력"],"title":"분단 비용 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L01_challenge#6','soc',6,1,'u1','L01','g6_1_soc_u1_L01_challenge','lesson_challenge','SO6-1-u1-C1',3,'ox','auto','6·25 전쟁이 남북이 처음 나뉘게 된 일이고, 광복은 그 분단을 굳힌 일이에요.',ARRAY['SO6-1-u1-X01']::text[],false,'{"seq":6,"concept":"SO6-1-u1-C1","difficulty":3,"kind":"ox","stem":"6·25 전쟁이 남북이 처음 나뉘게 된 일이고, 광복은 그 분단을 굳힌 일이에요.","answer":"X","reason_options":[{"t":"광복 뒤 남북에 따로 정부가 세워지며 나뉘었고, 전쟁이 그 분단을 굳혔기 때문에","correct":true},{"t":"광복은 전쟁보다 나중에 일어난 일이기 때문에","mis":"SO6-1-u1-X01"}],"mis":"SO6-1-u1-X01","explanation":["먼저 나뉘었어요.","그다음 전쟁으로 굳어졌어요.","차례가 거꾸로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L01_challenge#7','soc',6,1,'u1','L01','g6_1_soc_u1_L01_challenge','lesson_challenge','SO6-1-u1-C2',3,'error','auto','남북의 말 차이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u1-X02']::text[],false,'{"seq":7,"concept":"SO6-1-u1-C2","difficulty":3,"kind":"error","stem":"남북의 말 차이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「시간이 지나면 남북의 말은 저절로 같아질 거야.」","correct":true,"mis_target":"SO6-1-u1-X02"},{"t":"친구 가 — 「같은 것을 서로 다르게 부르는 말이 늘고 있어.」","mis":"SO6-1-u1-X02"},{"t":"친구 다 — 「이대로면 서로 외국어처럼 느낄 수도 있겠어.」","mis":"SO6-1-u1-X02"}],"explanation":["차이는 커지고 있어요.","저절로 같아지지 않아요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L01_challenge#8','soc',6,1,'u1','L01','g6_1_soc_u1_L01_challenge','lesson_challenge','SO6-1-u1-C4',4,'mc','auto','분단으로 나타난 문제점을 대하는 태도로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X04','SO6-1-u1-X03','SO6-1-u1-X02']::text[],false,'{"seq":8,"concept":"SO6-1-u1-C4","difficulty":4,"kind":"mc","stem":"분단으로 나타난 문제점을 대하는 태도로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"분단이라는 상황이 남과 북 모두에게 아픔을 준다고 보고 함께 풀어 갈 길을 생각한다","correct":true},{"t":"북한 사람을 이겨야 할 상대로 여기고 멀리한다","mis":"SO6-1-u1-X04"},{"t":"분단 비용은 국방비뿐이니 다른 문제는 생각하지 않는다","mis":"SO6-1-u1-X03"},{"t":"시간이 흐르면 차이가 저절로 줄어드니 그대로 둔다","mis":"SO6-1-u1-X02"}],"explanation":["문제는 상황이에요.","여러 갈래를 함께 봐요.","함께 풀어 갈 길을 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L01_challenge#9','soc',6,1,'u1','L01','g6_1_soc_u1_L01_challenge','lesson_challenge','SO6-1-u1-C2',4,'mc','auto','분단으로 나타난 네 가지 문제점을 가장 바르게 정리한 것은 어느 것인가요?',ARRAY['SO6-1-u1-X02','SO6-1-u1-X03']::text[],false,'{"seq":9,"concept":"SO6-1-u1-C2","difficulty":4,"kind":"mc","stem":"분단으로 나타난 네 가지 문제점을 가장 바르게 정리한 것은 어느 것인가요?","options":[{"t":"실향민·이산가족의 아픔, 커지는 생활 방식과 언어 차이, 전쟁의 긴장감, 많은 국방비 지출","correct":true},{"t":"실향민의 아픔, 줄어드는 언어 차이, 평화로운 분위기, 줄어드는 국방비","mis":"SO6-1-u1-X02"},{"t":"이산가족의 만남, 같아지는 생활 방식, 전쟁의 긴장감, 국방비 지출","mis":"SO6-1-u1-X02"},{"t":"많은 국방비 지출 하나뿐","mis":"SO6-1-u1-X03"}],"explanation":["아픔과 차이가 있어요.","긴장감과 국방비도 있어요.","네 가지를 함께 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L01_challenge#10','soc',6,1,'u1','L01','g6_1_soc_u1_L01_challenge','lesson_challenge','SO6-1-u1-C2',4,'essay','teacher','분단으로 나타난 문제점 두 가지를 쓰고, 분단 비용이 돈으로만 헤아릴 수 없는 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-1-u1-C2","difficulty":4,"kind":"essay","stem":"분단으로 나타난 문제점 두 가지를 쓰고, 분단 비용이 돈으로만 헤아릴 수 없는 까닭을 쓰세요.","answer_guide":{"answer":"예: 분단으로 실향민과 이산가족이 고향과 가족을 만나지 못하는 아픔을 겪고, 남북의 언어와 생활 방식의 차이가 커지고 있다. 분단 비용에는 군대를 유지하는 돈뿐 아니라 가족을 만나지 못하는 아픔과 힘을 모으지 못해 약해진 국력처럼 돈으로 셀 수 없는 것도 들어가기 때문이다.","scoring_points":["문제점 두 가지를 썼는가","돈으로 셀 수 없는 분단 비용을 썼는가","까닭을 이어 썼는가"]},"explanation":["아픔과 차이를 떠올려요.","분단 비용은 여러 갈래예요.","돈으로 셀 수 없는 것을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L02_basic#1','soc',6,1,'u1','L02','g6_1_soc_u1_L02_basic','lesson_basic','SO6-1-u1-C3',1,'mc','auto','6·25 전쟁 이후 한반도를 가로지르며 설치된 것은 무엇인가요?',ARRAY['SO6-1-u1-X05']::text[],false,'{"seq":1,"concept":"SO6-1-u1-C3","difficulty":1,"kind":"mc","stem":"6·25 전쟁 이후 한반도를 가로지르며 설치된 것은 무엇인가요?","options":[{"t":"휴전선","correct":true},{"t":"아바이 마을","mis":"SO6-1-u1-X05"},{"t":"평화 공원","mis":"SO6-1-u1-X05"},{"t":"고속 국도","mis":"SO6-1-u1-X05"}],"explanation":["한반도를 가로질러요.","전쟁 뒤에 생겼어요.","휴전선이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L02_basic#2','soc',6,1,'u1','L02','g6_1_soc_u1_L02_basic','lesson_basic','SO6-1-u1-C3',1,'mc','auto','전쟁 중 피란 왔다가 고향에 돌아가지 못한 사람들이 모여 살면서 만들어진 마을은 어느 것인가요?',ARRAY['SO6-1-u1-X05','SO6-1-u1-X07']::text[],false,'{"seq":2,"concept":"SO6-1-u1-C3","difficulty":1,"kind":"mc","stem":"전쟁 중 피란 왔다가 고향에 돌아가지 못한 사람들이 모여 살면서 만들어진 마을은 어느 것인가요?","options":[{"t":"아바이 마을","correct":true},{"t":"백마고지 전적지","mis":"SO6-1-u1-X05"},{"t":"DMZ 평화의 길","mis":"SO6-1-u1-X07"},{"t":"판문점","mis":"SO6-1-u1-X05"}],"explanation":["「아바이」는 아버지를 뜻하는 사투리예요.","돌아가지 못한 사람들이 모였어요.","아바이 마을이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L02_basic#3','soc',6,1,'u1','L02','g6_1_soc_u1_L02_basic','lesson_basic','SO6-1-u1-C4',1,'sa','auto','정전 협정 체결과 남북 정상 회담이 있었던 곳으로, 분단과 평화의 상징이 되는 장소는 어디인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO6-1-u1-C4","difficulty":1,"kind":"sa","stem":"정전 협정 체결과 남북 정상 회담이 있었던 곳으로, 분단과 평화의 상징이 되는 장소는 어디인가요? 세 글자로 쓰세요.","answer":["판문점"],"explanation":["남북이 만나는 장소예요.","회담이 열렸어요.","판문점이에요."],"mis":"SO6-1-u1-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L02_basic#4','soc',6,1,'u1','L02','g6_1_soc_u1_L02_basic','lesson_basic','SO6-1-u1-C4',1,'ox','auto','우리나라는 분단의 아픔이 담긴 장소를 평화의 장소로 바꾸려고 노력하고 있어요.',ARRAY['SO6-1-u1-X07']::text[],false,'{"seq":4,"concept":"SO6-1-u1-C4","difficulty":1,"kind":"ox","stem":"우리나라는 분단의 아픔이 담긴 장소를 평화의 장소로 바꾸려고 노력하고 있어요.","answer":"O","reason_options":[{"t":"DMZ 평화의 길이나 평화 공원처럼 평화의 뜻을 알리는 곳으로 가꾸고 있기 때문에","correct":true},{"t":"아픔이 담긴 장소는 모두 없애 버렸기 때문에","mis":"SO6-1-u1-X07"}],"mis":"SO6-1-u1-X07","explanation":["없애지 않았어요.","평화의 장소로 가꾸어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L02_basic#5','soc',6,1,'u1','L02','g6_1_soc_u1_L02_basic','lesson_basic','SO6-1-u1-C3',2,'match','auto','장소 카드를 보고 카드와 장소 이름을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO6-1-u1-C3","difficulty":2,"kind":"match","stem":"장소 카드를 보고 카드와 장소 이름을 알맞게 이으세요.","pairs":[{"l":"㉮","r":"휴전선"},{"l":"㉯","r":"아바이 마을"},{"l":"㉰","r":"백마고지 전적지"},{"l":"㉱","r":"장사 상륙 작전 전승 기념관"}],"mis":"SO6-1-u1-X05","explanation":["㉮는 한반도를 가로질러요.","㉯는 돌아가지 못한 사람들의 마을이에요.","㉰는 전투, ㉱는 학생 신분 참전이에요."],"asset":{"type":"passage","lines":["㉮ 전쟁이 끝난 뒤 한반도를 가로질러 놓인 선","㉯ 피란 왔다가 고향에 돌아가지 못한 사람들이 모여 이룬 마을","㉰ 큰 전투가 있었던 곳에 희생된 군인을 기리는 기념관과 기념비","㉱ 학생 신분으로 참전한 군인들을 추모하는 기념관"],"title":"분단의 아픔이 담긴 장소 카드 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L02_basic#6','soc',6,1,'u1','L02','g6_1_soc_u1_L02_basic','lesson_basic','SO6-1-u1-C4',2,'mc','auto','비무장 지대의 일부 구간을 남과 북의 합의로 열어 사람들이 관람할 수 있게 만든 것은 어느 것인가요?',ARRAY['SO6-1-u1-X05','SO6-1-u1-X06']::text[],false,'{"seq":6,"concept":"SO6-1-u1-C4","difficulty":2,"kind":"mc","stem":"비무장 지대의 일부 구간을 남과 북의 합의로 열어 사람들이 관람할 수 있게 만든 것은 어느 것인가요?","options":[{"t":"DMZ 평화의 길","correct":true},{"t":"아바이 마을","mis":"SO6-1-u1-X05"},{"t":"백마고지 전적지","mis":"SO6-1-u1-X05"},{"t":"휴전선","mis":"SO6-1-u1-X06"}],"explanation":["남북이 합의했어요.","일부 구간을 열었어요.","DMZ 평화의 길이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L02_basic#7','soc',6,1,'u1','L02','g6_1_soc_u1_L02_basic','lesson_basic','SO6-1-u1-C3',2,'mc','auto','분단의 아픔이 담긴 장소로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X05']::text[],false,'{"seq":7,"concept":"SO6-1-u1-C3","difficulty":2,"kind":"mc","stem":"분단의 아픔이 담긴 장소로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"새로 문을 연 놀이공원","correct":true},{"t":"휴전선","mis":"SO6-1-u1-X05"},{"t":"아바이 마을","mis":"SO6-1-u1-X05"},{"t":"장사 상륙 작전 전승 기념관","mis":"SO6-1-u1-X05"}],"explanation":["전쟁의 흔적이 남은 곳이에요.","분단으로 생긴 곳이기도 해요.","놀이공원은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L02_basic#8','soc',6,1,'u1','L02','g6_1_soc_u1_L02_basic','lesson_basic','SO6-1-u1-C3',2,'ox','auto','비무장 지대에는 자연환경이 잘 보전되어 희귀한 식물과 멸종 위기 동물이 살고 있어요.',ARRAY['SO6-1-u1-X06']::text[],false,'{"seq":8,"concept":"SO6-1-u1-C3","difficulty":2,"kind":"ox","stem":"비무장 지대에는 자연환경이 잘 보전되어 희귀한 식물과 멸종 위기 동물이 살고 있어요.","answer":"O","reason_options":[{"t":"사람의 손이 거의 닿지 않아 자연이 그대로 남았기 때문에","correct":true},{"t":"군대가 많이 모여 있어 생물이 살 수 없기 때문에","mis":"SO6-1-u1-X06"}],"mis":"SO6-1-u1-X06","explanation":["사람의 손이 덜 닿았어요.","자연이 잘 남았어요.","희귀 생물이 살아요."],"asset":{"type":"passage","lines":["정전 협정에 따라 남과 북 사이에 정해 둔 지대이다.","군사 충돌을 막으려고 군사적 행위를 원칙적으로 하지 않는다.","사람의 손이 거의 닿지 않아 자연환경이 잘 보전되어 있다.","희귀한 식물과 멸종 위기의 야생 동물이 살고 있다."],"title":"비무장 지대 알아보기 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L02_basic#9','soc',6,1,'u1','L02','g6_1_soc_u1_L02_basic','lesson_basic','SO6-1-u1-C4',2,'mc','auto','통일이 된 뒤 비무장 지대를 평화의 장소로 쓰는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X07']::text[],false,'{"seq":9,"concept":"SO6-1-u1-C4","difficulty":2,"kind":"mc","stem":"통일이 된 뒤 비무장 지대를 평화의 장소로 쓰는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"자연을 살린 평화 생태 학습 공간으로 꾸민다","correct":true},{"t":"다시 군사 시설로만 쓴다","mis":"SO6-1-u1-X07"},{"t":"흔적을 모두 지우고 잊는다","mis":"SO6-1-u1-X07"},{"t":"사람이 들어갈 수 없게 영원히 막는다","mis":"SO6-1-u1-X07"}],"explanation":["자연이 잘 보전되어 있어요.","평화의 뜻을 살려요.","평화 생태 학습 공간이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L02_basic#10','soc',6,1,'u1','L02','g6_1_soc_u1_L02_basic','lesson_basic','SO6-1-u1-C4',3,'mc','auto','인터넷 답사 수첩 ㉠~㉤을 알맞은 차례로 늘어놓은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X08']::text[],false,'{"seq":10,"concept":"SO6-1-u1-C4","difficulty":3,"kind":"mc","stem":"인터넷 답사 수첩 ㉠~㉤을 알맞은 차례로 늘어놓은 것은 어느 것인가요?","options":[{"t":"㉡ → ㉣ → ㉢ → ㉤ → ㉠","correct":true},{"t":"㉠ → ㉡ → ㉢ → ㉣ → ㉤","mis":"SO6-1-u1-X08"},{"t":"㉤ → ㉠ → ㉡ → ㉣ → ㉢","mis":"SO6-1-u1-X08"},{"t":"㉡ → ㉠ → ㉤ → ㉢ → ㉣","mis":"SO6-1-u1-X08"}],"explanation":["먼저 장소를 고르고 누리집에 가요.","의미 → 사건 → 시설을 봐요.","시설이 어떤 곳인지 마지막에 확인해요."],"asset":{"type":"passage","lines":["㉠ 주요 시설들이 각각 어떤 곳인지 확인한다.","㉡ 답사할 장소를 고르고 그 누리집을 방문한다.","㉢ 그곳에서 일어났던 사건들을 살펴본다.","㉣ 그곳이 어떤 의미가 있는 장소인지 알아본다.","㉤ 그곳의 주요 시설들을 살펴본다."],"title":"뒤섞인 인터넷 답사 수첩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L02_challenge#1','soc',6,1,'u1','L02','g6_1_soc_u1_L02_challenge','lesson_challenge','SO6-1-u1-C3',2,'sa','auto','정전 협정에 따라 군사 충돌을 막으려고 남과 북 사이에 정해 둔 지대를 무엇이라고 하나요? 다섯 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-1-u1-C3","difficulty":2,"kind":"sa","stem":"정전 협정에 따라 군사 충돌을 막으려고 남과 북 사이에 정해 둔 지대를 무엇이라고 하나요? 다섯 글자로 쓰세요.","answer":["비무장 지대","비무장지대"],"explanation":["무장을 하지 않는 곳이에요.","군사적 행위를 하지 않아요.","비무장 지대예요."],"mis":"SO6-1-u1-X06"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L02_challenge#2','soc',6,1,'u1','L02','g6_1_soc_u1_L02_challenge','lesson_challenge','SO6-1-u1-C3',2,'mc','auto','장소 카드 ㉰와 ㉱에 공통으로 담긴 마음은 어느 것인가요?',ARRAY['SO6-1-u1-X05','SO6-1-u1-X07']::text[],false,'{"seq":2,"concept":"SO6-1-u1-C3","difficulty":2,"kind":"mc","stem":"장소 카드 ㉰와 ㉱에 공통으로 담긴 마음은 어느 것인가요?","options":[{"t":"전쟁에서 희생된 사람들을 기리고 추모하는 마음","correct":true},{"t":"전쟁에서 이긴 것을 자랑하는 마음","mis":"SO6-1-u1-X05"},{"t":"그곳을 관광지로만 쓰려는 마음","mis":"SO6-1-u1-X07"},{"t":"전쟁을 잊으려는 마음","mis":"SO6-1-u1-X07"}],"explanation":["㉰는 기념관과 기념비예요.","㉱는 추모하는 기념관이에요.","기리고 추모해요."],"asset":{"type":"passage","lines":["㉮ 전쟁이 끝난 뒤 한반도를 가로질러 놓인 선","㉯ 피란 왔다가 고향에 돌아가지 못한 사람들이 모여 이룬 마을","㉰ 큰 전투가 있었던 곳에 희생된 군인을 기리는 기념관과 기념비","㉱ 학생 신분으로 참전한 군인들을 추모하는 기념관"],"title":"분단의 아픔이 담긴 장소 카드 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L02_challenge#3','soc',6,1,'u1','L02','g6_1_soc_u1_L02_challenge','lesson_challenge','SO6-1-u1-C3',3,'mc','auto','비무장 지대 메모를 보고 바르게 말한 것은 어느 것인가요?',ARRAY['SO6-1-u1-X06']::text[],false,'{"seq":3,"concept":"SO6-1-u1-C3","difficulty":3,"kind":"mc","stem":"비무장 지대 메모를 보고 바르게 말한 것은 어느 것인가요?","options":[{"t":"군사 충돌을 막으려는 곳이라 오히려 자연이 잘 남아 있다","correct":true},{"t":"군대가 가장 많이 모여 싸우는 곳이다","mis":"SO6-1-u1-X06"},{"t":"생물이 살 수 없는 메마른 땅이다","mis":"SO6-1-u1-X06"},{"t":"누구나 아무 때나 마음대로 드나드는 곳이다","mis":"SO6-1-u1-X06"}],"explanation":["충돌을 막으려고 정했어요.","사람 손이 덜 닿았어요.","자연이 잘 남았어요."],"asset":{"type":"passage","lines":["정전 협정에 따라 남과 북 사이에 정해 둔 지대이다.","군사 충돌을 막으려고 군사적 행위를 원칙적으로 하지 않는다.","사람의 손이 거의 닿지 않아 자연환경이 잘 보전되어 있다.","희귀한 식물과 멸종 위기의 야생 동물이 살고 있다."],"title":"비무장 지대 알아보기 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L02_challenge#4','soc',6,1,'u1','L02','g6_1_soc_u1_L02_challenge','lesson_challenge','SO6-1-u1-C4',3,'mc','auto','판문점이 분단의 장소이면서 평화의 상징이 되는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X05']::text[],false,'{"seq":4,"concept":"SO6-1-u1-C4","difficulty":3,"kind":"mc","stem":"판문점이 분단의 장소이면서 평화의 상징이 되는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"전쟁을 멈추는 협정을 맺고, 남북 정상이 만나 회담한 곳이기 때문에","correct":true},{"t":"전쟁이 처음 시작된 곳이기 때문에","mis":"SO6-1-u1-X05"},{"t":"피란민들이 모여 만든 마을이기 때문에","mis":"SO6-1-u1-X05"},{"t":"놀이 시설로 새로 지은 곳이기 때문에","mis":"SO6-1-u1-X05"}],"explanation":["정전 협정을 맺었어요.","정상 회담이 열렸어요.","분단과 평화가 함께 담겼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L02_challenge#5','soc',6,1,'u1','L02','g6_1_soc_u1_L02_challenge','lesson_challenge','SO6-1-u1-C4',3,'ox','auto','답사는 미리 알고 있던 것을 확인하기만 하는 일이라 짐작은 답사 전에 바로 채점해야 해요.',ARRAY['SO6-1-u1-X08']::text[],false,'{"seq":5,"concept":"SO6-1-u1-C4","difficulty":3,"kind":"ox","stem":"답사는 미리 알고 있던 것을 확인하기만 하는 일이라 짐작은 답사 전에 바로 채점해야 해요.","answer":"X","reason_options":[{"t":"답사는 가서 알게 되는 일이라, 짐작은 답사로 알게 된 것과 나중에 견주어 보기 때문에","correct":true},{"t":"답사를 하면 짐작이 언제나 맞기 때문에","mis":"SO6-1-u1-X08"}],"mis":"SO6-1-u1-X08","explanation":["답사는 가서 알게 되는 일이에요.","짐작은 틀리는 것이 아니라 바뀌어요.","나중에 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L02_challenge#6','soc',6,1,'u1','L02','g6_1_soc_u1_L02_challenge','lesson_challenge','SO6-1-u1-C4',3,'error','auto','분단의 아픔이 담긴 장소를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u1-X07','SO6-1-u1-X05']::text[],false,'{"seq":6,"concept":"SO6-1-u1-C4","difficulty":3,"kind":"error","stem":"분단의 아픔이 담긴 장소를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「슬픈 장소는 모두 없애야 아픔이 사라져.」","correct":true,"mis_target":"SO6-1-u1-X07"},{"t":"친구 가 — 「평화의 장소로 바꾸면 아픔을 기억하며 평화를 배울 수 있어.」","mis":"SO6-1-u1-X07"},{"t":"친구 나 — 「DMZ 평화의 길은 남북의 합의로 열렸어.」","mis":"SO6-1-u1-X05"}],"explanation":["없애는 것이 아니에요.","평화의 장소로 바꾸어요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L02_challenge#7','soc',6,1,'u1','L02','g6_1_soc_u1_L02_challenge','lesson_challenge','SO6-1-u1-C4',3,'mc','auto','답사 수첩 ㉣ 단계에서 판문점에 대해 알아낼 내용으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X08']::text[],false,'{"seq":7,"concept":"SO6-1-u1-C4","difficulty":3,"kind":"mc","stem":"답사 수첩 ㉣ 단계에서 판문점에 대해 알아낼 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"정전 협정 체결과 정상 회담의 장소로 분단과 평화의 상징이라는 것","correct":true},{"t":"판문점까지 가는 버스 요금","mis":"SO6-1-u1-X08"},{"t":"판문점 둘레의 날씨 예보","mis":"SO6-1-u1-X08"},{"t":"누리집을 만든 사람의 이름","mis":"SO6-1-u1-X08"}],"explanation":["㉣은 의미를 알아보는 단계예요.","그곳이 왜 중요한지 봐요.","분단과 평화의 상징이에요."],"asset":{"type":"passage","lines":["㉠ 주요 시설들이 각각 어떤 곳인지 확인한다.","㉡ 답사할 장소를 고르고 그 누리집을 방문한다.","㉢ 그곳에서 일어났던 사건들을 살펴본다.","㉣ 그곳이 어떤 의미가 있는 장소인지 알아본다.","㉤ 그곳의 주요 시설들을 살펴본다."],"title":"뒤섞인 인터넷 답사 수첩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L02_challenge#8','soc',6,1,'u1','L02','g6_1_soc_u1_L02_challenge','lesson_challenge','SO6-1-u1-C3',4,'mc','auto','휴전선과 아바이 마을을 함께 보았을 때 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X05']::text[],false,'{"seq":8,"concept":"SO6-1-u1-C3","difficulty":4,"kind":"mc","stem":"휴전선과 아바이 마을을 함께 보았을 때 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"전쟁 뒤 그어진 선 때문에 고향에 돌아가지 못한 사람들의 아픔이 생겼다","correct":true},{"t":"휴전선 덕분에 피란민이 고향에 쉽게 돌아갔다","mis":"SO6-1-u1-X05"},{"t":"두 장소는 분단과 아무 관계가 없다","mis":"SO6-1-u1-X05"},{"t":"아바이 마을은 전쟁 전에 만든 놀이 마을이다","mis":"SO6-1-u1-X05"}],"explanation":["선이 오가는 길을 막았어요.","피란민이 돌아가지 못했어요.","아픔이 담긴 장소예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L02_challenge#9','soc',6,1,'u1','L02','g6_1_soc_u1_L02_challenge','lesson_challenge','SO6-1-u1-C4',4,'mc','auto','분단의 아픔이 담긴 장소를 평화의 장소로 바꾸는 노력의 뜻으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X07']::text[],false,'{"seq":9,"concept":"SO6-1-u1-C4","difficulty":4,"kind":"mc","stem":"분단의 아픔이 담긴 장소를 평화의 장소로 바꾸는 노력의 뜻으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"아픔을 잊지 않고 기억하면서 평화의 소중함을 배우는 곳으로 만든다","correct":true},{"t":"아픔을 빨리 잊도록 흔적을 지운다","mis":"SO6-1-u1-X07"},{"t":"그곳을 군사 시설로만 계속 쓴다","mis":"SO6-1-u1-X07"},{"t":"관광으로 돈을 버는 것만 생각한다","mis":"SO6-1-u1-X07"}],"explanation":["아픔을 기억해요.","평화를 배우는 곳이 돼요.","그것이 노력의 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L02_challenge#10','soc',6,1,'u1','L02','g6_1_soc_u1_L02_challenge','lesson_challenge','SO6-1-u1-C4',4,'essay','teacher','분단의 아픔이 담긴 장소 한 곳을 골라 어떤 곳인지 쓰고, 그곳이나 비무장 지대를 평화의 장소로 바꾸는 방법을 한 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-1-u1-C4","difficulty":4,"kind":"essay","stem":"분단의 아픔이 담긴 장소 한 곳을 골라 어떤 곳인지 쓰고, 그곳이나 비무장 지대를 평화의 장소로 바꾸는 방법을 한 가지 쓰세요.","answer_guide":{"answer":"예: 아바이 마을은 전쟁 중 피란 왔다가 고향에 돌아가지 못한 사람들이 모여 살면서 만들어진 마을이다. 통일이 되면 비무장 지대의 잘 보전된 자연을 살려 남북 어린이가 함께 생물을 공부하는 평화 생태 학습 공간으로 만들고 싶다.","scoring_points":["장소를 하나 골랐는가","그곳이 어떤 곳인지 바르게 썼는가","평화의 장소로 바꾸는 방법을 썼는가"]},"explanation":["장소를 골라요.","어떤 아픔이 담겼는지 써요.","평화의 장소로 바꿀 방법을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L03_basic#1','soc',6,1,'u1','L03','g6_1_soc_u1_L03_basic','lesson_basic','SO6-1-u1-C5',1,'mc','auto','분단 이후 처음으로 통일 원칙에 관한 합의를 담아 발표한 것은 어느 것인가요?',ARRAY['SO6-1-u1-X10','SO6-1-u1-X09']::text[],false,'{"seq":1,"concept":"SO6-1-u1-C5","difficulty":1,"kind":"mc","stem":"분단 이후 처음으로 통일 원칙에 관한 합의를 담아 발표한 것은 어느 것인가요?","options":[{"t":"7·4 남북 공동 성명","correct":true},{"t":"남북 기본 합의서","mis":"SO6-1-u1-X10"},{"t":"겨레말큰사전","mis":"SO6-1-u1-X09"},{"t":"개성 공업 단지","mis":"SO6-1-u1-X09"}],"explanation":["처음으로 한 합의예요.","통일 원칙을 담았어요.","7·4 남북 공동 성명이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L03_basic#2','soc',6,1,'u1','L03','g6_1_soc_u1_L03_basic','lesson_basic','SO6-1-u1-C5',1,'mc','auto','남북 화해, 평화, 교류와 협력 등의 내용을 담아 채택한 것은 어느 것인가요?',ARRAY['SO6-1-u1-X10','SO6-1-u1-X09']::text[],false,'{"seq":2,"concept":"SO6-1-u1-C5","difficulty":1,"kind":"mc","stem":"남북 화해, 평화, 교류와 협력 등의 내용을 담아 채택한 것은 어느 것인가요?","options":[{"t":"남북 기본 합의서","correct":true},{"t":"7·4 남북 공동 성명","mis":"SO6-1-u1-X10"},{"t":"DMZ 평화의 길","mis":"SO6-1-u1-X09"},{"t":"금강산 관광 사업","mis":"SO6-1-u1-X09"}],"explanation":["화해와 평화를 담았어요.","교류와 협력도 담았어요.","남북 기본 합의서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L03_basic#3','soc',6,1,'u1','L03','g6_1_soc_u1_L03_basic','lesson_basic','SO6-1-u1-C6',1,'sa','auto','남과 북이 국제 대회에 하나의 팀을 이루어 함께 출전한 것을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO6-1-u1-C6","difficulty":1,"kind":"sa","stem":"남과 북이 국제 대회에 하나의 팀을 이루어 함께 출전한 것을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["단일팀"],"explanation":["두 팀이 아니라 한 팀이에요.","◯◯팀이에요.","단일팀이에요."],"mis":"SO6-1-u1-X09"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L03_basic#4','soc',6,1,'u1','L03','g6_1_soc_u1_L03_basic','lesson_basic','SO6-1-u1-C7',1,'ox','auto','남북 철도·도로 연결 사업은 끊어진 길을 이어 서로 오가는 데 도움을 주려는 노력이에요.',ARRAY['SO6-1-u1-X12']::text[],false,'{"seq":4,"concept":"SO6-1-u1-C7","difficulty":1,"kind":"ox","stem":"남북 철도·도로 연결 사업은 끊어진 길을 이어 서로 오가는 데 도움을 주려는 노력이에요.","answer":"O","reason_options":[{"t":"휴전선이 생기며 끊어진 철도와 도로를 다시 잇는 일이기 때문에","correct":true},{"t":"남과 북을 잇던 길을 일부러 끊는 일이기 때문에","mis":"SO6-1-u1-X12"}],"mis":"SO6-1-u1-X12","explanation":["길이 끊어졌어요.","다시 이으려 했어요.","왕래를 돕는 노력이에요."],"asset":{"type":"passage","lines":["휴전선이 생기면서 남과 북을 잇던 철도와 도로가 끊어졌다.","남북은 끊어진 길을 다시 잇고 낡은 시설을 고치려고 노력했다.","길이 이어지면 육로로 대륙을 거쳐 먼 나라까지 갈 수 있다."],"title":"남북 철도·도로 연결 사업 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L03_basic#5','soc',6,1,'u1','L03','g6_1_soc_u1_L03_basic','lesson_basic','SO6-1-u1-C5',2,'match','auto','노력 카드를 보고 카드와 노력의 분야를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO6-1-u1-C5","difficulty":2,"kind":"match","stem":"노력 카드를 보고 카드와 노력의 분야를 알맞게 이으세요.","pairs":[{"l":"㉯","r":"정치적 노력"},{"l":"㉰","r":"사회·문화적 노력"},{"l":"㉳","r":"경제적 노력"}],"mis":"SO6-1-u1-X09","explanation":["㉯는 합의서예요.","㉰는 문화유산 발굴이에요.","㉳는 공업 단지예요."],"asset":{"type":"passage","lines":["㉮ 분단 뒤 처음으로 통일 원칙에 관한 합의를 담아 발표했다.","㉯ 화해·평화·교류와 협력의 내용을 담은 합의서를 채택했다.","㉰ 남북 학자들이 고려의 궁궐터에서 문화유산을 함께 발굴했다.","㉱ 국제 대회에 하나의 팀을 이루어 함께 출전했다.","㉲ 남북 국어학자들이 통일된 국어사전을 함께 만들기로 했다.","㉳ 남한의 자본·기술과 북한의 노동력을 합해 상품을 만들었다."],"title":"평화 통일을 위한 노력 카드 여섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L03_basic#6','soc',6,1,'u1','L03','g6_1_soc_u1_L03_basic','lesson_basic','SO6-1-u1-C7',2,'mc','auto','개성 공업 단지 운영 사업에서 남한과 북한이 각각 내놓은 것으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X11','SO6-1-u1-X12']::text[],false,'{"seq":6,"concept":"SO6-1-u1-C7","difficulty":2,"kind":"mc","stem":"개성 공업 단지 운영 사업에서 남한과 북한이 각각 내놓은 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"남한은 자본과 기술, 북한은 노동력","correct":true},{"t":"남한은 노동력, 북한은 자본과 기술","mis":"SO6-1-u1-X11"},{"t":"남한만 모든 것을 내놓았다","mis":"SO6-1-u1-X12"},{"t":"북한만 모든 것을 내놓았다","mis":"SO6-1-u1-X12"}],"explanation":["두 몫을 합했어요.","남한은 돈과 기술이에요.","북한은 일하는 힘이에요."],"asset":{"type":"passage","lines":["㉮ 분단 뒤 처음으로 통일 원칙에 관한 합의를 담아 발표했다.","㉯ 화해·평화·교류와 협력의 내용을 담은 합의서를 채택했다.","㉰ 남북 학자들이 고려의 궁궐터에서 문화유산을 함께 발굴했다.","㉱ 국제 대회에 하나의 팀을 이루어 함께 출전했다.","㉲ 남북 국어학자들이 통일된 국어사전을 함께 만들기로 했다.","㉳ 남한의 자본·기술과 북한의 노동력을 합해 상품을 만들었다."],"title":"평화 통일을 위한 노력 카드 여섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L03_basic#7','soc',6,1,'u1','L03','g6_1_soc_u1_L03_basic','lesson_basic','SO6-1-u1-C6',2,'mc','auto','『겨레말큰사전』을 남북이 함께 만들려는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X04','SO6-1-u1-X09']::text[],false,'{"seq":7,"concept":"SO6-1-u1-C6","difficulty":2,"kind":"mc","stem":"『겨레말큰사전』을 남북이 함께 만들려는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"달라지는 남북의 언어문화를 이해하고 한민족임을 잊지 않으려고","correct":true},{"t":"남한 말만 쓰게 하려고","mis":"SO6-1-u1-X04"},{"t":"북한 말을 모두 없애려고","mis":"SO6-1-u1-X04"},{"t":"외국어를 배우려고","mis":"SO6-1-u1-X09"}],"explanation":["남북의 말이 달라지고 있어요.","서로의 말을 이해해야 해요.","한민족임을 잊지 않으려는 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L03_basic#8','soc',6,1,'u1','L03','g6_1_soc_u1_L03_basic','lesson_basic','SO6-1-u1-C6',2,'blank','auto','남북의 학자들은 고려의 궁궐터인 (    )에서 문화유산을 함께 발굴했어요. 빈칸에 알맞은 곳은 어디인가요?',ARRAY['SO6-1-u1-X09']::text[],false,'{"seq":8,"concept":"SO6-1-u1-C6","difficulty":2,"kind":"blank","stem":"남북의 학자들은 고려의 궁궐터인 (    )에서 문화유산을 함께 발굴했어요. 빈칸에 알맞은 곳은 어디인가요?","options":[{"t":"개성 만월대","correct":true},{"t":"판문점","mis":"SO6-1-u1-X09"},{"t":"아바이 마을","mis":"SO6-1-u1-X09"},{"t":"백마고지","mis":"SO6-1-u1-X09"}],"explanation":["고려의 궁궐터예요.","남북 학자들이 함께 팠어요.","개성 만월대예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L03_basic#9','soc',6,1,'u1','L03','g6_1_soc_u1_L03_basic','lesson_basic','SO6-1-u1-C7',2,'mc','auto','평화 통일을 위한 경제적 노력이 아닌 것은 어느 것인가요?',ARRAY['SO6-1-u1-X09']::text[],false,'{"seq":9,"concept":"SO6-1-u1-C7","difficulty":2,"kind":"mc","stem":"평화 통일을 위한 경제적 노력이 아닌 것은 어느 것인가요?","options":[{"t":"국제 대회에 단일팀으로 출전","correct":true},{"t":"금강산 관광 사업","mis":"SO6-1-u1-X09"},{"t":"개성 공업 단지 운영 사업","mis":"SO6-1-u1-X09"},{"t":"남북 철도·도로 연결 사업","mis":"SO6-1-u1-X09"}],"explanation":["경제적 노력은 돈과 물자에 관한 협력이에요.","단일팀은 스포츠 교류예요.","사회·문화적 노력이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L03_basic#10','soc',6,1,'u1','L03','g6_1_soc_u1_L03_basic','lesson_basic','SO6-1-u1-C7',3,'mc','auto','남북이 경제 협력 사업을 하는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X12']::text[],false,'{"seq":10,"concept":"SO6-1-u1-C7","difficulty":3,"kind":"mc","stem":"남북이 경제 협력 사업을 하는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"남과 북의 장점이 합쳐지면 더 큰 경제적 이익을 만들 수 있기 때문에","correct":true},{"t":"한쪽이 다른 쪽을 일방적으로 돕기만 하려고","mis":"SO6-1-u1-X12"},{"t":"한쪽의 장점만 쓰고 다른 쪽은 쉬게 하려고","mis":"SO6-1-u1-X12"},{"t":"협력하면 통일과 멀어지기 때문에","mis":"SO6-1-u1-X12"}],"explanation":["남북은 저마다 장점이 있어요.","합치면 더 커져요.","통일의 밑바탕도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L03_challenge#1','soc',6,1,'u1','L03','g6_1_soc_u1_L03_challenge','lesson_challenge','SO6-1-u1-C7',2,'sa','auto','개성 공업 단지에서 남한의 자본·기술과 합해진 북한의 몫은 무엇인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-1-u1-C7","difficulty":2,"kind":"sa","stem":"개성 공업 단지에서 남한의 자본·기술과 합해진 북한의 몫은 무엇인가요? 세 글자로 쓰세요.","answer":["노동력"],"explanation":["일하는 사람의 힘이에요.","◯◯력이에요.","노동력이에요."],"mis":"SO6-1-u1-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L03_challenge#2','soc',6,1,'u1','L03','g6_1_soc_u1_L03_challenge','lesson_challenge','SO6-1-u1-C5',2,'ox','auto','7·4 남북 공동 성명은 화해·평화·교류와 협력을 담아 채택한 합의서예요.',ARRAY['SO6-1-u1-X10']::text[],false,'{"seq":2,"concept":"SO6-1-u1-C5","difficulty":2,"kind":"ox","stem":"7·4 남북 공동 성명은 화해·평화·교류와 협력을 담아 채택한 합의서예요.","answer":"X","reason_options":[{"t":"7·4 남북 공동 성명은 처음으로 통일 원칙에 관한 합의를 담아 발표한 것이기 때문에","correct":true},{"t":"7·4 남북 공동 성명과 남북 기본 합의서는 같은 것이기 때문에","mis":"SO6-1-u1-X10"}],"mis":"SO6-1-u1-X10","explanation":["공동 성명은 처음 통일 원칙이에요.","화해·교류는 기본 합의서예요.","둘을 바꾸어 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L03_challenge#3','soc',6,1,'u1','L03','g6_1_soc_u1_L03_challenge','lesson_challenge','SO6-1-u1-C6',3,'mc','auto','남북이 국제 대회에 단일팀으로 출전하거나 함께 입장한 일이 준 의미로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X09','SO6-1-u1-X04']::text[],false,'{"seq":3,"concept":"SO6-1-u1-C6","difficulty":3,"kind":"mc","stem":"남북이 국제 대회에 단일팀으로 출전하거나 함께 입장한 일이 준 의미로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"온 국민에게 통일의 희망을 전했다","correct":true},{"t":"남북의 경제적 이익만 늘렸다","mis":"SO6-1-u1-X09"},{"t":"남북이 서로 맞서게 했다","mis":"SO6-1-u1-X04"},{"t":"정치적 약속을 처음 맺었다","mis":"SO6-1-u1-X09"}],"explanation":["스포츠로 함께했어요.","하나 된 모습을 보였어요.","통일의 희망을 전했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L03_challenge#4','soc',6,1,'u1','L03','g6_1_soc_u1_L03_challenge','lesson_challenge','SO6-1-u1-C9',3,'mc','auto','노력 카드 여섯 장을 분야별로 바르게 나눈 것은 어느 것인가요?',ARRAY['SO6-1-u1-X09']::text[],false,'{"seq":4,"concept":"SO6-1-u1-C9","difficulty":3,"kind":"mc","stem":"노력 카드 여섯 장을 분야별로 바르게 나눈 것은 어느 것인가요?","options":[{"t":"정치 ㉮㉯ · 사회·문화 ㉰㉱㉲ · 경제 ㉳","correct":true},{"t":"정치 ㉮㉰ · 사회·문화 ㉯㉱ · 경제 ㉲㉳","mis":"SO6-1-u1-X09"},{"t":"정치 ㉮ · 사회·문화 ㉯㉰㉱ · 경제 ㉲㉳","mis":"SO6-1-u1-X09"},{"t":"정치 ㉮㉯㉳ · 사회·문화 ㉰㉱ · 경제 ㉲","mis":"SO6-1-u1-X09"}],"explanation":["약속과 합의는 정치예요.","발굴·단일팀·사전은 사회·문화예요.","공업 단지는 경제예요."],"asset":{"type":"passage","lines":["㉮ 분단 뒤 처음으로 통일 원칙에 관한 합의를 담아 발표했다.","㉯ 화해·평화·교류와 협력의 내용을 담은 합의서를 채택했다.","㉰ 남북 학자들이 고려의 궁궐터에서 문화유산을 함께 발굴했다.","㉱ 국제 대회에 하나의 팀을 이루어 함께 출전했다.","㉲ 남북 국어학자들이 통일된 국어사전을 함께 만들기로 했다.","㉳ 남한의 자본·기술과 북한의 노동력을 합해 상품을 만들었다."],"title":"평화 통일을 위한 노력 카드 여섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L03_challenge#5','soc',6,1,'u1','L03','g6_1_soc_u1_L03_challenge','lesson_challenge','SO6-1-u1-C7',3,'error','auto','개성 공업 단지를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u1-X11','SO6-1-u1-X12']::text[],false,'{"seq":5,"concept":"SO6-1-u1-C7","difficulty":3,"kind":"error","stem":"개성 공업 단지를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「북한의 자본과 기술, 남한의 노동력을 합한 사업이야.」","correct":true,"mis_target":"SO6-1-u1-X11"},{"t":"친구 나 — 「두 몫이 다 있어야 상품을 만들 수 있었어.」","mis":"SO6-1-u1-X12"},{"t":"친구 다 — 「남과 북의 장점을 합한 경제 협력이야.」","mis":"SO6-1-u1-X12"}],"explanation":["남한이 자본과 기술을 냈어요.","북한은 노동력을 냈어요.","친구 가가 두 몫을 뒤바꿨어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L03_challenge#6','soc',6,1,'u1','L03','g6_1_soc_u1_L03_challenge','lesson_challenge','SO6-1-u1-C7',3,'mc','auto','철도·도로 연결 메모를 보고, 남북의 길이 이어지면 좋은 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X12']::text[],false,'{"seq":6,"concept":"SO6-1-u1-C7","difficulty":3,"kind":"mc","stem":"철도·도로 연결 메모를 보고, 남북의 길이 이어지면 좋은 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"남북이 왕래하기 쉬워지고 육로로 대륙까지 갈 수 있다","correct":true},{"t":"바닷길이 모두 막힌다","mis":"SO6-1-u1-X12"},{"t":"남과 북이 더 멀어진다","mis":"SO6-1-u1-X12"},{"t":"비행기를 탈 수 없게 된다","mis":"SO6-1-u1-X12"}],"explanation":["끊어진 길을 이어요.","오가기 쉬워져요.","대륙까지 갈 수 있어요."],"asset":{"type":"passage","lines":["휴전선이 생기면서 남과 북을 잇던 철도와 도로가 끊어졌다.","남북은 끊어진 길을 다시 잇고 낡은 시설을 고치려고 노력했다.","길이 이어지면 육로로 대륙을 거쳐 먼 나라까지 갈 수 있다."],"title":"남북 철도·도로 연결 사업 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L03_challenge#7','soc',6,1,'u1','L03','g6_1_soc_u1_L03_challenge','lesson_challenge','SO6-1-u1-C12',3,'ox','auto','함께 한 일은 어느 한쪽의 몫이 아니라 두 몫이 나란히 있어야 이루어져요.',ARRAY['SO6-1-u1-X12']::text[],false,'{"seq":7,"concept":"SO6-1-u1-C12","difficulty":3,"kind":"ox","stem":"함께 한 일은 어느 한쪽의 몫이 아니라 두 몫이 나란히 있어야 이루어져요.","answer":"O","reason_options":[{"t":"협력은 서로 가진 것을 합해야 이루어지기 때문에","correct":true},{"t":"협력은 한쪽이 다른 쪽을 일방적으로 돕는 것이기 때문에","mis":"SO6-1-u1-X12"}],"mis":"SO6-1-u1-X12","explanation":["두 몫이 필요해요.","서로 가진 것을 합해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L03_challenge#8','soc',6,1,'u1','L03','g6_1_soc_u1_L03_challenge','lesson_challenge','SO6-1-u1-C9',4,'mc','auto','평화 통일을 위한 노력을 세 분야로 정리할 때 각 분야의 대표 예를 바르게 묶은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X09']::text[],false,'{"seq":8,"concept":"SO6-1-u1-C9","difficulty":4,"kind":"mc","stem":"평화 통일을 위한 노력을 세 분야로 정리할 때 각 분야의 대표 예를 바르게 묶은 것은 어느 것인가요?","options":[{"t":"정치 — 남북 정상 회담 · 사회·문화 — 겨레말큰사전 · 경제 — 금강산 관광","correct":true},{"t":"정치 — 금강산 관광 · 사회·문화 — 남북 정상 회담 · 경제 — 겨레말큰사전","mis":"SO6-1-u1-X09"},{"t":"정치 — 단일팀 · 사회·문화 — 개성 공업 단지 · 경제 — 기본 합의서","mis":"SO6-1-u1-X09"},{"t":"정치 — 겨레말큰사전 · 사회·문화 — 철도 연결 · 경제 — 공동 성명","mis":"SO6-1-u1-X09"}],"explanation":["회담은 정치예요.","사전은 사회·문화예요.","관광은 경제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L03_challenge#9','soc',6,1,'u1','L03','g6_1_soc_u1_L03_challenge','lesson_challenge','SO6-1-u1-C12',4,'mc','auto','평화 통일을 위한 여러 노력에 공통으로 담긴 생각으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X04','SO6-1-u1-X12','SO6-1-u1-X09']::text[],false,'{"seq":9,"concept":"SO6-1-u1-C12","difficulty":4,"kind":"mc","stem":"평화 통일을 위한 여러 노력에 공통으로 담긴 생각으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"대화하고 교류하며 서로 신뢰를 쌓아 평화롭게 하나가 되자","correct":true},{"t":"한쪽이 다른 쪽을 이겨서 하나가 되자","mis":"SO6-1-u1-X04"},{"t":"서로 만나지 않고 각자 지내자","mis":"SO6-1-u1-X12"},{"t":"경제만 함께하고 말과 문화는 따로 가자","mis":"SO6-1-u1-X09"}],"explanation":["약속·교류·협력이 있었어요.","서로 믿음을 쌓아요.","평화롭게 하나가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L03_challenge#10','soc',6,1,'u1','L03','g6_1_soc_u1_L03_challenge','lesson_challenge','SO6-1-u1-C9',4,'essay','teacher','평화 통일을 위한 노력을 정치·사회문화·경제 분야에서 하나씩 쓰고, 그 가운데 하나가 평화 통일에 도움이 되는 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-1-u1-C9","difficulty":4,"kind":"essay","stem":"평화 통일을 위한 노력을 정치·사회문화·경제 분야에서 하나씩 쓰고, 그 가운데 하나가 평화 통일에 도움이 되는 까닭을 쓰세요.","answer_guide":{"answer":"예: 정치적 노력으로 남북 기본 합의서를 채택했고, 사회·문화적 노력으로 『겨레말큰사전』을 함께 만들었으며, 경제적 노력으로 개성 공업 단지를 운영했다. 『겨레말큰사전』은 달라지는 남북의 말을 서로 이해하게 도와 통일 뒤에도 서로 잘 소통할 수 있게 하므로 평화 통일에 도움이 된다.","scoring_points":["세 분야의 노력을 하나씩 썼는가","분야와 노력을 바르게 짝지었는가","도움이 되는 까닭을 썼는가"]},"explanation":["세 분야를 떠올려요.","하나씩 짝지어요.","까닭을 이어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L04_basic#1','soc',6,1,'u1','L04','g6_1_soc_u1_L04_basic','lesson_basic','SO6-1-u1-C8',1,'mc','auto','북한 어린이 돕기 알뜰 시장이나 캠페인을 여는 것은 어떤 일인가요?',ARRAY['SO6-1-u1-X14','SO6-1-u1-X04']::text[],false,'{"seq":1,"concept":"SO6-1-u1-C8","difficulty":1,"kind":"mc","stem":"북한 어린이 돕기 알뜰 시장이나 캠페인을 여는 것은 어떤 일인가요?","options":[{"t":"어려움을 겪는 북한 주민을 돕는 일","correct":true},{"t":"남북의 말을 하나로 정하는 일","mis":"SO6-1-u1-X14"},{"t":"평화 통일을 바라는 마음만 키우는 일","mis":"SO6-1-u1-X14"},{"t":"북한과 경쟁하는 일","mis":"SO6-1-u1-X04"}],"explanation":["알뜰 시장으로 모은 것을 나눠요.","어려운 사람을 도와요.","북한 주민을 돕는 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L04_basic#2','soc',6,1,'u1','L04','g6_1_soc_u1_L04_basic','lesson_basic','SO6-1-u1-C8',1,'mc','auto','통일 퀴즈 대회나 북한 문화유산 알아보기 행사에 참여하는 것은 어떤 일인가요?',ARRAY['SO6-1-u1-X14','SO6-1-u1-X09','SO6-1-u1-X13']::text[],false,'{"seq":2,"concept":"SO6-1-u1-C8","difficulty":1,"kind":"mc","stem":"통일 퀴즈 대회나 북한 문화유산 알아보기 행사에 참여하는 것은 어떤 일인가요?","options":[{"t":"평화 통일의 의미와 중요성을 알리는 일","correct":true},{"t":"북한 주민에게 물건을 보내는 일","mis":"SO6-1-u1-X14"},{"t":"남북의 경제 협력 사업을 하는 일","mis":"SO6-1-u1-X09"},{"t":"통일을 서두르지 말자고 알리는 일","mis":"SO6-1-u1-X13"}],"explanation":["여러 사람이 함께 참여해요.","통일이 왜 중요한지 알게 돼요.","의미와 중요성을 알려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L04_basic#3','soc',6,1,'u1','L04','g6_1_soc_u1_L04_basic','lesson_basic','SO6-1-u1-C8',1,'sa','auto','북한 사회를 이해하고 통일 방법을 연구하며 북한에 관한 올바른 지식을 가르치는 사람을 무엇이라고 하나요? 다섯 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO6-1-u1-C8","difficulty":1,"kind":"sa","stem":"북한 사회를 이해하고 통일 방법을 연구하며 북한에 관한 올바른 지식을 가르치는 사람을 무엇이라고 하나요? 다섯 글자로 쓰세요.","answer":["북한 연구자","북한연구자"],"explanation":["북한을 연구해요.","통일 방법도 찾아요.","북한 연구자예요."],"mis":"SO6-1-u1-X13"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L04_basic#4','soc',6,1,'u1','L04','g6_1_soc_u1_L04_basic','lesson_basic','SO6-1-u1-C8',1,'ox','auto','북한에 관심을 갖는 것도 평화 통일을 위해 할 수 있는 일이에요.',ARRAY['SO6-1-u1-X13']::text[],false,'{"seq":4,"concept":"SO6-1-u1-C8","difficulty":1,"kind":"ox","stem":"북한에 관심을 갖는 것도 평화 통일을 위해 할 수 있는 일이에요.","answer":"O","reason_options":[{"t":"관심을 가져야 북한을 바르게 알고 통일에 관해 올바른 인식을 가질 수 있기 때문에","correct":true},{"t":"평화 통일은 나라가 하는 일이라 어린이와는 관계없기 때문에","mis":"SO6-1-u1-X13"}],"mis":"SO6-1-u1-X13","explanation":["관심이 첫걸음이에요.","바르게 알게 돼요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L04_basic#5','soc',6,1,'u1','L04','g6_1_soc_u1_L04_basic','lesson_basic','SO6-1-u1-C8',2,'match','auto','통일 주간 활동 카드를 보고 카드와 그 활동이 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO6-1-u1-C8","difficulty":2,"kind":"match","stem":"통일 주간 활동 카드를 보고 카드와 그 활동이 하는 일을 알맞게 이으세요.","pairs":[{"l":"㉠","r":"북한 주민 돕기"},{"l":"㉡","r":"통일을 바라는 마음 키우기"},{"l":"㉢","r":"올바른 인식 갖기"},{"l":"㉣","r":"의미와 중요성 알리기"}],"mis":"SO6-1-u1-X14","explanation":["㉠은 돕기, ㉡은 마음 키우기예요.","㉢은 알아보며 바르게 알기예요.","㉣은 행사로 알리기예요."],"asset":{"type":"passage","lines":["㉠ 북한 어린이 돕기 알뜰 시장을 열었다.","㉡ 북한 어린이에게 편지 쓰기 대회에 참가했다.","㉢ 남북 관계와 통일의 필요성을 책과 영상으로 알아보았다.","㉣ 통일 퀴즈 대회와 북한 문화유산 알아보기 행사를 열었다."],"title":"우리 학교 통일 주간 활동 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L04_basic#6','soc',6,1,'u1','L04','g6_1_soc_u1_L04_basic','lesson_basic','SO6-1-u1-C8',2,'mc','auto','종이비행기 날리기에서 가장 먼저 하는 일은 무엇인가요?',ARRAY['SO6-1-u1-X14']::text[],false,'{"seq":6,"concept":"SO6-1-u1-C8","difficulty":2,"kind":"mc","stem":"종이비행기 날리기에서 가장 먼저 하는 일은 무엇인가요?","options":[{"t":"평화 통일의 뜻을 담은 문구를 정한다","correct":true},{"t":"비행기를 모아 전시한다","mis":"SO6-1-u1-X14"},{"t":"친구들과 함께 날린다","mis":"SO6-1-u1-X14"},{"t":"비행기에 문구를 쓰고 꾸민다","mis":"SO6-1-u1-X14"}],"explanation":["무엇을 담을지 먼저 정해요.","그다음 접고 써요.","문구 정하기가 먼저예요."],"asset":{"type":"passage","lines":["① 평화 통일의 뜻을 담은 문구를 정한다.","② 종이비행기를 접고 정한 문구를 쓴 뒤 꾸민다.","③ 친구들과 함께 날리고, 날린 비행기를 모아 전시한다."],"title":"평화 통일 종이비행기 날리기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L04_basic#7','soc',6,1,'u1','L04','g6_1_soc_u1_L04_basic','lesson_basic','SO6-1-u1-C8',2,'mc','auto','평화 통일 뮤직비디오를 만들 때 지켜야 할 점으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X14']::text[],false,'{"seq":7,"concept":"SO6-1-u1-C8","difficulty":2,"kind":"mc","stem":"평화 통일 뮤직비디오를 만들 때 지켜야 할 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"쓴 노래의 출처를 밝히고 저작권을 존중한다","correct":true},{"t":"남의 노래를 출처 없이 마음대로 쓴다","mis":"SO6-1-u1-X14"},{"t":"가사와 상관없는 영상을 넣는다","mis":"SO6-1-u1-X14"},{"t":"줄거리 없이 아무 장면이나 찍는다","mis":"SO6-1-u1-X14"}],"explanation":["남이 만든 노래예요.","만든 사람의 권리가 있어요.","출처를 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L04_basic#8','soc',6,1,'u1','L04','g6_1_soc_u1_L04_basic','lesson_basic','SO6-1-u1-C8',2,'mc','auto','평화 통일을 위해 할 수 있는 일로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X13']::text[],false,'{"seq":8,"concept":"SO6-1-u1-C8","difficulty":2,"kind":"mc","stem":"평화 통일을 위해 할 수 있는 일로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"북한에 관해 알아보려 하지 않는다","correct":true},{"t":"편지 쓰기 대회에 참가한다","mis":"SO6-1-u1-X13"},{"t":"알뜰 시장을 열어 북한 주민을 돕는다","mis":"SO6-1-u1-X13"},{"t":"통일 퀴즈 대회에 참여한다","mis":"SO6-1-u1-X13"}],"explanation":["관심을 갖는 것도 실천이에요.","알아보려 하지 않으면 실천이 아니에요.","나머지 셋은 실천이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L04_basic#9','soc',6,1,'u1','L04','g6_1_soc_u1_L04_basic','lesson_basic','SO6-1-u1-C8',2,'mc','auto','평화 통일 밥상 그리기에서 남한과 북한의 음식을 함께 고르는 까닭은 무엇인가요?',ARRAY['SO6-1-u1-X04','SO6-1-u1-X14']::text[],false,'{"seq":9,"concept":"SO6-1-u1-C8","difficulty":2,"kind":"mc","stem":"평화 통일 밥상 그리기에서 남한과 북한의 음식을 함께 고르는 까닭은 무엇인가요?","options":[{"t":"남북이 화합하는 조화로운 한 상을 차리려고","correct":true},{"t":"한쪽 음식이 더 좋다고 알리려고","mis":"SO6-1-u1-X04"},{"t":"음식 값을 견주어 보려고","mis":"SO6-1-u1-X14"},{"t":"남한 음식만 고르면 되니까","mis":"SO6-1-u1-X04"}],"explanation":["두 곳의 음식을 모아요.","함께 어울리는 상이에요.","화합의 뜻을 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L04_basic#10','soc',6,1,'u1','L04','g6_1_soc_u1_L04_basic','lesson_basic','SO6-1-u1-C8',3,'error','auto','평화 통일을 위한 실천을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u1-X13','SO6-1-u1-X14']::text[],false,'{"seq":10,"concept":"SO6-1-u1-C8","difficulty":3,"kind":"error","stem":"평화 통일을 위한 실천을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「통일은 어른들이 할 일이라 우리가 할 건 없어.」","correct":true,"mis_target":"SO6-1-u1-X13"},{"t":"친구 가 — 「편지 쓰기 대회에 나가면 통일을 바라는 마음이 커질 거야.」","mis":"SO6-1-u1-X14"},{"t":"친구 다 — 「북한 문화유산을 알아보는 것도 실천이야.」","mis":"SO6-1-u1-X14"}],"explanation":["어린이도 할 수 있어요.","관심과 참여가 실천이에요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L04_challenge#1','soc',6,1,'u1','L04','g6_1_soc_u1_L04_challenge','lesson_challenge','SO6-1-u1-C8',2,'sa','auto','종이비행기 날리기 둘째 걸음에서 종이비행기에 쓰는 것은 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-1-u1-C8","difficulty":2,"kind":"sa","stem":"종이비행기 날리기 둘째 걸음에서 종이비행기에 쓰는 것은 무엇인가요? 두 글자로 쓰세요.","answer":["문구"],"explanation":["첫째 걸음에서 정했어요.","평화 통일의 뜻을 담았어요.","문구예요."],"mis":"SO6-1-u1-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L04_challenge#2','soc',6,1,'u1','L04','g6_1_soc_u1_L04_challenge','lesson_challenge','SO6-1-u1-C8',2,'mc','auto','북한 연구자가 되려면 필요한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X04','SO6-1-u1-X13']::text[],false,'{"seq":2,"concept":"SO6-1-u1-C8","difficulty":2,"kind":"mc","stem":"북한 연구자가 되려면 필요한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"남북의 차이를 이해하고 받아들이는 포용력과 폭넓은 시각","correct":true},{"t":"북한을 이기는 방법만 아는 것","mis":"SO6-1-u1-X04"},{"t":"남한 것만 옳다고 믿는 마음","mis":"SO6-1-u1-X04"},{"t":"새로운 문화에 관심을 갖지 않는 태도","mis":"SO6-1-u1-X13"}],"explanation":["차이를 이해해야 해요.","받아들이는 마음이 필요해요.","포용력과 폭넓은 시각이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L04_challenge#3','soc',6,1,'u1','L04','g6_1_soc_u1_L04_challenge','lesson_challenge','SO6-1-u1-C8',3,'mc','auto','통일 주간 활동 카드 ㉢처럼 남북 관계와 통일의 필요성을 알아보는 것이 중요한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X13','SO6-1-u1-X14']::text[],false,'{"seq":3,"concept":"SO6-1-u1-C8","difficulty":3,"kind":"mc","stem":"통일 주간 활동 카드 ㉢처럼 남북 관계와 통일의 필요성을 알아보는 것이 중요한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"바르게 알아야 평화 통일에 관해 올바른 인식을 갖고 실천할 수 있기 때문에","correct":true},{"t":"알아보기만 하면 통일이 저절로 되기 때문에","mis":"SO6-1-u1-X13"},{"t":"북한 주민을 직접 돕는 일이기 때문에","mis":"SO6-1-u1-X14"},{"t":"통일이 필요 없다는 것을 알리려고","mis":"SO6-1-u1-X13"}],"explanation":["먼저 바르게 알아요.","올바른 인식이 생겨요.","실천으로 이어져요."],"asset":{"type":"passage","lines":["㉠ 북한 어린이 돕기 알뜰 시장을 열었다.","㉡ 북한 어린이에게 편지 쓰기 대회에 참가했다.","㉢ 남북 관계와 통일의 필요성을 책과 영상으로 알아보았다.","㉣ 통일 퀴즈 대회와 북한 문화유산 알아보기 행사를 열었다."],"title":"우리 학교 통일 주간 활동 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L04_challenge#4','soc',6,1,'u1','L04','g6_1_soc_u1_L04_challenge','lesson_challenge','SO6-1-u1-C8',3,'mc','auto','서로 다른 실천(밥상 그리기·종이비행기·뮤직비디오)을 고른 친구들이 결국 같은 목표에 닿는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X14']::text[],false,'{"seq":4,"concept":"SO6-1-u1-C8","difficulty":3,"kind":"mc","stem":"서로 다른 실천(밥상 그리기·종이비행기·뮤직비디오)을 고른 친구들이 결국 같은 목표에 닿는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"방법은 달라도 모두 평화 통일을 바라는 마음을 키우고 나누는 일이기 때문에","correct":true},{"t":"가장 빠른 실천 하나만 옳기 때문에","mis":"SO6-1-u1-X14"},{"t":"실천은 정해진 하나만 해야 하기 때문에","mis":"SO6-1-u1-X14"},{"t":"고른 방법이 모두 똑같기 때문에","mis":"SO6-1-u1-X14"}],"explanation":["방법은 저마다 달라요.","목표는 같아요.","모두 평화 통일로 모여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L04_challenge#5','soc',6,1,'u1','L04','g6_1_soc_u1_L04_challenge','lesson_challenge','SO6-1-u1-C8',3,'ox','auto','평화 통일을 위한 실천은 저마다 고른 방법의 차례를 끝까지 밟아 해내는 것이 중요해요.',ARRAY['SO6-1-u1-X14']::text[],false,'{"seq":5,"concept":"SO6-1-u1-C8","difficulty":3,"kind":"ox","stem":"평화 통일을 위한 실천은 저마다 고른 방법의 차례를 끝까지 밟아 해내는 것이 중요해요.","answer":"O","reason_options":[{"t":"실천마다 하는 차례가 다르고, 고른 사람이 그 길을 끝까지 해내야 실천이 되기 때문에","correct":true},{"t":"실천은 시작만 하면 되고 끝까지 할 필요는 없기 때문에","mis":"SO6-1-u1-X14"}],"mis":"SO6-1-u1-X14","explanation":["차례가 서로 달라요.","끝까지 해내요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L04_challenge#6','soc',6,1,'u1','L04','g6_1_soc_u1_L04_challenge','lesson_challenge','SO6-1-u1-C4',3,'mc','auto','다음 가운데 북한 사람을 대하는 태도로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X04','SO6-1-u1-X13','SO6-1-u1-X02']::text[],false,'{"seq":6,"concept":"SO6-1-u1-C4","difficulty":3,"kind":"mc","stem":"다음 가운데 북한 사람을 대하는 태도로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"분단의 아픔을 함께 겪는 같은 민족으로 이해하려고 한다","correct":true},{"t":"이겨야 할 적으로 여기고 멀리한다","mis":"SO6-1-u1-X04"},{"t":"관심을 두지 않고 모른 척한다","mis":"SO6-1-u1-X13"},{"t":"말이 다르니 외국 사람으로만 여긴다","mis":"SO6-1-u1-X02"}],"explanation":["같은 민족이에요.","분단의 아픔을 함께 겪어요.","이해하려는 마음이 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L04_challenge#7','soc',6,1,'u1','L04','g6_1_soc_u1_L04_challenge','lesson_challenge','SO6-1-u1-C8',3,'error','auto','뮤직비디오 만들기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u1-X14']::text[],false,'{"seq":7,"concept":"SO6-1-u1-C8","difficulty":3,"kind":"error","stem":"뮤직비디오 만들기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「인터넷에 있는 노래니까 출처는 안 밝혀도 돼.」","correct":true,"mis_target":"SO6-1-u1-X14"},{"t":"친구 가 — 「노래 가사에 맞춰 줄거리를 먼저 만들자.」","mis":"SO6-1-u1-X14"},{"t":"친구 나 — 「다 만들면 친구들과 보고 느낀 점을 나누자.」","mis":"SO6-1-u1-X14"}],"explanation":["남이 만든 노래예요.","출처를 밝혀야 해요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L04_challenge#8','soc',6,1,'u1','L04','g6_1_soc_u1_L04_challenge','lesson_challenge','SO6-1-u1-C8',4,'mc','auto','평화 통일을 위해 할 수 있는 일 네 가지를 가장 바르게 정리한 것은 어느 것인가요?',ARRAY['SO6-1-u1-X04','SO6-1-u1-X13','SO6-1-u1-X09']::text[],false,'{"seq":8,"concept":"SO6-1-u1-C8","difficulty":4,"kind":"mc","stem":"평화 통일을 위해 할 수 있는 일 네 가지를 가장 바르게 정리한 것은 어느 것인가요?","options":[{"t":"올바른 인식 갖기 · 통일을 바라는 마음 키우기 · 북한 주민 돕기 · 의미와 중요성 알리기","correct":true},{"t":"국방비 늘리기 · 휴전선 지키기 · 북한과 경쟁하기 · 관심 두지 않기","mis":"SO6-1-u1-X04"},{"t":"어른에게 맡기기 · 결과 기다리기 · 뉴스만 보기 · 잊어버리기","mis":"SO6-1-u1-X13"},{"t":"통일 원칙 합의하기 · 단일팀 만들기 · 공업 단지 운영하기 · 철도 잇기","mis":"SO6-1-u1-X09"}],"explanation":["어린이도 할 수 있는 일이에요.","인식·마음·돕기·알리기예요.","나머지는 나라의 노력이거나 실천이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L04_challenge#9','soc',6,1,'u1','L04','g6_1_soc_u1_L04_challenge','lesson_challenge','SO6-1-u1-C13',4,'mc','auto','평화 통일을 위한 나라의 노력과 우리의 실천을 함께 볼 때 가장 알맞은 생각은 어느 것인가요?',ARRAY['SO6-1-u1-X13','SO6-1-u1-X09']::text[],false,'{"seq":9,"concept":"SO6-1-u1-C13","difficulty":4,"kind":"mc","stem":"평화 통일을 위한 나라의 노력과 우리의 실천을 함께 볼 때 가장 알맞은 생각은 어느 것인가요?","options":[{"t":"나라의 노력과 시민 한 사람 한 사람의 실천이 함께 모여야 평화 통일에 다가갈 수 있다","correct":true},{"t":"나라가 노력하니 우리는 아무것도 하지 않아도 된다","mis":"SO6-1-u1-X13"},{"t":"우리가 실천하면 나라의 노력은 필요 없다","mis":"SO6-1-u1-X09"},{"t":"평화 통일은 저절로 이루어진다","mis":"SO6-1-u1-X13"}],"explanation":["나라도 노력해요.","우리도 실천해요.","함께 모여야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L04_challenge#10','soc',6,1,'u1','L04','g6_1_soc_u1_L04_challenge','lesson_challenge','SO6-1-u1-C8',4,'essay','teacher','평화 통일을 위해 내가 할 수 있는 일을 하나 정해 어떻게 실천할지 차례대로 쓰고, 그 실천이 평화 통일에 도움이 되는 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-1-u1-C8","difficulty":4,"kind":"essay","stem":"평화 통일을 위해 내가 할 수 있는 일을 하나 정해 어떻게 실천할지 차례대로 쓰고, 그 실천이 평화 통일에 도움이 되는 까닭을 쓰세요.","answer_guide":{"answer":"예: 나는 평화 통일 종이비행기 날리기를 하겠다. 먼저 「우리는 한민족, 언제나 함께」처럼 평화 통일의 뜻을 담은 문구를 정하고, 종이비행기를 접어 문구를 쓰고 꾸민 뒤, 친구들과 함께 날리고 모아서 전시하겠다. 이렇게 하면 친구들과 함께 평화 통일을 바라는 마음을 키우고 나눌 수 있어 도움이 된다.","scoring_points":["실천할 일을 하나 정했는가","실천의 차례를 썼는가","평화 통일에 도움이 되는 까닭을 썼는가"]},"explanation":["실천할 일을 골라요.","차례대로 써요.","도움이 되는 까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L05_basic#1','soc',6,1,'u1','L05','g6_1_soc_u1_L05_basic','lesson_basic','SO6-1-u1-C9',1,'mc','auto','이승만 정부가 계속 집권하려고 벌인 일은 어느 것인가요?',ARRAY['SO6-1-u1-X15']::text[],false,'{"seq":1,"concept":"SO6-1-u1-C9","difficulty":1,"kind":"mc","stem":"이승만 정부가 계속 집권하려고 벌인 일은 어느 것인가요?","options":[{"t":"3·15 부정 선거","correct":true},{"t":"헌법을 지키는 바른 선거","mis":"SO6-1-u1-X15"},{"t":"대통령 자리에서 스스로 물러나기","mis":"SO6-1-u1-X15"},{"t":"국민에게 투표를 맡기기","mis":"SO6-1-u1-X15"}],"explanation":["계속 집권하려 했어요.","부정한 방법을 썼어요.","3·15 부정 선거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L05_basic#2','soc',6,1,'u1','L05','g6_1_soc_u1_L05_basic','lesson_basic','SO6-1-u1-C9',1,'mc','auto','정부가 선거 운동에 개입하자 처음으로 정부에 맞서 시위한 사람들은 누구인가요?',ARRAY['SO6-1-u1-X16']::text[],false,'{"seq":2,"concept":"SO6-1-u1-C9","difficulty":1,"kind":"mc","stem":"정부가 선거 운동에 개입하자 처음으로 정부에 맞서 시위한 사람들은 누구인가요?","options":[{"t":"대구의 고등학생들","correct":true},{"t":"서울의 대학교수들","mis":"SO6-1-u1-X16"},{"t":"이웃 나라 학생들","mis":"SO6-1-u1-X16"},{"t":"정부의 관리들","mis":"SO6-1-u1-X16"}],"explanation":["학생들이었어요.","대구에서 시작했어요.","대구의 고등학생들이에요."],"asset":{"type":"passage","lines":["ⓐ 2월 28일 — 대구의 고등학생들이 처음으로 정부에 맞섰다.","ⓑ 3월 15일 — 부정한 방법으로 정부통령 선거를 치렀다.","ⓒ 4월 11일 — 마산 시위에 나섰던 고등학생의 죽음이 알려졌다.","ⓓ 4월 19일 — 여러 도시에서 학생과 시민이 시위를 벌였다.","ⓔ 4월 26일 — 대통령이 자리에서 물러났다."],"title":"4·19 혁명 흐름표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L05_basic#3','soc',6,1,'u1','L05','g6_1_soc_u1_L05_basic','lesson_basic','SO6-1-u1-C9',1,'sa','auto','대통령과 부통령을 함께 뽑는 선거를 무엇이라고 하나요? 다섯 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO6-1-u1-C9","difficulty":1,"kind":"sa","stem":"대통령과 부통령을 함께 뽑는 선거를 무엇이라고 하나요? 다섯 글자로 쓰세요.","answer":["정부통령 선거","정부통령선거"],"explanation":["대통령과 부통령을 함께 뽑아요.","정◯◯ 선거예요.","정부통령 선거예요."],"mis":"SO6-1-u1-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L05_basic#4','soc',6,1,'u1','L05','g6_1_soc_u1_L05_basic','lesson_basic','SO6-1-u1-C9',1,'ox','auto','4·19 혁명에는 초등학생부터 대학교수까지 각계각층의 사람들이 참여했어요.',ARRAY['SO6-1-u1-X16']::text[],false,'{"seq":4,"concept":"SO6-1-u1-C9","difficulty":1,"kind":"ox","stem":"4·19 혁명에는 초등학생부터 대학교수까지 각계각층의 사람들이 참여했어요.","answer":"O","reason_options":[{"t":"여러 도시에서 학생과 시민이 함께 시위를 벌였기 때문에","correct":true},{"t":"대학생들만 시위에 참여했기 때문에","mis":"SO6-1-u1-X16"}],"mis":"SO6-1-u1-X16","explanation":["학생과 시민이 나섰어요.","초등학생도 참여했어요.","각계각층이 참여했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L05_basic#5','soc',6,1,'u1','L05','g6_1_soc_u1_L05_basic','lesson_basic','SO6-1-u1-C10',2,'mc','auto','4·19 혁명의 결과로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X17']::text[],false,'{"seq":5,"concept":"SO6-1-u1-C10","difficulty":2,"kind":"mc","stem":"4·19 혁명의 결과로 알맞은 것은 어느 것인가요?","options":[{"t":"이승만이 대통령 자리에서 물러나고 3·15 부정 선거는 무효가 되었다","correct":true},{"t":"부정 선거의 결과가 그대로 인정되었다","mis":"SO6-1-u1-X17"},{"t":"정부가 더 오래 집권하게 되었다","mis":"SO6-1-u1-X17"},{"t":"선거 제도가 아예 없어졌다","mis":"SO6-1-u1-X17"}],"explanation":["시민과 학생이 나섰어요.","대통령이 물러났어요.","부정 선거는 무효가 되었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L05_basic#6','soc',6,1,'u1','L05','g6_1_soc_u1_L05_basic','lesson_basic','SO6-1-u1-C9',2,'mc','auto','시민 ㉠~㉢의 말처럼 3·15 선거에서 있었던 일을 묶어 부르는 말로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X15','SO6-1-u1-X24']::text[],false,'{"seq":6,"concept":"SO6-1-u1-C9","difficulty":2,"kind":"mc","stem":"시민 ㉠~㉢의 말처럼 3·15 선거에서 있었던 일을 묶어 부르는 말로 알맞은 것은 어느 것인가요?","options":[{"t":"부정 선거","correct":true},{"t":"공정한 선거","mis":"SO6-1-u1-X15"},{"t":"직접 선거","mis":"SO6-1-u1-X24"},{"t":"비밀 선거","mis":"SO6-1-u1-X15"}],"explanation":["돈과 물건을 주었어요.","투표를 확인하고 미리 표시했어요.","부정한 방법이에요."],"asset":{"type":"speech","turns":[{"who":"어느 시민 ㉠","text":"돈이나 물건을 주며 어느 후보를 찍으라고 했어요."},{"who":"어느 시민 ㉡","text":"조를 짜서 투표하게 하고 조장이 누구를 찍는지 확인했어요."},{"who":"어느 시민 ㉢","text":"선거 전에 미리 표시해 둔 투표지가 투표함에서 나왔어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L05_basic#7','soc',6,1,'u1','L05','g6_1_soc_u1_L05_basic','lesson_basic','SO6-1-u1-C9',2,'mc','auto','부정한 방법으로 선거가 치러지면 생기는 문제로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X15']::text[],false,'{"seq":7,"concept":"SO6-1-u1-C9","difficulty":2,"kind":"mc","stem":"부정한 방법으로 선거가 치러지면 생기는 문제로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"국민의 뜻이 제대로 전달되지 않고 국민이 결과를 믿지 못한다","correct":true},{"t":"표를 세는 일이 더 빨라진다","mis":"SO6-1-u1-X15"},{"t":"국민의 뜻이 더 잘 드러난다","mis":"SO6-1-u1-X15"},{"t":"아무 문제도 생기지 않는다","mis":"SO6-1-u1-X15"}],"explanation":["국민의 뜻이 왜곡돼요.","결과를 믿기 어려워요.","그래서 문제가 커요."],"asset":{"type":"speech","turns":[{"who":"어느 시민 ㉠","text":"돈이나 물건을 주며 어느 후보를 찍으라고 했어요."},{"who":"어느 시민 ㉡","text":"조를 짜서 투표하게 하고 조장이 누구를 찍는지 확인했어요."},{"who":"어느 시민 ㉢","text":"선거 전에 미리 표시해 둔 투표지가 투표함에서 나왔어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L05_basic#8','soc',6,1,'u1','L05','g6_1_soc_u1_L05_basic','lesson_basic','SO6-1-u1-C9',2,'blank','auto','마산 시위에 나섰던 (    )의 죽음이 알려지면서 시위는 전국으로 퍼졌어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-1-u1-X16']::text[],false,'{"seq":8,"concept":"SO6-1-u1-C9","difficulty":2,"kind":"blank","stem":"마산 시위에 나섰던 (    )의 죽음이 알려지면서 시위는 전국으로 퍼졌어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"고등학생 김주열","correct":true},{"t":"대통령 이승만","mis":"SO6-1-u1-X16"},{"t":"정부의 관리","mis":"SO6-1-u1-X16"},{"t":"서울의 대학교수","mis":"SO6-1-u1-X16"}],"explanation":["마산 시위에 나섰던 학생이에요.","그 일로 시위가 퍼졌어요.","김주열이에요."],"asset":{"type":"passage","lines":["ⓐ 2월 28일 — 대구의 고등학생들이 처음으로 정부에 맞섰다.","ⓑ 3월 15일 — 부정한 방법으로 정부통령 선거를 치렀다.","ⓒ 4월 11일 — 마산 시위에 나섰던 고등학생의 죽음이 알려졌다.","ⓓ 4월 19일 — 여러 도시에서 학생과 시민이 시위를 벌였다.","ⓔ 4월 26일 — 대통령이 자리에서 물러났다."],"title":"4·19 혁명 흐름표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L05_basic#9','soc',6,1,'u1','L05','g6_1_soc_u1_L05_basic','lesson_basic','SO6-1-u1-C10',2,'mc','auto','4·19 혁명의 의의로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X17','SO6-1-u1-X24']::text[],false,'{"seq":9,"concept":"SO6-1-u1-C10","difficulty":2,"kind":"mc","stem":"4·19 혁명의 의의로 알맞은 것은 어느 것인가요?","options":[{"t":"시민과 학생의 힘으로 민주적 절차를 무시한 정권을 무너뜨려 민주주의 발전의 밑거름이 되었다","correct":true},{"t":"부정 선거를 더 늘리는 계기가 되었다","mis":"SO6-1-u1-X17"},{"t":"군인이 권력을 잡는 계기가 되었다","mis":"SO6-1-u1-X24"},{"t":"민주주의와는 관계없는 일이었다","mis":"SO6-1-u1-X17"}],"explanation":["시민과 학생이 해냈어요.","민주적 절차를 지키려 했어요.","민주주의의 밑거름이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L05_basic#10','soc',6,1,'u1','L05','g6_1_soc_u1_L05_basic','lesson_basic','SO6-1-u1-C9',3,'mc','auto','4·19 혁명 흐름표의 ⓐ~ⓔ를 원인에서 결과로 이어 볼 때 ⓑ가 맡은 자리로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X15','SO6-1-u1-X16']::text[],false,'{"seq":10,"concept":"SO6-1-u1-C9","difficulty":3,"kind":"mc","stem":"4·19 혁명 흐름표의 ⓐ~ⓔ를 원인에서 결과로 이어 볼 때 ⓑ가 맡은 자리로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"시위가 크게 번진 직접적인 원인","correct":true},{"t":"혁명의 마지막 결과","mis":"SO6-1-u1-X15"},{"t":"시위와 관계없는 일","mis":"SO6-1-u1-X15"},{"t":"혁명이 끝난 뒤의 일","mis":"SO6-1-u1-X16"}],"explanation":["ⓑ는 부정 선거예요.","선거 무효를 외치며 시위가 번졌어요.","직접적인 원인이에요."],"asset":{"type":"passage","lines":["ⓐ 2월 28일 — 대구의 고등학생들이 처음으로 정부에 맞섰다.","ⓑ 3월 15일 — 부정한 방법으로 정부통령 선거를 치렀다.","ⓒ 4월 11일 — 마산 시위에 나섰던 고등학생의 죽음이 알려졌다.","ⓓ 4월 19일 — 여러 도시에서 학생과 시민이 시위를 벌였다.","ⓔ 4월 26일 — 대통령이 자리에서 물러났다."],"title":"4·19 혁명 흐름표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L05_challenge#1','soc',6,1,'u1','L05','g6_1_soc_u1_L05_challenge','lesson_challenge','SO6-1-u1-C9',2,'sa','auto','4·19 혁명이 일어나게 된 직접적인 원인인 선거를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-1-u1-C9","difficulty":2,"kind":"sa","stem":"4·19 혁명이 일어나게 된 직접적인 원인인 선거를 쓰세요.","answer":["3·15 부정 선거","3·15 부정선거","부정 선거","부정선거"],"explanation":["3월 15일에 치렀어요.","부정한 방법을 썼어요.","3·15 부정 선거예요."],"mis":"SO6-1-u1-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L05_challenge#2','soc',6,1,'u1','L05','g6_1_soc_u1_L05_challenge','lesson_challenge','SO6-1-u1-C9',2,'mc','auto','4·19 혁명 흐름표에서 시위가 전국으로 퍼지는 계기가 된 일은 어느 것인가요?',ARRAY['SO6-1-u1-X16']::text[],false,'{"seq":2,"concept":"SO6-1-u1-C9","difficulty":2,"kind":"mc","stem":"4·19 혁명 흐름표에서 시위가 전국으로 퍼지는 계기가 된 일은 어느 것인가요?","options":[{"t":"ⓒ","correct":true},{"t":"ⓐ","mis":"SO6-1-u1-X16"},{"t":"ⓔ","mis":"SO6-1-u1-X16"},{"t":"ⓑ","mis":"SO6-1-u1-X16"}],"explanation":["ⓐ는 처음 맞선 일이에요.","ⓒ의 일이 알려지며 번졌어요.","ⓔ는 결과예요."],"asset":{"type":"passage","lines":["ⓐ 2월 28일 — 대구의 고등학생들이 처음으로 정부에 맞섰다.","ⓑ 3월 15일 — 부정한 방법으로 정부통령 선거를 치렀다.","ⓒ 4월 11일 — 마산 시위에 나섰던 고등학생의 죽음이 알려졌다.","ⓓ 4월 19일 — 여러 도시에서 학생과 시민이 시위를 벌였다.","ⓔ 4월 26일 — 대통령이 자리에서 물러났다."],"title":"4·19 혁명 흐름표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L05_challenge#3','soc',6,1,'u1','L05','g6_1_soc_u1_L05_challenge','lesson_challenge','SO6-1-u1-C9',3,'mc','auto','4·19 혁명 흐름표를 결과 쪽에서 거슬러 올라 차례대로 바르게 늘어놓은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X16']::text[],false,'{"seq":3,"concept":"SO6-1-u1-C9","difficulty":3,"kind":"mc","stem":"4·19 혁명 흐름표를 결과 쪽에서 거슬러 올라 차례대로 바르게 늘어놓은 것은 어느 것인가요?","options":[{"t":"ⓔ → ⓓ → ⓒ → ⓑ → ⓐ","correct":true},{"t":"ⓐ → ⓑ → ⓒ → ⓓ → ⓔ","mis":"SO6-1-u1-X16"},{"t":"ⓔ → ⓒ → ⓓ → ⓐ → ⓑ","mis":"SO6-1-u1-X16"},{"t":"ⓑ → ⓐ → ⓒ → ⓔ → ⓓ","mis":"SO6-1-u1-X16"}],"explanation":["결과는 ⓔ예요.","한 칸씩 앞의 일로 올라가요.","ⓐ가 가장 앞이에요."],"asset":{"type":"passage","lines":["ⓐ 2월 28일 — 대구의 고등학생들이 처음으로 정부에 맞섰다.","ⓑ 3월 15일 — 부정한 방법으로 정부통령 선거를 치렀다.","ⓒ 4월 11일 — 마산 시위에 나섰던 고등학생의 죽음이 알려졌다.","ⓓ 4월 19일 — 여러 도시에서 학생과 시민이 시위를 벌였다.","ⓔ 4월 26일 — 대통령이 자리에서 물러났다."],"title":"4·19 혁명 흐름표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L05_challenge#4','soc',6,1,'u1','L05','g6_1_soc_u1_L05_challenge','lesson_challenge','SO6-1-u1-C9',3,'mc','auto','국민의 불만이 높아진 까닭으로 4·19 혁명 이전 상황을 가장 잘 설명한 것은 어느 것인가요?',ARRAY['SO6-1-u1-X15']::text[],false,'{"seq":4,"concept":"SO6-1-u1-C9","difficulty":3,"kind":"mc","stem":"국민의 불만이 높아진 까닭으로 4·19 혁명 이전 상황을 가장 잘 설명한 것은 어느 것인가요?","options":[{"t":"대통령이 헌법을 바꿔 가며 오래 집권했고 전쟁 뒤 경제도 어려웠다","correct":true},{"t":"대통령이 짧게 일하고 곧 물러났다","mis":"SO6-1-u1-X15"},{"t":"경제가 매우 좋아 모두 넉넉했다","mis":"SO6-1-u1-X15"},{"t":"선거가 늘 공정하게 치러졌다","mis":"SO6-1-u1-X15"}],"explanation":["오래 집권했어요.","경제가 어려웠어요.","불만이 쌓였어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L05_challenge#5','soc',6,1,'u1','L05','g6_1_soc_u1_L05_challenge','lesson_challenge','SO6-1-u1-C10',3,'ox','auto','4·19 혁명은 시민과 학생의 힘으로 민주적 절차를 무시한 정권을 무너뜨린 사건이에요.',ARRAY['SO6-1-u1-X24']::text[],false,'{"seq":5,"concept":"SO6-1-u1-C10","difficulty":3,"kind":"ox","stem":"4·19 혁명은 시민과 학생의 힘으로 민주적 절차를 무시한 정권을 무너뜨린 사건이에요.","answer":"O","reason_options":[{"t":"부정 선거로 계속 집권하려던 대통령이 시민과 학생의 시위로 물러났기 때문에","correct":true},{"t":"군인들이 힘으로 정권을 바꾼 일이기 때문에","mis":"SO6-1-u1-X24"}],"mis":"SO6-1-u1-X24","explanation":["시민과 학생이 나섰어요.","대통령이 물러났어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L05_challenge#6','soc',6,1,'u1','L05','g6_1_soc_u1_L05_challenge','lesson_challenge','SO6-1-u1-C9',3,'error','auto','4·19 혁명을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u1-X15','SO6-1-u1-X16']::text[],false,'{"seq":6,"concept":"SO6-1-u1-C9","difficulty":3,"kind":"error","stem":"4·19 혁명을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「대통령이 물러난 일 때문에 부정 선거가 일어났어.」","correct":true,"mis_target":"SO6-1-u1-X15"},{"t":"친구 가 — 「부정 선거가 시위의 원인이 되었어.」","mis":"SO6-1-u1-X15"},{"t":"친구 다 — 「시위가 전국으로 퍼지자 대통령이 물러났어.」","mis":"SO6-1-u1-X16"}],"explanation":["부정 선거가 먼저예요.","물러난 것은 결과예요.","친구 나가 원인과 결과를 바꿨어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L05_challenge#7','soc',6,1,'u1','L05','g6_1_soc_u1_L05_challenge','lesson_challenge','SO6-1-u1-C10',3,'mc','auto','4·19 혁명을 공부하는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X31','SO6-1-u1-X15']::text[],false,'{"seq":7,"concept":"SO6-1-u1-C10","difficulty":3,"kind":"mc","stem":"4·19 혁명을 공부하는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"부정 선거가 왜 시위로 이어지고 어떤 결과를 낳았는지 원인과 결과를 이어 생각한다","correct":true},{"t":"날짜와 숫자만 차례대로 외운다","mis":"SO6-1-u1-X31"},{"t":"결과만 알면 되니 원인은 살피지 않는다","mis":"SO6-1-u1-X15"},{"t":"사건에 나온 사람 이름만 외운다","mis":"SO6-1-u1-X31"}],"explanation":["외우기보다 까닭을 봐요.","원인과 결과를 이어요.","그래야 의미를 알아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L05_challenge#8','soc',6,1,'u1','L05','g6_1_soc_u1_L05_challenge','lesson_challenge','SO6-1-u1-C10',4,'mc','auto','4·19 혁명이 오늘날 우리에게 주는 의미로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X17','SO6-1-u1-X16']::text[],false,'{"seq":8,"concept":"SO6-1-u1-C10","difficulty":4,"kind":"mc","stem":"4·19 혁명이 오늘날 우리에게 주는 의미로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"국민의 뜻을 무시한 정치는 시민의 힘으로 바로잡을 수 있으며 바른 선거가 민주주의의 바탕이다","correct":true},{"t":"선거는 중요하지 않다","mis":"SO6-1-u1-X17"},{"t":"정부가 하는 일은 무엇이든 따라야 한다","mis":"SO6-1-u1-X17"},{"t":"학생은 나라 일에 관심을 갖지 않아도 된다","mis":"SO6-1-u1-X16"}],"explanation":["시민이 바로잡았어요.","바른 선거가 바탕이에요.","민주주의의 밑거름이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L05_challenge#9','soc',6,1,'u1','L05','g6_1_soc_u1_L05_challenge','lesson_challenge','SO6-1-u1-C9',4,'mc','auto','시민 ㉠~㉢의 말과 4·19 혁명의 결과를 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X15','SO6-1-u1-X17']::text[],false,'{"seq":9,"concept":"SO6-1-u1-C9","difficulty":4,"kind":"mc","stem":"시민 ㉠~㉢의 말과 4·19 혁명의 결과를 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"부정한 선거가 국민의 큰 반발을 불러 결국 그 선거가 무효가 되었다","correct":true},{"t":"부정한 선거가 국민의 큰 지지를 받았다","mis":"SO6-1-u1-X15"},{"t":"부정한 선거와 4·19 혁명은 관계없다","mis":"SO6-1-u1-X15"},{"t":"부정한 선거로 대통령이 더 오래 집권했다","mis":"SO6-1-u1-X17"}],"explanation":["부정한 방법이 드러났어요.","국민이 반발했어요.","선거는 무효가 되었어요."],"asset":{"type":"speech","turns":[{"who":"어느 시민 ㉠","text":"돈이나 물건을 주며 어느 후보를 찍으라고 했어요."},{"who":"어느 시민 ㉡","text":"조를 짜서 투표하게 하고 조장이 누구를 찍는지 확인했어요."},{"who":"어느 시민 ㉢","text":"선거 전에 미리 표시해 둔 투표지가 투표함에서 나왔어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L05_challenge#10','soc',6,1,'u1','L05','g6_1_soc_u1_L05_challenge','lesson_challenge','SO6-1-u1-C10',4,'essay','teacher','4·19 혁명의 원인과 전개 과정, 결과를 차례대로 쓰고, 4·19 혁명의 의의를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-1-u1-C10","difficulty":4,"kind":"essay","stem":"4·19 혁명의 원인과 전개 과정, 결과를 차례대로 쓰고, 4·19 혁명의 의의를 쓰세요.","answer_guide":{"answer":"예: 이승만 정부가 계속 집권하려고 3·15 부정 선거를 벌인 것이 원인이다. 대구의 고등학생들이 먼저 맞섰고, 마산 시위에 나섰던 고등학생 김주열의 죽음이 알려지며 시위가 전국으로 퍼져 4월 19일에는 초등학생부터 대학교수까지 각계각층이 참여했다. 결국 이승만이 물러나고 부정 선거는 무효가 되었다. 4·19 혁명은 시민과 학생의 힘으로 민주적 절차를 무시한 정권을 무너뜨려 우리나라 민주주의 발전의 밑거름이 되었다.","scoring_points":["원인을 썼는가","전개 과정과 결과를 차례대로 썼는가","의의를 썼는가"]},"explanation":["원인은 부정 선거예요.","시위가 번지고 대통령이 물러났어요.","민주주의의 밑거름이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L06_basic#1','soc',6,1,'u1','L06','g6_1_soc_u1_L06_basic','lesson_basic','SO6-1-u1-C11',1,'mc','auto','법에 맞지 않는 방법으로 일어난 정치적인 변화를 무엇이라고 하나요?',ARRAY['SO6-1-u1-X18']::text[],false,'{"seq":1,"concept":"SO6-1-u1-C11","difficulty":1,"kind":"mc","stem":"법에 맞지 않는 방법으로 일어난 정치적인 변화를 무엇이라고 하나요?","options":[{"t":"정변","correct":true},{"t":"선거","mis":"SO6-1-u1-X18"},{"t":"개헌","mis":"SO6-1-u1-X18"},{"t":"합의","mis":"SO6-1-u1-X18"}],"explanation":["법에 맞지 않아요.","정치가 갑자기 바뀌어요.","정변이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L06_basic#2','soc',6,1,'u1','L06','g6_1_soc_u1_L06_basic','lesson_basic','SO6-1-u1-C11',1,'mc','auto','군인들이 또다시 정변을 일으켜 권력을 장악하자 시민들이 요구한 것은 무엇인가요?',ARRAY['SO6-1-u1-X18','SO6-1-u1-X24']::text[],false,'{"seq":2,"concept":"SO6-1-u1-C11","difficulty":1,"kind":"mc","stem":"군인들이 또다시 정변을 일으켜 권력을 장악하자 시민들이 요구한 것은 무엇인가요?","options":[{"t":"군인들의 퇴진과 민주화","correct":true},{"t":"군인들이 더 오래 권력을 잡는 것","mis":"SO6-1-u1-X18"},{"t":"부정 선거를 무효로 하는 것","mis":"SO6-1-u1-X24"},{"t":"공장을 더 많이 짓는 것","mis":"SO6-1-u1-X18"}],"explanation":["군인들이 권력을 잡았어요.","시민들은 물러나라고 했어요.","민주화를 요구했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L06_basic#3','soc',6,1,'u1','L06','g6_1_soc_u1_L06_basic','lesson_basic','SO6-1-u1-C11',1,'sa','auto','광주 시민이 계엄군에게 맞서려고 만든 무리를 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO6-1-u1-C11","difficulty":1,"kind":"sa","stem":"광주 시민이 계엄군에게 맞서려고 만든 무리를 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["시민군"],"explanation":["시민들이 만들었어요.","시민◯이에요.","시민군이에요."],"mis":"SO6-1-u1-X19"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L06_basic#4','soc',6,1,'u1','L06','g6_1_soc_u1_L06_basic','lesson_basic','SO6-1-u1-C11',1,'ox','auto','계엄군은 광주에서 일어나는 일을 다른 지역에 알리려고 노력했어요.',ARRAY['SO6-1-u1-X19']::text[],false,'{"seq":4,"concept":"SO6-1-u1-C11","difficulty":1,"kind":"ox","stem":"계엄군은 광주에서 일어나는 일을 다른 지역에 알리려고 노력했어요.","answer":"X","reason_options":[{"t":"알리려 한 것은 광주 시민이고, 계엄군은 길을 막고 신문과 방송을 통제했기 때문에","correct":true},{"t":"계엄군이 신문과 방송으로 광주 소식을 널리 전했기 때문에","mis":"SO6-1-u1-X19"}],"mis":"SO6-1-u1-X19","explanation":["알리려 한 쪽은 시민이에요.","계엄군은 막았어요.","그래서 X예요."],"asset":{"type":"passage","lines":["① 군인들이 정변을 일으켜 다시 권력을 차지했다.","② 시민들이 군인들의 퇴진과 민주화를 요구했다.","③ 광주에서 큰 민주화 시위가 일어나자 계엄군이 들어왔다.","④ 시민들은 시민군을 만들어 맞서고 바깥에 알리려 했다.","⑤ 계엄군은 길을 막고 신문과 방송을 통제했다.","⑥ 외국인 기자들이 광주의 일을 영상과 사진에 담아 세계에 알렸다."],"title":"5·18 민주화 운동 흐름 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L06_basic#5','soc',6,1,'u1','L06','g6_1_soc_u1_L06_basic','lesson_basic','SO6-1-u1-C11',2,'mc','auto','전쟁 등 국가 비상사태가 일어났을 때 질서 유지를 목적으로 활용한 군대를 무엇이라고 하나요?',ARRAY['SO6-1-u1-X19','SO6-1-u1-X18','SO6-1-u1-X24']::text[],false,'{"seq":5,"concept":"SO6-1-u1-C11","difficulty":2,"kind":"mc","stem":"전쟁 등 국가 비상사태가 일어났을 때 질서 유지를 목적으로 활용한 군대를 무엇이라고 하나요?","options":[{"t":"계엄군","correct":true},{"t":"시민군","mis":"SO6-1-u1-X19"},{"t":"단일팀","mis":"SO6-1-u1-X18"},{"t":"선거인단","mis":"SO6-1-u1-X24"}],"explanation":["비상사태에 활용해요.","질서 유지가 목적이었어요.","계엄군이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L06_basic#6','soc',6,1,'u1','L06','g6_1_soc_u1_L06_basic','lesson_basic','SO6-1-u1-C11',2,'mc','auto','5·18 민주화 운동 흐름 메모에서 ⑤처럼 계엄군이 길을 막고 신문과 방송을 통제한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X19']::text[],false,'{"seq":6,"concept":"SO6-1-u1-C11","difficulty":2,"kind":"mc","stem":"5·18 민주화 운동 흐름 메모에서 ⑤처럼 계엄군이 길을 막고 신문과 방송을 통제한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"광주에서 일어나는 일이 바깥에 알려지지 않게 하려고","correct":true},{"t":"광주 소식을 더 빨리 알리려고","mis":"SO6-1-u1-X19"},{"t":"시민들의 시위를 돕기 위해","mis":"SO6-1-u1-X19"},{"t":"외국인 기자를 초대하려고","mis":"SO6-1-u1-X19"}],"explanation":["길과 방송을 막았어요.","바깥은 알 수 없었어요.","알려지지 않게 하려 했어요."],"asset":{"type":"passage","lines":["① 군인들이 정변을 일으켜 다시 권력을 차지했다.","② 시민들이 군인들의 퇴진과 민주화를 요구했다.","③ 광주에서 큰 민주화 시위가 일어나자 계엄군이 들어왔다.","④ 시민들은 시민군을 만들어 맞서고 바깥에 알리려 했다.","⑤ 계엄군은 길을 막고 신문과 방송을 통제했다.","⑥ 외국인 기자들이 광주의 일을 영상과 사진에 담아 세계에 알렸다."],"title":"5·18 민주화 운동 흐름 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L06_basic#7','soc',6,1,'u1','L06','g6_1_soc_u1_L06_basic','lesson_basic','SO6-1-u1-C11',2,'mc','auto','외국인 기자들이 광주에서 한 일로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X19']::text[],false,'{"seq":7,"concept":"SO6-1-u1-C11","difficulty":2,"kind":"mc","stem":"외국인 기자들이 광주에서 한 일로 알맞은 것은 어느 것인가요?","options":[{"t":"목숨을 걸고 광주에 들어가 그곳의 일을 영상과 사진에 담아 세계에 알렸다","correct":true},{"t":"광주로 가는 길을 막았다","mis":"SO6-1-u1-X19"},{"t":"방송을 통제했다","mis":"SO6-1-u1-X19"},{"t":"광주의 일을 숨기려 했다","mis":"SO6-1-u1-X19"}],"explanation":["기자들이 들어갔어요.","영상과 사진에 담았어요.","세계에 알렸어요."],"asset":{"type":"passage","lines":["① 군인들이 정변을 일으켜 다시 권력을 차지했다.","② 시민들이 군인들의 퇴진과 민주화를 요구했다.","③ 광주에서 큰 민주화 시위가 일어나자 계엄군이 들어왔다.","④ 시민들은 시민군을 만들어 맞서고 바깥에 알리려 했다.","⑤ 계엄군은 길을 막고 신문과 방송을 통제했다.","⑥ 외국인 기자들이 광주의 일을 영상과 사진에 담아 세계에 알렸다."],"title":"5·18 민주화 운동 흐름 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L06_basic#8','soc',6,1,'u1','L06','g6_1_soc_u1_L06_basic','lesson_basic','SO6-1-u1-C11',2,'blank','auto','5·18 민주화 운동은 폭력적인 정부에 맞서 (    )를 지키려는 시민의 의지를 보여 주었어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-1-u1-X18']::text[],false,'{"seq":8,"concept":"SO6-1-u1-C11","difficulty":2,"kind":"blank","stem":"5·18 민주화 운동은 폭력적인 정부에 맞서 (    )를 지키려는 시민의 의지를 보여 주었어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"민주주의","correct":true},{"t":"경제 개발","mis":"SO6-1-u1-X18"},{"t":"국방비","mis":"SO6-1-u1-X18"},{"t":"정변","mis":"SO6-1-u1-X18"}],"explanation":["시민들이 지키려 했어요.","민주화를 요구했어요.","민주주의예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L06_basic#9','soc',6,1,'u1','L06','g6_1_soc_u1_L06_basic','lesson_basic','SO6-1-u1-C11',2,'mc','auto','5·18 민주화 운동 흐름 메모 ①~⑥ 가운데 이 운동이 일어난 원인에 해당하는 것은 어느 것인가요?',ARRAY['SO6-1-u1-X18']::text[],false,'{"seq":9,"concept":"SO6-1-u1-C11","difficulty":2,"kind":"mc","stem":"5·18 민주화 운동 흐름 메모 ①~⑥ 가운데 이 운동이 일어난 원인에 해당하는 것은 어느 것인가요?","options":[{"t":"①","correct":true},{"t":"⑥","mis":"SO6-1-u1-X18"},{"t":"④","mis":"SO6-1-u1-X18"},{"t":"⑤","mis":"SO6-1-u1-X18"}],"explanation":["먼저 일어난 일을 봐요.","군인들이 권력을 차지했어요.","①이 원인이에요."],"asset":{"type":"passage","lines":["① 군인들이 정변을 일으켜 다시 권력을 차지했다.","② 시민들이 군인들의 퇴진과 민주화를 요구했다.","③ 광주에서 큰 민주화 시위가 일어나자 계엄군이 들어왔다.","④ 시민들은 시민군을 만들어 맞서고 바깥에 알리려 했다.","⑤ 계엄군은 길을 막고 신문과 방송을 통제했다.","⑥ 외국인 기자들이 광주의 일을 영상과 사진에 담아 세계에 알렸다."],"title":"5·18 민주화 운동 흐름 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L06_basic#10','soc',6,1,'u1','L06','g6_1_soc_u1_L06_basic','lesson_basic','SO6-1-u1-C11',3,'mc','auto','어느 시민의 기록을 보고 알 수 있는 사실로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X19']::text[],false,'{"seq":10,"concept":"SO6-1-u1-C11","difficulty":3,"kind":"mc","stem":"어느 시민의 기록을 보고 알 수 있는 사실로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"광주는 바깥과 막혀 있었고 방송은 광주 시민을 사실과 다르게 그렸다","correct":true},{"t":"방송은 광주의 일을 사실대로 자세히 알렸다","mis":"SO6-1-u1-X19"},{"t":"바깥 사람들은 광주의 일을 모두 알고 있었다","mis":"SO6-1-u1-X19"},{"t":"계엄군이 들어온 뒤 아무 일도 없었다","mis":"SO6-1-u1-X19"}],"explanation":["방송이 사실과 달랐어요.","바깥은 알기 어려웠어요.","광주는 고립되어 있었어요."],"asset":{"type":"passage","lines":["계엄군이 들어온 뒤 많은 시민이 목숨을 잃었다.","그런데 방송은 광주 시민을 사실과 다르게 몰아갔다.","바깥 사람들은 광주에서 무슨 일이 있는지 알기 어려웠다."],"title":"어느 시민의 기록을 내 말로 줄인 것"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L06_challenge#1','soc',6,1,'u1','L06','g6_1_soc_u1_L06_challenge','lesson_challenge','SO6-1-u1-C11',2,'sa','auto','전쟁 등 국가 비상사태에 질서 유지를 목적으로 활용한 군대로, 광주에 보내진 군대를 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-1-u1-C11","difficulty":2,"kind":"sa","stem":"전쟁 등 국가 비상사태에 질서 유지를 목적으로 활용한 군대로, 광주에 보내진 군대를 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["계엄군"],"explanation":["비상사태의 군대예요.","계엄◯이에요.","계엄군이에요."],"mis":"SO6-1-u1-X19"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L06_challenge#2','soc',6,1,'u1','L06','g6_1_soc_u1_L06_challenge','lesson_challenge','SO6-1-u1-C11',2,'ox','auto','5·18 민주화 운동은 우리나라뿐 아니라 세계 여러 나라의 민주화 운동에도 영향을 주었어요.',ARRAY['SO6-1-u1-X20']::text[],false,'{"seq":2,"concept":"SO6-1-u1-C11","difficulty":2,"kind":"ox","stem":"5·18 민주화 운동은 우리나라뿐 아니라 세계 여러 나라의 민주화 운동에도 영향을 주었어요.","answer":"O","reason_options":[{"t":"폭력에 맞서 민주주의를 지키려 한 시민의 의지가 널리 알려졌기 때문에","correct":true},{"t":"광주 한 도시 안에서만 기억되고 끝난 일이기 때문에","mis":"SO6-1-u1-X20"}],"mis":"SO6-1-u1-X20","explanation":["진실이 세계에 알려졌어요.","여러 나라에 영향을 주었어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L06_challenge#3','soc',6,1,'u1','L06','g6_1_soc_u1_L06_challenge','lesson_challenge','SO6-1-u1-C11',3,'mc','auto','흐름 메모의 ④와 ⑤를 견주어 보았을 때 가장 알맞은 설명은 어느 것인가요?',ARRAY['SO6-1-u1-X19']::text[],false,'{"seq":3,"concept":"SO6-1-u1-C11","difficulty":3,"kind":"mc","stem":"흐름 메모의 ④와 ⑤를 견주어 보았을 때 가장 알맞은 설명은 어느 것인가요?","options":[{"t":"시민은 바깥에 알리려 했고, 계엄군은 알려지지 않게 막았다","correct":true},{"t":"시민과 계엄군 모두 바깥에 알리려 했다","mis":"SO6-1-u1-X19"},{"t":"계엄군은 알리려 했고 시민은 숨기려 했다","mis":"SO6-1-u1-X19"},{"t":"둘 다 바깥과 아무 관계가 없었다","mis":"SO6-1-u1-X19"}],"explanation":["④는 시민의 일이에요.","⑤는 계엄군의 일이에요.","알리려는 쪽과 막는 쪽이에요."],"asset":{"type":"passage","lines":["① 군인들이 정변을 일으켜 다시 권력을 차지했다.","② 시민들이 군인들의 퇴진과 민주화를 요구했다.","③ 광주에서 큰 민주화 시위가 일어나자 계엄군이 들어왔다.","④ 시민들은 시민군을 만들어 맞서고 바깥에 알리려 했다.","⑤ 계엄군은 길을 막고 신문과 방송을 통제했다.","⑥ 외국인 기자들이 광주의 일을 영상과 사진에 담아 세계에 알렸다."],"title":"5·18 민주화 운동 흐름 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L06_challenge#4','soc',6,1,'u1','L06','g6_1_soc_u1_L06_challenge','lesson_challenge','SO6-1-u1-C11',3,'mc','auto','5·18 민주화 운동이 일어난 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X18']::text[],false,'{"seq":4,"concept":"SO6-1-u1-C11","difficulty":3,"kind":"mc","stem":"5·18 민주화 운동이 일어난 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"군인들이 정변으로 권력을 장악하자 시민들이 퇴진과 민주화를 요구했기 때문에","correct":true},{"t":"정부가 부정 선거로 계속 집권하려 했기 때문에","mis":"SO6-1-u1-X18"},{"t":"국민이 처음으로 대통령을 직접 뽑으려 했기 때문에","mis":"SO6-1-u1-X18"},{"t":"경제 개발 계획에 반대했기 때문에","mis":"SO6-1-u1-X18"}],"explanation":["군인들이 권력을 잡았어요.","시민들이 민주화를 요구했어요.","그것이 원인이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L06_challenge#5','soc',6,1,'u1','L06','g6_1_soc_u1_L06_challenge','lesson_challenge','SO6-1-u1-C11',3,'mc','auto','당시 기자들이 광주의 모습을 사진과 영상으로 남긴 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X19']::text[],false,'{"seq":5,"concept":"SO6-1-u1-C11","difficulty":3,"kind":"mc","stem":"당시 기자들이 광주의 모습을 사진과 영상으로 남긴 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"막혀 있던 광주의 일을 바깥과 세계에 알리고 싶었기 때문에","correct":true},{"t":"광주를 관광지로 소개하려고","mis":"SO6-1-u1-X19"},{"t":"계엄군의 일을 숨기려고","mis":"SO6-1-u1-X19"},{"t":"사진 대회에 내려고","mis":"SO6-1-u1-X19"}],"explanation":["광주는 막혀 있었어요.","기록이 있어야 알 수 있어요.","세계에 알리고 싶었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L06_challenge#6','soc',6,1,'u1','L06','g6_1_soc_u1_L06_challenge','lesson_challenge','SO6-1-u1-C11',3,'error','auto','5·18 민주화 운동을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u1-X19','SO6-1-u1-X20']::text[],false,'{"seq":6,"concept":"SO6-1-u1-C11","difficulty":3,"kind":"error","stem":"5·18 민주화 운동을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「계엄군이 광주 소식을 신문과 방송으로 널리 알렸어.」","correct":true,"mis_target":"SO6-1-u1-X19"},{"t":"친구 나 — 「광주 시민은 시민군을 만들어 맞섰어.」","mis":"SO6-1-u1-X19"},{"t":"친구 다 — 「외국인 기자들 덕분에 진실이 세계에 알려졌어.」","mis":"SO6-1-u1-X20"}],"explanation":["계엄군은 막았어요.","알리려 한 것은 시민이에요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L06_challenge#7','soc',6,1,'u1','L06','g6_1_soc_u1_L06_challenge','lesson_challenge','SO6-1-u1-C11',3,'ox','auto','오늘날 우리가 5·18 민주화 운동의 진실을 알 수 있는 것은 그때 기록을 남기고 알린 사람들이 있었기 때문이에요.',ARRAY['SO6-1-u1-X19']::text[],false,'{"seq":7,"concept":"SO6-1-u1-C11","difficulty":3,"kind":"ox","stem":"오늘날 우리가 5·18 민주화 운동의 진실을 알 수 있는 것은 그때 기록을 남기고 알린 사람들이 있었기 때문이에요.","answer":"O","reason_options":[{"t":"바깥이 막혀 있을 때 기록을 남기고 영상을 담은 사람들이 진실을 전했기 때문에","correct":true},{"t":"그때 신문과 방송이 모든 일을 자유롭게 보도했기 때문에","mis":"SO6-1-u1-X19"}],"mis":"SO6-1-u1-X19","explanation":["바깥은 막혀 있었어요.","기록하고 알린 사람이 있었어요.","그래서 오늘 알 수 있어요."],"asset":{"type":"passage","lines":["계엄군이 들어온 뒤 많은 시민이 목숨을 잃었다.","그런데 방송은 광주 시민을 사실과 다르게 몰아갔다.","바깥 사람들은 광주에서 무슨 일이 있는지 알기 어려웠다."],"title":"어느 시민의 기록을 내 말로 줄인 것"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L06_challenge#8','soc',6,1,'u1','L06','g6_1_soc_u1_L06_challenge','lesson_challenge','SO6-1-u1-C11',4,'mc','auto','5·18 민주화 운동의 의의를 가장 바르게 정리한 것은 어느 것인가요?',ARRAY['SO6-1-u1-X20','SO6-1-u1-X18']::text[],false,'{"seq":8,"concept":"SO6-1-u1-C11","difficulty":4,"kind":"mc","stem":"5·18 민주화 운동의 의의를 가장 바르게 정리한 것은 어느 것인가요?","options":[{"t":"폭력적인 정부에 맞서 민주주의를 지키려는 시민의 의지를 보여 주었고, 세계 여러 나라의 민주화 운동에도 영향을 주었다","correct":true},{"t":"광주 한 도시의 일로만 남았다","mis":"SO6-1-u1-X20"},{"t":"군인들이 권력을 잡는 데 도움이 되었다","mis":"SO6-1-u1-X18"},{"t":"정부가 바르게 일하고 있음을 보여 주었다","mis":"SO6-1-u1-X20"}],"explanation":["시민의 의지를 보여 주었어요.","세계에도 영향을 주었어요.","두 가지가 의의예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L06_challenge#9','soc',6,1,'u1','L06','g6_1_soc_u1_L06_challenge','lesson_challenge','SO6-1-u1-C11',4,'mc','auto','5·18 민주화 운동에서 희생된 사람들을 대하는 마음으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X20']::text[],false,'{"seq":9,"concept":"SO6-1-u1-C11","difficulty":4,"kind":"mc","stem":"5·18 민주화 운동에서 희생된 사람들을 대하는 마음으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"민주주의를 지키려 한 뜻을 기억하고 기리는 마음","correct":true},{"t":"오래된 일이니 잊어도 된다는 마음","mis":"SO6-1-u1-X20"},{"t":"남의 지역 일이라 상관없다는 마음","mis":"SO6-1-u1-X20"},{"t":"무서운 이야기로만 여기는 마음","mis":"SO6-1-u1-X20"}],"explanation":["민주주의를 지키려 했어요.","그 뜻을 기억해요.","기리는 마음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L06_challenge#10','soc',6,1,'u1','L06','g6_1_soc_u1_L06_challenge','lesson_challenge','SO6-1-u1-C11',4,'essay','teacher','5·18 민주화 운동이 일어난 원인과 광주 시민·계엄군·외국인 기자가 한 일을 쓰고, 이 운동의 의의를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-1-u1-C11","difficulty":4,"kind":"essay","stem":"5·18 민주화 운동이 일어난 원인과 광주 시민·계엄군·외국인 기자가 한 일을 쓰고, 이 운동의 의의를 쓰세요.","answer_guide":{"answer":"예: 군인들이 또다시 정변을 일으켜 권력을 장악하자 시민들이 퇴진과 민주화를 요구한 것이 원인이다. 광주 시민은 시민군을 만들어 맞서고 광주의 일을 바깥에 알리려 했으나, 계엄군은 길을 막고 신문과 방송을 통제했다. 외국인 기자들은 목숨을 걸고 광주에 들어가 진실을 세계에 알렸다. 5·18 민주화 운동은 폭력적인 정부에 맞서 민주주의를 지키려는 시민의 의지를 보여 주었고 세계 여러 나라의 민주화 운동에도 영향을 주었다.","scoring_points":["원인을 썼는가","시민·계엄군·기자가 한 일을 구분해 썼는가","의의를 썼는가"]},"explanation":["군인들의 권력 장악이 원인이에요.","알리려는 쪽과 막는 쪽을 나눠요.","세계에도 영향을 주었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L07_basic#1','soc',6,1,'u1','L07','g6_1_soc_u1_L07_basic','lesson_basic','SO6-1-u1-C12',1,'mc','auto','일정 수의 선거인단이 대표를 뽑는 선거 제도를 무엇이라고 하나요?',ARRAY['SO6-1-u1-X21','SO6-1-u1-X23']::text[],false,'{"seq":1,"concept":"SO6-1-u1-C12","difficulty":1,"kind":"mc","stem":"일정 수의 선거인단이 대표를 뽑는 선거 제도를 무엇이라고 하나요?","options":[{"t":"간선제","correct":true},{"t":"직선제","mis":"SO6-1-u1-X21"},{"t":"지방 자치제","mis":"SO6-1-u1-X23"},{"t":"정부통령 선거","mis":"SO6-1-u1-X21"}],"explanation":["선거인단이 뽑아요.","국민이 직접 뽑지 않아요.","간선제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L07_basic#2','soc',6,1,'u1','L07','g6_1_soc_u1_L07_basic','lesson_basic','SO6-1-u1-C12',1,'mc','auto','국민이 직접 대표를 뽑는 선거 제도를 무엇이라고 하나요?',ARRAY['SO6-1-u1-X21']::text[],false,'{"seq":2,"concept":"SO6-1-u1-C12","difficulty":1,"kind":"mc","stem":"국민이 직접 대표를 뽑는 선거 제도를 무엇이라고 하나요?","options":[{"t":"직선제","correct":true},{"t":"간선제","mis":"SO6-1-u1-X21"},{"t":"선거인단","mis":"SO6-1-u1-X21"},{"t":"개헌","mis":"SO6-1-u1-X21"}],"explanation":["국민이 직접 뽑아요.","곧을 직, 가릴 선이에요.","직선제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L07_basic#3','soc',6,1,'u1','L07','g6_1_soc_u1_L07_basic','lesson_basic','SO6-1-u1-C12',1,'sa','auto','헌법을 고치는 것을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO6-1-u1-C12","difficulty":1,"kind":"sa","stem":"헌법을 고치는 것을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["개헌"],"explanation":["헌법을 고쳐요.","◯헌이에요.","개헌이에요."],"mis":"SO6-1-u1-X22"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L07_basic#4','soc',6,1,'u1','L07','g6_1_soc_u1_L07_basic','lesson_basic','SO6-1-u1-C13',1,'ox','auto','6월 민주 항쟁 이후 대통령 직선제와 지방 자치제가 시행되었어요.',ARRAY['SO6-1-u1-X23']::text[],false,'{"seq":4,"concept":"SO6-1-u1-C13","difficulty":1,"kind":"ox","stem":"6월 민주 항쟁 이후 대통령 직선제와 지방 자치제가 시행되었어요.","answer":"O","reason_options":[{"t":"정부가 대통령 직선제를 포함한 국민의 민주화 요구를 받아들였기 때문에","correct":true},{"t":"6월 민주 항쟁 뒤 선거가 모두 없어졌기 때문에","mis":"SO6-1-u1-X23"}],"mis":"SO6-1-u1-X23","explanation":["요구가 받아들여졌어요.","직선제가 시행됐어요.","지방 자치제도 다시 시행됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L07_basic#5','soc',6,1,'u1','L07','g6_1_soc_u1_L07_basic','lesson_basic','SO6-1-u1-C12',2,'mc','auto','간선제로 대통령이 된 정부가 한 일로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X22','SO6-1-u1-X23']::text[],false,'{"seq":5,"concept":"SO6-1-u1-C12","difficulty":2,"kind":"mc","stem":"간선제로 대통령이 된 정부가 한 일로 알맞은 것은 어느 것인가요?","options":[{"t":"언론을 통제하고 민주화 운동을 탄압했다","correct":true},{"t":"시민들의 요구를 모두 받아들였다","mis":"SO6-1-u1-X22"},{"t":"곧바로 직선제를 시행했다","mis":"SO6-1-u1-X22"},{"t":"지방 자치제를 바로 시작했다","mis":"SO6-1-u1-X23"}],"explanation":["언론을 막았어요.","민주화 운동을 누르려 했어요.","그래서 시민들이 나섰어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L07_basic#6','soc',6,1,'u1','L07','g6_1_soc_u1_L07_basic','lesson_basic','SO6-1-u1-C12',2,'mc','auto','대학생 박종철이 경찰 조사 중 목숨을 잃은 일이 알려진 뒤 시민들이 시위하며 요구한 것은 무엇인가요?',ARRAY['SO6-1-u1-X22','SO6-1-u1-X24']::text[],false,'{"seq":6,"concept":"SO6-1-u1-C12","difficulty":2,"kind":"mc","stem":"대학생 박종철이 경찰 조사 중 목숨을 잃은 일이 알려진 뒤 시민들이 시위하며 요구한 것은 무엇인가요?","options":[{"t":"직선제 개헌","correct":true},{"t":"간선제 유지","mis":"SO6-1-u1-X22"},{"t":"선거 없애기","mis":"SO6-1-u1-X22"},{"t":"부정 선거 무효","mis":"SO6-1-u1-X24"}],"explanation":["대통령을 직접 뽑고 싶었어요.","헌법을 고쳐야 했어요.","직선제 개헌이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L07_basic#7','soc',6,1,'u1','L07','g6_1_soc_u1_L07_basic','lesson_basic','SO6-1-u1-C12',2,'mc','auto','시민들의 직선제 요구에 대해 정부가 처음에 한 일은 무엇인가요?',ARRAY['SO6-1-u1-X22','SO6-1-u1-X24']::text[],false,'{"seq":7,"concept":"SO6-1-u1-C12","difficulty":2,"kind":"mc","stem":"시민들의 직선제 요구에 대해 정부가 처음에 한 일은 무엇인가요?","options":[{"t":"직선제 요구를 받아들이지 않고 간선제를 유지하겠다고 발표했다","correct":true},{"t":"곧바로 직선제를 시행했다","mis":"SO6-1-u1-X22"},{"t":"지방 자치제를 바로 시작했다","mis":"SO6-1-u1-X22"},{"t":"스스로 물러났다","mis":"SO6-1-u1-X24"}],"explanation":["처음에는 거부했어요.","간선제를 지키려 했어요.","그래서 시위가 더 번졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L07_basic#8','soc',6,1,'u1','L07','g6_1_soc_u1_L07_basic','lesson_basic','SO6-1-u1-C13',2,'match','auto','6월 민주 항쟁 뒤 달라진 모습 카드와 그 이름을 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"SO6-1-u1-C13","difficulty":2,"kind":"match","stem":"6월 민주 항쟁 뒤 달라진 모습 카드와 그 이름을 알맞게 이으세요.","pairs":[{"l":"㉠","r":"대통령 직선제 시행"},{"l":"㉡","r":"지방 자치제 시행"},{"l":"㉢","r":"시민 참여 확대"}],"mis":"SO6-1-u1-X23","explanation":["㉠은 대통령을 직접 뽑아요.","㉡은 지역 대표가 지역 일을 해요.","㉢은 시민 단체로 참여해요."],"asset":{"type":"passage","lines":["㉠ 국민이 직접 대통령을 뽑는 선거가 오늘날까지 이어진다.","㉡ 지역 주민이 뽑은 대표가 그 지역의 일을 처리한다.","㉢ 시민들이 시민 단체를 만들어 사회문제 해결에 참여한다."],"title":"6월 민주 항쟁 뒤 달라진 모습 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L07_basic#9','soc',6,1,'u1','L07','g6_1_soc_u1_L07_basic','lesson_basic','SO6-1-u1-C12',2,'mc','auto','6월 민주 항쟁 상황 일지를 보고 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X22','SO6-1-u1-X21']::text[],false,'{"seq":9,"concept":"SO6-1-u1-C12","difficulty":2,"kind":"mc","stem":"6월 민주 항쟁 상황 일지를 보고 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"시간이 지날수록 모인 사람이 늘어나며 직선제를 요구했다","correct":true},{"t":"사람들이 금방 흩어졌다","mis":"SO6-1-u1-X22"},{"t":"사람들이 간선제를 지키자고 외쳤다","mis":"SO6-1-u1-X21"},{"t":"아무도 구호를 외치지 않았다","mis":"SO6-1-u1-X22"}],"explanation":["저녁이 되며 사람이 늘었어요.","횃불을 들고 외쳤어요.","직선제를 요구했어요."],"asset":{"type":"passage","lines":["오후 다섯 시 — 시민과 학생들이 어느 성당 앞으로 모였다.","저녁 여덟 시 — 모인 사람이 점점 더 늘어났다.","밤 아홉 시 반 — 사람들이 횃불을 들고 구호를 외쳤다.","사람들이 외친 구호 — 「직선제로 민주 정부를!」"],"title":"6월 민주 항쟁 상황 일지(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L07_basic#10','soc',6,1,'u1','L07','g6_1_soc_u1_L07_basic','lesson_basic','SO6-1-u1-C12',3,'mc','auto','같은 요구를 계속했는데 마지막에 정부가 받아들인 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X22']::text[],false,'{"seq":10,"concept":"SO6-1-u1-C12","difficulty":3,"kind":"mc","stem":"같은 요구를 계속했는데 마지막에 정부가 받아들인 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"독재 반대와 직선제를 요구하는 시위가 전국으로 퍼져 함께한 사람이 크게 늘었기 때문에","correct":true},{"t":"요구를 바꾸어 간선제를 요구했기 때문에","mis":"SO6-1-u1-X22"},{"t":"정부가 처음부터 직선제를 원했기 때문에","mis":"SO6-1-u1-X22"},{"t":"시위가 한 곳에서만 조용히 끝났기 때문에","mis":"SO6-1-u1-X22"}],"explanation":["요구는 그대로였어요.","함께한 사람이 늘었어요.","전국에서 일어났어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L07_challenge#1','soc',6,1,'u1','L07','g6_1_soc_u1_L07_challenge','lesson_challenge','SO6-1-u1-C13',2,'sa','auto','국가의 중요한 일을 결정하는 권리를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-1-u1-C13","difficulty":2,"kind":"sa","stem":"국가의 중요한 일을 결정하는 권리를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["주권"],"explanation":["국가의 중요한 일을 정해요.","주인의 권리예요.","주권이에요."],"mis":"SO6-1-u1-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L07_challenge#2','soc',6,1,'u1','L07','g6_1_soc_u1_L07_challenge','lesson_challenge','SO6-1-u1-C12',2,'ox','auto','간선제는 국민 한 사람 한 사람이 직접 대통령을 뽑는 선거 제도예요.',ARRAY['SO6-1-u1-X21']::text[],false,'{"seq":2,"concept":"SO6-1-u1-C12","difficulty":2,"kind":"ox","stem":"간선제는 국민 한 사람 한 사람이 직접 대통령을 뽑는 선거 제도예요.","answer":"X","reason_options":[{"t":"간선제는 일정 수의 선거인단이 대표를 뽑는 제도이고, 국민이 직접 뽑는 것은 직선제이기 때문에","correct":true},{"t":"간선제와 직선제는 뜻이 같기 때문에","mis":"SO6-1-u1-X21"}],"mis":"SO6-1-u1-X21","explanation":["간선제는 선거인단이 뽑아요.","직접 뽑는 것은 직선제예요.","둘을 바꾸었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L07_challenge#3','soc',6,1,'u1','L07','g6_1_soc_u1_L07_challenge','lesson_challenge','SO6-1-u1-C12',3,'mc','auto','6월 민주 항쟁의 전개 과정을 차례대로 바르게 늘어놓은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X22']::text[],false,'{"seq":3,"concept":"SO6-1-u1-C12","difficulty":3,"kind":"mc","stem":"6월 민주 항쟁의 전개 과정을 차례대로 바르게 늘어놓은 것은 어느 것인가요?","options":[{"t":"대학생이 목숨을 잃음 → 직선제 개헌 요구 → 정부의 거부 → 전국으로 시위가 퍼짐 → 요구를 받아들임","correct":true},{"t":"직선제 시행 → 대학생이 목숨을 잃음 → 정부의 거부 → 요구 → 시위","mis":"SO6-1-u1-X22"},{"t":"정부의 거부 → 요구를 받아들임 → 직선제 개헌 요구 → 시위가 퍼짐","mis":"SO6-1-u1-X22"},{"t":"전국으로 시위가 퍼짐 → 직선제 시행 → 직선제 개헌 요구 → 정부의 거부","mis":"SO6-1-u1-X22"}],"explanation":["먼저 안타까운 일이 알려졌어요.","요구했지만 거부당했어요.","전국으로 퍼져 받아들여졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L07_challenge#4','soc',6,1,'u1','L07','g6_1_soc_u1_L07_challenge','lesson_challenge','SO6-1-u1-C13',3,'mc','auto','6월 민주 항쟁 뒤 치른 대통령 선거에 많은 사람이 길게 줄지어 투표한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X23','SO6-1-u1-X21']::text[],false,'{"seq":4,"concept":"SO6-1-u1-C13","difficulty":3,"kind":"mc","stem":"6월 민주 항쟁 뒤 치른 대통령 선거에 많은 사람이 길게 줄지어 투표한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"국민이 직접 대통령을 뽑는 직선제가 이루어졌기 때문에","correct":true},{"t":"투표하면 선물을 받았기 때문에","mis":"SO6-1-u1-X23"},{"t":"선거인단만 투표할 수 있었기 때문에","mis":"SO6-1-u1-X21"},{"t":"투표가 의무라 벌을 받기 때문에","mis":"SO6-1-u1-X23"}],"explanation":["직접 뽑게 되었어요.","주권을 행사하고 싶었어요.","그래서 줄을 섰어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L07_challenge#5','soc',6,1,'u1','L07','g6_1_soc_u1_L07_challenge','lesson_challenge','SO6-1-u1-C13',3,'mc','auto','지방 자치제를 바르게 설명한 것은 어느 것인가요?',ARRAY['SO6-1-u1-X23','SO6-1-u1-X21']::text[],false,'{"seq":5,"concept":"SO6-1-u1-C13","difficulty":3,"kind":"mc","stem":"지방 자치제를 바르게 설명한 것은 어느 것인가요?","options":[{"t":"지역 주민이 뽑은 대표가 그 지역의 일을 처리하는 제도","correct":true},{"t":"나라에서 보낸 사람만 지역 일을 처리하는 제도","mis":"SO6-1-u1-X23"},{"t":"선거인단이 대통령을 뽑는 제도","mis":"SO6-1-u1-X21"},{"t":"시민 단체가 대통령을 뽑는 제도","mis":"SO6-1-u1-X23"}],"explanation":["지역 주민이 뽑아요.","그 대표가 지역 일을 해요.","지방 자치제예요."],"asset":{"type":"passage","lines":["㉠ 국민이 직접 대통령을 뽑는 선거가 오늘날까지 이어진다.","㉡ 지역 주민이 뽑은 대표가 그 지역의 일을 처리한다.","㉢ 시민들이 시민 단체를 만들어 사회문제 해결에 참여한다."],"title":"6월 민주 항쟁 뒤 달라진 모습 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L07_challenge#6','soc',6,1,'u1','L07','g6_1_soc_u1_L07_challenge','lesson_challenge','SO6-1-u1-C12',3,'error','auto','6월 민주 항쟁을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u1-X22']::text[],false,'{"seq":6,"concept":"SO6-1-u1-C12","difficulty":3,"kind":"error","stem":"6월 민주 항쟁을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「시민들은 간선제를 지키자고 시위했어.」","correct":true,"mis_target":"SO6-1-u1-X22"},{"t":"친구 가 — 「시민들은 직선제 개헌을 요구했어.」","mis":"SO6-1-u1-X22"},{"t":"친구 나 — 「정부는 처음에 그 요구를 거부했어.」","mis":"SO6-1-u1-X22"}],"explanation":["시민들은 직선제를 원했어요.","간선제를 지키려 한 것은 정부예요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L07_challenge#7','soc',6,1,'u1','L07','g6_1_soc_u1_L07_challenge','lesson_challenge','SO6-1-u1-C13',3,'mc','auto','6월 민주 항쟁이 우리나라 민주주의에 끼친 영향으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X23']::text[],false,'{"seq":7,"concept":"SO6-1-u1-C13","difficulty":3,"kind":"mc","stem":"6월 민주 항쟁이 우리나라 민주주의에 끼친 영향으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"여러 분야에 민주적인 제도가 만들어지고 시민의 영향력이 커졌다","correct":true},{"t":"대통령을 뽑는 일을 다시 선거인단에게만 맡겼다","mis":"SO6-1-u1-X23"},{"t":"시민이 사회문제에 참여할 길이 막혔다","mis":"SO6-1-u1-X23"},{"t":"지역의 일을 나라에서 모두 정하게 되었다","mis":"SO6-1-u1-X23"}],"explanation":["민주적인 제도가 생겼어요.","시민의 힘이 커졌어요.","민주주의가 더 발전했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L07_challenge#8','soc',6,1,'u1','L07','g6_1_soc_u1_L07_challenge','lesson_challenge','SO6-1-u1-C13',4,'mc','auto','6월 민주 항쟁이 사람들에게 준 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X22','SO6-1-u1-X23']::text[],false,'{"seq":8,"concept":"SO6-1-u1-C13","difficulty":4,"kind":"mc","stem":"6월 민주 항쟁이 사람들에게 준 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"시민의 힘으로 민주주의를 지켜 낼 수 있다는 자신감과 희망","correct":true},{"t":"정부의 결정은 바꿀 수 없다는 생각","mis":"SO6-1-u1-X22"},{"t":"선거는 필요 없다는 생각","mis":"SO6-1-u1-X23"},{"t":"시민이 나서면 아무것도 바뀌지 않는다는 생각","mis":"SO6-1-u1-X22"}],"explanation":["요구가 받아들여졌어요.","시민이 해냈어요.","자신감과 희망이 생겼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L07_challenge#9','soc',6,1,'u1','L07','g6_1_soc_u1_L07_challenge','lesson_challenge','SO6-1-u1-C13',4,'mc','auto','6월 민주 항쟁 전과 뒤를 견주어 대통령을 뽑는 방법이 어떻게 달라졌는지 가장 바르게 말한 것은 어느 것인가요?',ARRAY['SO6-1-u1-X21','SO6-1-u1-X23']::text[],false,'{"seq":9,"concept":"SO6-1-u1-C13","difficulty":4,"kind":"mc","stem":"6월 민주 항쟁 전과 뒤를 견주어 대통령을 뽑는 방법이 어떻게 달라졌는지 가장 바르게 말한 것은 어느 것인가요?","options":[{"t":"선거인단이 뽑던 방법에서 국민이 직접 뽑는 방법으로 바뀌었다","correct":true},{"t":"국민이 직접 뽑던 방법에서 선거인단이 뽑는 방법으로 바뀌었다","mis":"SO6-1-u1-X21"},{"t":"바뀐 것이 없다","mis":"SO6-1-u1-X23"},{"t":"대통령을 뽑지 않게 되었다","mis":"SO6-1-u1-X23"}],"explanation":["전에는 간선제였어요.","뒤에는 직선제예요.","국민이 직접 뽑아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L07_challenge#10','soc',6,1,'u1','L07','g6_1_soc_u1_L07_challenge','lesson_challenge','SO6-1-u1-C12',4,'essay','teacher','6월 민주 항쟁이 일어난 원인과 시민들의 요구, 정부의 대응을 쓰고, 6월 민주 항쟁으로 달라진 모습 두 가지를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-1-u1-C12","difficulty":4,"kind":"essay","stem":"6월 민주 항쟁이 일어난 원인과 시민들의 요구, 정부의 대응을 쓰고, 6월 민주 항쟁으로 달라진 모습 두 가지를 쓰세요.","answer_guide":{"answer":"예: 간선제로 대통령이 된 정부가 언론을 통제하고 민주화 운동을 탄압한 것이 원인이다. 시민들은 직선제 개헌을 요구했지만 정부는 거부했고, 시위가 전국으로 퍼지자 결국 직선제를 포함한 민주화 요구를 받아들였다. 그 뒤 국민이 직접 대통령을 뽑는 직선제가 시행되었고, 지역 주민이 뽑은 대표가 지역 일을 처리하는 지방 자치제도 다시 시행되었다.","scoring_points":["원인을 썼는가","시민의 요구와 정부의 대응을 썼는가","달라진 모습 두 가지를 썼는가"]},"explanation":["정부의 독재가 원인이에요.","직선제 요구 → 거부 → 받아들임이에요.","직선제와 지방 자치제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L08_basic#1','soc',6,1,'u1','L08','g6_1_soc_u1_L08_basic','lesson_basic','SO6-1-u1-C14',1,'mc','auto','신발, 가발, 의류처럼 무게가 적게 나가는 물건을 만드는 공업을 무엇이라고 하나요?',ARRAY['SO6-1-u1-X25']::text[],false,'{"seq":1,"concept":"SO6-1-u1-C14","difficulty":1,"kind":"mc","stem":"신발, 가발, 의류처럼 무게가 적게 나가는 물건을 만드는 공업을 무엇이라고 하나요?","options":[{"t":"경공업","correct":true},{"t":"중화학 공업","mis":"SO6-1-u1-X25"},{"t":"조선업","mis":"SO6-1-u1-X25"},{"t":"석유 화학 공업","mis":"SO6-1-u1-X25"}],"explanation":["가벼운 물건이에요.","가벼울 경을 써요.","경공업이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L08_basic#2','soc',6,1,'u1','L08','g6_1_soc_u1_L08_basic','lesson_basic','SO6-1-u1-C14',1,'mc','auto','1970년대에 정부가 발전시킨 철강, 조선, 석유 화학 같은 공업을 무엇이라고 하나요?',ARRAY['SO6-1-u1-X25','SO6-1-u1-X26']::text[],false,'{"seq":2,"concept":"SO6-1-u1-C14","difficulty":1,"kind":"mc","stem":"1970년대에 정부가 발전시킨 철강, 조선, 석유 화학 같은 공업을 무엇이라고 하나요?","options":[{"t":"중화학 공업","correct":true},{"t":"경공업","mis":"SO6-1-u1-X25"},{"t":"농업","mis":"SO6-1-u1-X26"},{"t":"수산업","mis":"SO6-1-u1-X26"}],"explanation":["무거운 물건과 화학 제품이에요.","높은 기술력이 필요해요.","중화학 공업이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L08_basic#3','soc',6,1,'u1','L08','g6_1_soc_u1_L08_basic','lesson_basic','SO6-1-u1-C15',1,'sa','auto','1960년대 정부가 수출을 통해 우리나라를 산업화하려고 추진한 계획은 「경제 개발 ◯개년 계획」이에요. ◯에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO6-1-u1-C15","difficulty":1,"kind":"sa","stem":"1960년대 정부가 수출을 통해 우리나라를 산업화하려고 추진한 계획은 「경제 개발 ◯개년 계획」이에요. ◯에 알맞은 수를 쓰세요.","answer":["5"],"explanation":["계획의 이름이에요.","몇 해씩 나누어 세웠어요.","5예요."],"mis":"SO6-1-u1-X27"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L08_basic#4','soc',6,1,'u1','L08','g6_1_soc_u1_L08_basic','lesson_basic','SO6-1-u1-C14',1,'ox','auto','1950년대에는 밀가루, 설탕, 면직물처럼 생활에 필요한 물건을 만드는 산업이 발달했어요.',ARRAY['SO6-1-u1-X26']::text[],false,'{"seq":4,"concept":"SO6-1-u1-C14","difficulty":1,"kind":"ox","stem":"1950년대에는 밀가루, 설탕, 면직물처럼 생활에 필요한 물건을 만드는 산업이 발달했어요.","answer":"O","reason_options":[{"t":"전쟁 뒤 여러 나라에서 지원받은 물자로 생활에 필요한 물건을 만들었기 때문에","correct":true},{"t":"1950년대에 이미 자동차와 전자 산업이 가장 발달했기 때문에","mis":"SO6-1-u1-X26"}],"mis":"SO6-1-u1-X26","explanation":["전쟁 뒤 물자를 지원받았어요.","생활에 필요한 물건을 만들었어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L08_basic#5','soc',6,1,'u1','L08','g6_1_soc_u1_L08_basic','lesson_basic','SO6-1-u1-C14',2,'match','auto','시대와 그때 발달한 산업을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO6-1-u1-C14","difficulty":2,"kind":"match","stem":"시대와 그때 발달한 산업을 알맞게 이으세요.","pairs":[{"l":"1950년대","r":"밀가루·설탕·면직물"},{"l":"1960년대","r":"신발·가발·의류 수출"},{"l":"1970년대","r":"철강·조선·석유 화학"},{"l":"1980년대","r":"자동차·정밀 기계·전자 제품"}],"mis":"SO6-1-u1-X26","explanation":["생활용품에서 시작했어요.","경공업, 중화학 공업이 이어졌어요.","그다음 자동차·전자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L08_basic#6','soc',6,1,'u1','L08','g6_1_soc_u1_L08_basic','lesson_basic','SO6-1-u1-C14',2,'mc','auto','1960년대에 우리나라가 경공업 제품을 만들어 수출할 수 있었던 바탕은 무엇인가요?',ARRAY['SO6-1-u1-X26','SO6-1-u1-X25']::text[],false,'{"seq":6,"concept":"SO6-1-u1-C14","difficulty":2,"kind":"mc","stem":"1960년대에 우리나라가 경공업 제품을 만들어 수출할 수 있었던 바탕은 무엇인가요?","options":[{"t":"풍부한 노동력","correct":true},{"t":"높은 기술력과 큰 연구소","mis":"SO6-1-u1-X26"},{"t":"넓은 땅과 많은 자원","mis":"SO6-1-u1-X25"},{"t":"자동차 공장","mis":"SO6-1-u1-X26"}],"explanation":["일할 사람이 많았어요.","가벼운 물건은 손이 많이 가요.","풍부한 노동력이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L08_basic#7','soc',6,1,'u1','L08','g6_1_soc_u1_L08_basic','lesson_basic','SO6-1-u1-C15',2,'mc','auto','제품의 생산, 운반, 수출을 위해 1960년대에 활발하게 지은 것을 묶은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X27']::text[],false,'{"seq":7,"concept":"SO6-1-u1-C15","difficulty":2,"kind":"mc","stem":"제품의 생산, 운반, 수출을 위해 1960년대에 활발하게 지은 것을 묶은 것은 어느 것인가요?","options":[{"t":"발전소, 고속 국도, 항만","correct":true},{"t":"놀이공원, 박물관, 공원","mis":"SO6-1-u1-X27"},{"t":"아파트, 학교, 병원","mis":"SO6-1-u1-X27"},{"t":"성당, 궁궐, 성곽","mis":"SO6-1-u1-X27"}],"explanation":["전기가 필요해요.","물건을 옮겨야 해요.","배로 실어 보내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L08_basic#8','soc',6,1,'u1','L08','g6_1_soc_u1_L08_basic','lesson_basic','SO6-1-u1-C15',2,'mc','auto','독일로 간 광부와 간호사가 우리나라 산업화에 도움이 된 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X27']::text[],false,'{"seq":8,"concept":"SO6-1-u1-C15","difficulty":2,"kind":"mc","stem":"독일로 간 광부와 간호사가 우리나라 산업화에 도움이 된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"그들이 벌어들인 외화가 산업화의 밑거름이 되었기 때문에","correct":true},{"t":"독일의 공장을 우리나라로 옮겨 왔기 때문에","mis":"SO6-1-u1-X27"},{"t":"독일에서 자동차를 만들어 팔았기 때문에","mis":"SO6-1-u1-X27"},{"t":"나라에서 그들에게 돈을 보내 주었기 때문에","mis":"SO6-1-u1-X27"}],"explanation":["외국에서 힘든 일을 했어요.","번 돈이 나라로 들어왔어요.","산업화의 밑거름이 되었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L08_basic#9','soc',6,1,'u1','L08','g6_1_soc_u1_L08_basic','lesson_basic','SO6-1-u1-C15',2,'blank','auto','1980년대에 국내 기업들은 세계에서 경쟁하려고 (    )을 연구하고 개발했어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-1-u1-X27']::text[],false,'{"seq":9,"concept":"SO6-1-u1-C15","difficulty":2,"kind":"blank","stem":"1980년대에 국내 기업들은 세계에서 경쟁하려고 (    )을 연구하고 개발했어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"기술","correct":true},{"t":"노래","mis":"SO6-1-u1-X27"},{"t":"날씨","mis":"SO6-1-u1-X27"},{"t":"옷차림","mis":"SO6-1-u1-X27"}],"explanation":["세계와 경쟁해야 했어요.","더 좋은 물건을 만들어야 해요.","기술이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L08_basic#10','soc',6,1,'u1','L08','g6_1_soc_u1_L08_basic','lesson_basic','SO6-1-u1-C14',3,'mc','auto','뒤섞인 산업 발달 카드를 시대 순서대로 바르게 늘어놓은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X26']::text[],false,'{"seq":10,"concept":"SO6-1-u1-C14","difficulty":3,"kind":"mc","stem":"뒤섞인 산업 발달 카드를 시대 순서대로 바르게 늘어놓은 것은 어느 것인가요?","options":[{"t":"㉰ → ㉱ → ㉮ → ㉯","correct":true},{"t":"㉮ → ㉯ → ㉰ → ㉱","mis":"SO6-1-u1-X26"},{"t":"㉱ → ㉰ → ㉯ → ㉮","mis":"SO6-1-u1-X26"},{"t":"㉰ → ㉮ → ㉱ → ㉯","mis":"SO6-1-u1-X26"}],"explanation":["생활용품이 먼저예요.","경공업 다음 중화학 공업이에요.","자동차·전자가 마지막이에요."],"asset":{"type":"passage","lines":["㉮ 철강·조선·석유 화학 같은 중화학 공업이 발달했다.","㉯ 자동차·정밀 기계·전자 제품 산업이 발달했다.","㉰ 밀가루·설탕·면직물처럼 생활에 필요한 물건을 만들었다.","㉱ 신발·가발·의류 같은 경공업 제품을 만들어 수출했다."],"title":"뒤섞인 산업 발달 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L08_challenge#1','soc',6,1,'u1','L08','g6_1_soc_u1_L08_challenge','lesson_challenge','SO6-1-u1-C14',2,'sa','auto','철·배처럼 무거운 물건과 플라스틱·고무 같은 화학 제품을 만드는 공업을 무엇이라고 하나요?','{}'::text[],false,'{"seq":1,"concept":"SO6-1-u1-C14","difficulty":2,"kind":"sa","stem":"철·배처럼 무거운 물건과 플라스틱·고무 같은 화학 제품을 만드는 공업을 무엇이라고 하나요?","answer":["중화학 공업","중화학공업"],"explanation":["무거운 물건이에요.","화학 제품도 함께예요.","중화학 공업이에요."],"mis":"SO6-1-u1-X25"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L08_challenge#2','soc',6,1,'u1','L08','g6_1_soc_u1_L08_challenge','lesson_challenge','SO6-1-u1-C14',2,'ox','auto','우리나라는 중화학 공업이 먼저 발달한 뒤에 경공업이 발달했어요.',ARRAY['SO6-1-u1-X26']::text[],false,'{"seq":2,"concept":"SO6-1-u1-C14","difficulty":2,"kind":"ox","stem":"우리나라는 중화학 공업이 먼저 발달한 뒤에 경공업이 발달했어요.","answer":"X","reason_options":[{"t":"1960년대 경공업이 먼저 발달하고 1970년대에 중화학 공업이 발달했기 때문에","correct":true},{"t":"무거운 물건을 만드는 공업은 기술이 덜 필요하기 때문에","mis":"SO6-1-u1-X26"}],"mis":"SO6-1-u1-X26","explanation":["경공업이 먼저예요.","중화학 공업은 1970년대예요.","차례가 거꾸로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L08_challenge#3','soc',6,1,'u1','L08','g6_1_soc_u1_L08_challenge','lesson_challenge','SO6-1-u1-C15',3,'mc','auto','1970년대에 정부가 교육 시설과 연구소를 세운 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X25','SO6-1-u1-X26','SO6-1-u1-X27']::text[],false,'{"seq":3,"concept":"SO6-1-u1-C15","difficulty":3,"kind":"mc","stem":"1970년대에 정부가 교육 시설과 연구소를 세운 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"높은 기술력이 필요한 중화학 공업을 발전시키려고","correct":true},{"t":"경공업 제품을 손으로 더 많이 만들려고","mis":"SO6-1-u1-X25"},{"t":"농업 중심으로 되돌아가려고","mis":"SO6-1-u1-X26"},{"t":"수출을 줄이려고","mis":"SO6-1-u1-X27"}],"explanation":["중화학 공업은 기술이 필요해요.","사람을 길러야 했어요.","그래서 교육 시설과 연구소를 세웠어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L08_challenge#4','soc',6,1,'u1','L08','g6_1_soc_u1_L08_challenge','lesson_challenge','SO6-1-u1-C15',3,'mc','auto','라면이 나온 까닭을 견주는 두 기사에서 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X27']::text[],false,'{"seq":4,"concept":"SO6-1-u1-C15","difficulty":3,"kind":"mc","stem":"라면이 나온 까닭을 견주는 두 기사에서 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"같은 물건이라도 시대 상황에 따라 만든 목적이 다를 수 있다","correct":true},{"t":"라면은 처음부터 수출만을 위해 만들었다","mis":"SO6-1-u1-X27"},{"t":"두 시대에 라면을 만든 까닭은 똑같다","mis":"SO6-1-u1-X27"},{"t":"라면은 산업 발달과 관계가 없다","mis":"SO6-1-u1-X27"}],"explanation":["옛날엔 먹을거리가 모자랐어요.","오늘은 수출 상품이에요.","목적이 달라졌어요."],"asset":{"type":"passage","lines":["옛 기사 — 먹을거리가 모자라던 때, 값싸고 배부른 음식으로 라면이 나왔다.","오늘 기사 — 라면이 여러 나라로 팔려 나가는 수출 상품이 되었다.","물음 — 두 기사 속 라면은 만든 까닭이 어떻게 다를까?"],"title":"라면이 나온 까닭을 견주는 두 기사(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L08_challenge#5','soc',6,1,'u1','L08','g6_1_soc_u1_L08_challenge','lesson_challenge','SO6-1-u1-C14',3,'mc','auto','정부가 경제 개발 계획을 추진한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X26','SO6-1-u1-X27']::text[],false,'{"seq":5,"concept":"SO6-1-u1-C14","difficulty":3,"kind":"mc","stem":"정부가 경제 개발 계획을 추진한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"수출을 통해 농업 중심의 산업구조를 공업 중심으로 바꾸려고","correct":true},{"t":"공업 중심의 산업구조를 농업 중심으로 되돌리려고","mis":"SO6-1-u1-X26"},{"t":"다른 나라와의 무역을 끊으려고","mis":"SO6-1-u1-X27"},{"t":"생활 수준을 낮추려고","mis":"SO6-1-u1-X27"}],"explanation":["농업 중심이었어요.","공업 중심으로 바꾸려 했어요.","수출로 산업화하려 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L08_challenge#6','soc',6,1,'u1','L08','g6_1_soc_u1_L08_challenge','lesson_challenge','SO6-1-u1-C14',3,'error','auto','산업의 발달을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u1-X25','SO6-1-u1-X26']::text[],false,'{"seq":6,"concept":"SO6-1-u1-C14","difficulty":3,"kind":"error","stem":"산업의 발달을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「가발과 의류는 무거운 물건이라 중화학 공업이야.」","correct":true,"mis_target":"SO6-1-u1-X25"},{"t":"친구 가 — 「철강과 조선은 중화학 공업이야.」","mis":"SO6-1-u1-X25"},{"t":"친구 다 — 「1980년대에는 전자 제품 산업이 발달했어.」","mis":"SO6-1-u1-X26"}],"explanation":["가발과 의류는 가벼워요.","그래서 경공업이에요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L08_challenge#7','soc',6,1,'u1','L08','g6_1_soc_u1_L08_challenge','lesson_challenge','SO6-1-u1-C15',3,'ox','auto','우리나라의 산업화는 정부의 계획만으로 이루어졌고, 근로자나 기업의 노력은 관계가 없어요.',ARRAY['SO6-1-u1-X27']::text[],false,'{"seq":7,"concept":"SO6-1-u1-C15","difficulty":3,"kind":"ox","stem":"우리나라의 산업화는 정부의 계획만으로 이루어졌고, 근로자나 기업의 노력은 관계가 없어요.","answer":"X","reason_options":[{"t":"정부의 계획과 함께 근로자들의 노동, 외국에서 일한 사람들의 외화, 기업의 기술 개발이 함께 모였기 때문에","correct":true},{"t":"정부가 모든 물건을 직접 만들었기 때문에","mis":"SO6-1-u1-X27"}],"mis":"SO6-1-u1-X27","explanation":["정부가 계획했어요.","근로자와 기업도 노력했어요.","여러 사람의 노력이 모였어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L08_challenge#8','soc',6,1,'u1','L08','g6_1_soc_u1_L08_challenge','lesson_challenge','SO6-1-u1-C14',4,'mc','auto','1980년대에 국민 소득이 급격히 늘어난 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X26']::text[],false,'{"seq":8,"concept":"SO6-1-u1-C14","difficulty":4,"kind":"mc","stem":"1980년대에 국민 소득이 급격히 늘어난 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"중화학 공업이 더욱 발달하고 수출 규모가 커졌기 때문에","correct":true},{"t":"농업 중심으로 되돌아갔기 때문에","mis":"SO6-1-u1-X26"},{"t":"수출을 모두 멈추었기 때문에","mis":"SO6-1-u1-X26"},{"t":"공장을 모두 닫았기 때문에","mis":"SO6-1-u1-X26"}],"explanation":["중화학 공업이 더 발달했어요.","수출이 커졌어요.","소득이 늘었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L08_challenge#9','soc',6,1,'u1','L08','g6_1_soc_u1_L08_challenge','lesson_challenge','SO6-1-u1-C15',4,'mc','auto','독일로 간 광부와 간호사가 힘든 일을 견딜 때 한 생각으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X27']::text[],false,'{"seq":9,"concept":"SO6-1-u1-C15","difficulty":4,"kind":"mc","stem":"독일로 간 광부와 간호사가 힘든 일을 견딜 때 한 생각으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"가족의 생활과 나라의 경제 발전에 보탬이 된다는 생각","correct":true},{"t":"일은 힘들지만 아무 도움도 되지 않는다는 생각","mis":"SO6-1-u1-X27"},{"t":"독일에서 영원히 놀며 지내겠다는 생각","mis":"SO6-1-u1-X27"},{"t":"나라와 가족은 상관없다는 생각","mis":"SO6-1-u1-X27"}],"explanation":["가족을 생각했어요.","나라의 발전도 생각했어요.","그래서 견뎌 냈어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L08_challenge#10','soc',6,1,'u1','L08','g6_1_soc_u1_L08_challenge','lesson_challenge','SO6-1-u1-C14',4,'essay','teacher','1950년대부터 1980년대까지 우리나라 산업이 어떻게 발달했는지 시대별로 쓰고, 그 과정에서 사람들이 한 노력을 한 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-1-u1-C14","difficulty":4,"kind":"essay","stem":"1950년대부터 1980년대까지 우리나라 산업이 어떻게 발달했는지 시대별로 쓰고, 그 과정에서 사람들이 한 노력을 한 가지 쓰세요.","answer_guide":{"answer":"예: 1950년대에는 지원받은 물자로 밀가루·설탕·면직물 같은 생활용품 산업이, 1960년대에는 풍부한 노동력으로 신발·가발·의류 같은 경공업이, 1970년대에는 철강·조선·석유 화학 같은 중화학 공업이, 1980년대에는 자동차·전자 제품 산업이 발달했다. 그 과정에서 독일로 간 광부와 간호사가 힘든 일을 견디며 벌어들인 외화가 산업화의 밑거름이 되었다.","scoring_points":["네 시대의 산업을 차례대로 썼는가","경공업에서 중화학 공업으로 바뀐 흐름이 드러났는가","사람들의 노력을 한 가지 썼는가"]},"explanation":["생활용품 → 경공업이에요.","→ 중화학 공업 → 자동차·전자예요.","사람들의 노력도 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L09_basic#1','soc',6,1,'u1','L09','g6_1_soc_u1_L09_basic','lesson_basic','SO6-1-u1-C16',1,'mc','auto','산업화 과정에서 많은 사람이 일자리를 찾아 몰려든 곳은 어디인가요?',ARRAY['SO6-1-u1-X28']::text[],false,'{"seq":1,"concept":"SO6-1-u1-C16","difficulty":1,"kind":"mc","stem":"산업화 과정에서 많은 사람이 일자리를 찾아 몰려든 곳은 어디인가요?","options":[{"t":"도시","correct":true},{"t":"농촌","mis":"SO6-1-u1-X28"},{"t":"산골","mis":"SO6-1-u1-X28"},{"t":"외딴섬","mis":"SO6-1-u1-X28"}],"explanation":["일자리가 많은 곳이에요.","공장과 회사가 있어요.","도시예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L09_basic#2','soc',6,1,'u1','L09','g6_1_soc_u1_L09_basic','lesson_basic','SO6-1-u1-C16',1,'mc','auto','하루 동안 볼일을 끝내고 되돌아올 수 있는 거리의 범위를 무엇이라고 하나요?',ARRAY['SO6-1-u1-X28']::text[],false,'{"seq":2,"concept":"SO6-1-u1-C16","difficulty":1,"kind":"mc","stem":"하루 동안 볼일을 끝내고 되돌아올 수 있는 거리의 범위를 무엇이라고 하나요?","options":[{"t":"일일생활권","correct":true},{"t":"대중 매체","mis":"SO6-1-u1-X28"},{"t":"달동네","mis":"SO6-1-u1-X28"},{"t":"공업 단지","mis":"SO6-1-u1-X28"}],"explanation":["하루 안에 다녀와요.","교통이 발달해 넓어졌어요.","일일생활권이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L09_basic#3','soc',6,1,'u1','L09','g6_1_soc_u1_L09_basic','lesson_basic','SO6-1-u1-C16',1,'sa','auto','라디오·텔레비전처럼 많은 사람에게 정보를 전달하는 수단을 무엇이라고 하나요? 다섯 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO6-1-u1-C16","difficulty":1,"kind":"sa","stem":"라디오·텔레비전처럼 많은 사람에게 정보를 전달하는 수단을 무엇이라고 하나요? 다섯 글자로 쓰세요.","answer":["대중 매체","대중매체"],"explanation":["많은 사람에게 전해요.","대중◯◯예요.","대중 매체예요."],"mis":"SO6-1-u1-X28"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L09_basic#4','soc',6,1,'u1','L09','g6_1_soc_u1_L09_basic','lesson_basic','SO6-1-u1-C17',1,'ox','auto','산업화로 도시와 농촌의 소득 차이가 줄어들고 농촌 인구가 크게 늘었어요.',ARRAY['SO6-1-u1-X28']::text[],false,'{"seq":4,"concept":"SO6-1-u1-C17","difficulty":1,"kind":"ox","stem":"산업화로 도시와 농촌의 소득 차이가 줄어들고 농촌 인구가 크게 늘었어요.","answer":"X","reason_options":[{"t":"사람들이 도시로 몰리며 도시와 농촌의 소득 격차가 벌어지고 농촌 인구는 줄었기 때문에","correct":true},{"t":"산업화로 사람들이 모두 농촌으로 돌아갔기 때문에","mis":"SO6-1-u1-X28"}],"mis":"SO6-1-u1-X28","explanation":["사람들이 도시로 갔어요.","소득 차이가 벌어졌어요.","농촌 인구는 줄었어요."],"asset":{"type":"passage","lines":["ⓐ 일자리와 집이 모자라 변두리나 높은 지대에 모여 살기도 했다.","ⓑ 도시와 농촌의 소득 차이가 벌어지고 농촌 사람이 줄었다.","ⓒ 근로자들이 열악한 환경에서 오래 일하고 임금은 낮았다."],"title":"산업화의 그늘 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L09_basic#5','soc',6,1,'u1','L09','g6_1_soc_u1_L09_basic','lesson_basic','SO6-1-u1-C16',2,'match','auto','산업화로 달라진 생활 카드와 그 변화를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO6-1-u1-C16","difficulty":2,"kind":"match","stem":"산업화로 달라진 생활 카드와 그 변화를 알맞게 이으세요.","pairs":[{"l":"㉠","r":"도시화"},{"l":"㉡","r":"교통의 발달"},{"l":"㉢","r":"소득 수준 향상"},{"l":"㉣","r":"대중문화 성장"}],"mis":"SO6-1-u1-X28","explanation":["㉠은 도시로 몰렸어요.","㉡은 지하철과 고속 국도예요.","㉢은 가전제품, ㉣은 가요·영화예요."],"asset":{"type":"passage","lines":["㉠ 일자리를 찾아 도시로 사람이 몰리자 아파트 단지를 많이 지었다.","㉡ 지하철을 개통하고 고속 국도를 넓혀 전국을 하루 생활권으로 만들었다.","㉢ 텔레비전·냉장고·세탁기가 집집마다 보급되었다.","㉣ 가요·영화·드라마·스포츠를 즐기는 사람이 크게 늘었다."],"title":"산업화로 달라진 생활 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L09_basic#6','soc',6,1,'u1','L09','g6_1_soc_u1_L09_basic','lesson_basic','SO6-1-u1-C16',2,'mc','auto','도시 인구가 빠르게 늘자 정부가 좁은 땅에 여러 사람이 살 수 있도록 많이 지은 것은 무엇인가요?',ARRAY['SO6-1-u1-X28']::text[],false,'{"seq":6,"concept":"SO6-1-u1-C16","difficulty":2,"kind":"mc","stem":"도시 인구가 빠르게 늘자 정부가 좁은 땅에 여러 사람이 살 수 있도록 많이 지은 것은 무엇인가요?","options":[{"t":"아파트 단지","correct":true},{"t":"넓은 마당이 있는 한옥","mis":"SO6-1-u1-X28"},{"t":"큰 농장","mis":"SO6-1-u1-X28"},{"t":"공원","mis":"SO6-1-u1-X28"}],"explanation":["좁은 땅에 많이 살아요.","높이 쌓아 지어요.","아파트 단지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L09_basic#7','soc',6,1,'u1','L09','g6_1_soc_u1_L09_basic','lesson_basic','SO6-1-u1-C16',2,'mc','auto','두 도시 사이를 오가는 데 걸린 시간 자료를 보고 알 수 있는 생활의 변화로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X28']::text[],false,'{"seq":7,"concept":"SO6-1-u1-C16","difficulty":2,"kind":"mc","stem":"두 도시 사이를 오가는 데 걸린 시간 자료를 보고 알 수 있는 생활의 변화로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"지역 사이의 이동이 활발해졌다","correct":true},{"t":"이동하는 데 시간이 더 걸리게 되었다","mis":"SO6-1-u1-X28"},{"t":"사람들이 먼 곳에 가지 않게 되었다","mis":"SO6-1-u1-X28"},{"t":"기차를 탈 수 없게 되었다","mis":"SO6-1-u1-X28"}],"explanation":["걸리는 시간이 크게 줄었어요.","쉽게 오갈 수 있어요.","이동이 활발해졌어요."],"asset":{"type":"passage","lines":["고속 국도가 생기기 전 — 기차로 12시간, 옛 도로로 15시간","고속 국도가 생긴 뒤 — 4시간 30분대","물음 — 이 변화가 사람들의 생활에 어떤 영향을 주었을까?"],"title":"두 도시 사이를 오가는 데 걸린 시간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L09_basic#8','soc',6,1,'u1','L09','g6_1_soc_u1_L09_basic','lesson_basic','SO6-1-u1-C17',2,'mc','auto','산업화로 나타난 문제점으로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X29','SO6-1-u1-X30']::text[],false,'{"seq":8,"concept":"SO6-1-u1-C17","difficulty":2,"kind":"mc","stem":"산업화로 나타난 문제점으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"가전제품이 가정에 널리 보급되었다","correct":true},{"t":"도시에 일자리와 주택이 부족해졌다","mis":"SO6-1-u1-X29"},{"t":"도시와 농촌의 소득 격차가 커졌다","mis":"SO6-1-u1-X29"},{"t":"근로자들이 오랜 시간 낮은 임금으로 일했다","mis":"SO6-1-u1-X30"}],"explanation":["가전제품 보급은 달라진 생활이에요.","나머지는 산업화의 그늘이에요.","문제점이 아닌 것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L09_basic#9','soc',6,1,'u1','L09','g6_1_soc_u1_L09_basic','lesson_basic','SO6-1-u1-C17',2,'blank','auto','산업화 시기 근로자들은 열악한 근무 환경에서 (    ) 노동과 낮은 임금에 시달렸어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-1-u1-X30']::text[],false,'{"seq":9,"concept":"SO6-1-u1-C17","difficulty":2,"kind":"blank","stem":"산업화 시기 근로자들은 열악한 근무 환경에서 (    ) 노동과 낮은 임금에 시달렸어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"장시간","correct":true},{"t":"짧은 시간","mis":"SO6-1-u1-X30"},{"t":"자유로운","mis":"SO6-1-u1-X30"},{"t":"즐거운","mis":"SO6-1-u1-X30"}],"explanation":["오래 일했어요.","편지에도 나와요.","장시간이에요."],"asset":{"type":"passage","lines":["저희는 근로 기준법의 보호를 거의 받지 못하고 있습니다.","많은 근로자가 하루 15시간씩 일합니다.","근무 시간을 줄이고 일요일마다 쉴 수 있기를 바랍니다."],"title":"한 근로자가 대통령에게 보낸 편지(내 말로 줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L09_basic#10','soc',6,1,'u1','L09','g6_1_soc_u1_L09_basic','lesson_basic','SO6-1-u1-C17',3,'mc','auto','산업화가 생활에 준 영향을 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['SO6-1-u1-X29','SO6-1-u1-X28']::text[],false,'{"seq":10,"concept":"SO6-1-u1-C17","difficulty":3,"kind":"mc","stem":"산업화가 생활에 준 영향을 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"생활이 편리해지고 소득이 늘었지만, 주택 부족·소득 격차·근로자의 어려움 같은 그늘도 함께 나타났다","correct":true},{"t":"좋은 점만 있고 어려운 점은 하나도 없었다","mis":"SO6-1-u1-X29"},{"t":"어려운 점만 있고 좋아진 점은 하나도 없었다","mis":"SO6-1-u1-X29"},{"t":"생활 모습은 아무것도 달라지지 않았다","mis":"SO6-1-u1-X28"}],"explanation":["편리해진 점이 있어요.","그늘도 있어요.","두 면을 함께 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L09_challenge#1','soc',6,1,'u1','L09','g6_1_soc_u1_L09_challenge','lesson_challenge','SO6-1-u1-C17',2,'sa','auto','산비탈 같은 높은 곳에 형편이 어려운 사람들이 모여 살던 동네로, 달이 잘 보인다는 뜻에서 붙은 이름은 무엇인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-1-u1-C17","difficulty":2,"kind":"sa","stem":"산비탈 같은 높은 곳에 형편이 어려운 사람들이 모여 살던 동네로, 달이 잘 보인다는 뜻에서 붙은 이름은 무엇인가요? 세 글자로 쓰세요.","answer":["달동네"],"explanation":["높은 곳에 있었어요.","달이 잘 보였어요.","달동네예요."],"mis":"SO6-1-u1-X29"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L09_challenge#2','soc',6,1,'u1','L09','g6_1_soc_u1_L09_challenge','lesson_challenge','SO6-1-u1-C16',2,'ox','auto','라디오와 텔레비전이 널리 보급되면서 가요·영화·드라마·스포츠 같은 대중문화가 성장했어요.',ARRAY['SO6-1-u1-X28']::text[],false,'{"seq":2,"concept":"SO6-1-u1-C16","difficulty":2,"kind":"ox","stem":"라디오와 텔레비전이 널리 보급되면서 가요·영화·드라마·스포츠 같은 대중문화가 성장했어요.","answer":"O","reason_options":[{"t":"대중 매체로 많은 사람이 같은 문화를 함께 즐길 수 있게 되었기 때문에","correct":true},{"t":"산업화 뒤 사람들이 문화생활을 모두 그만두었기 때문에","mis":"SO6-1-u1-X28"}],"mis":"SO6-1-u1-X28","explanation":["대중 매체가 보급됐어요.","많은 사람이 함께 즐겨요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L09_challenge#3','soc',6,1,'u1','L09','g6_1_soc_u1_L09_challenge','lesson_challenge','SO6-1-u1-C17',3,'mc','auto','산업화 시기 정부가 근로자의 임금을 낮게 유지한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X30']::text[],false,'{"seq":3,"concept":"SO6-1-u1-C17","difficulty":3,"kind":"mc","stem":"산업화 시기 정부가 근로자의 임금을 낮게 유지한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"수출품의 가격을 낮춰 경쟁력을 유지하려고","correct":true},{"t":"근로자들이 적게 받기를 원했기 때문에","mis":"SO6-1-u1-X30"},{"t":"물건을 하나도 팔지 않으려고","mis":"SO6-1-u1-X30"},{"t":"근로자를 더 많이 쉬게 하려고","mis":"SO6-1-u1-X30"}],"explanation":["수출 중심이었어요.","값이 싸야 잘 팔려요.","그래서 임금을 낮게 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L09_challenge#4','soc',6,1,'u1','L09','g6_1_soc_u1_L09_challenge','lesson_challenge','SO6-1-u1-C17',3,'mc','auto','한 근로자가 대통령에게 보낸 편지에서 바란 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X30']::text[],false,'{"seq":4,"concept":"SO6-1-u1-C17","difficulty":3,"kind":"mc","stem":"한 근로자가 대통령에게 보낸 편지에서 바란 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"근무 시간을 줄이고 정해진 날에 쉴 수 있는 것","correct":true},{"t":"더 오래 일하는 것","mis":"SO6-1-u1-X30"},{"t":"휴일을 모두 없애는 것","mis":"SO6-1-u1-X30"},{"t":"공장을 모두 닫는 것","mis":"SO6-1-u1-X30"}],"explanation":["하루 15시간씩 일했어요.","시간을 줄이고 싶었어요.","쉬는 날을 바랐어요."],"asset":{"type":"passage","lines":["저희는 근로 기준법의 보호를 거의 받지 못하고 있습니다.","많은 근로자가 하루 15시간씩 일합니다.","근무 시간을 줄이고 일요일마다 쉴 수 있기를 바랍니다."],"title":"한 근로자가 대통령에게 보낸 편지(내 말로 줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L09_challenge#5','soc',6,1,'u1','L09','g6_1_soc_u1_L09_challenge','lesson_challenge','SO6-1-u1-C16',3,'mc','auto','두 도시를 오가는 시간 자료처럼 고속 국도가 생긴 뒤 늘어났을 것으로 짐작할 수 있는 것은 어느 것인가요?',ARRAY['SO6-1-u1-X28']::text[],false,'{"seq":5,"concept":"SO6-1-u1-C16","difficulty":3,"kind":"mc","stem":"두 도시를 오가는 시간 자료처럼 고속 국도가 생긴 뒤 늘어났을 것으로 짐작할 수 있는 것은 어느 것인가요?","options":[{"t":"자동차를 사려는 사람","correct":true},{"t":"먼 길을 걸어 다니는 사람","mis":"SO6-1-u1-X28"},{"t":"하루에 다녀올 수 없는 곳","mis":"SO6-1-u1-X28"},{"t":"도로를 막는 일","mis":"SO6-1-u1-X28"}],"explanation":["길이 빨라졌어요.","차로 다니기 좋아요.","자동차를 사려는 사람이 늘었어요."],"asset":{"type":"passage","lines":["고속 국도가 생기기 전 — 기차로 12시간, 옛 도로로 15시간","고속 국도가 생긴 뒤 — 4시간 30분대","물음 — 이 변화가 사람들의 생활에 어떤 영향을 주었을까?"],"title":"두 도시 사이를 오가는 데 걸린 시간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L09_challenge#6','soc',6,1,'u1','L09','g6_1_soc_u1_L09_challenge','lesson_challenge','SO6-1-u1-C17',3,'error','auto','산업화의 그늘을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u1-X30','SO6-1-u1-X29']::text[],false,'{"seq":6,"concept":"SO6-1-u1-C17","difficulty":3,"kind":"error","stem":"산업화의 그늘을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「일하던 사람들은 아무 노력 없이 그냥 참기만 했어.」","correct":true,"mis_target":"SO6-1-u1-X30"},{"t":"친구 가 — 「도시로 사람이 몰려 집이 부족했어.」","mis":"SO6-1-u1-X29"},{"t":"친구 나 — 「도시와 농촌의 소득 차이가 벌어졌어.」","mis":"SO6-1-u1-X29"}],"explanation":["많은 사람이 권리를 지키려 했어요.","편지를 쓰고 개선을 요구했어요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L09_challenge#7','soc',6,1,'u1','L09','g6_1_soc_u1_L09_challenge','lesson_challenge','SO6-1-u1-C17',3,'mc','auto','산업화의 그늘 카드 ⓐ에서 사람들이 변두리나 높은 지대에 모여 살게 된 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X29','SO6-1-u1-X28']::text[],false,'{"seq":7,"concept":"SO6-1-u1-C17","difficulty":3,"kind":"mc","stem":"산업화의 그늘 카드 ⓐ에서 사람들이 변두리나 높은 지대에 모여 살게 된 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"도시로 사람이 몰려 안정된 일자리와 집이 모자랐기 때문에","correct":true},{"t":"높은 곳의 경치를 좋아했기 때문에","mis":"SO6-1-u1-X29"},{"t":"도시에 집이 너무 많이 남았기 때문에","mis":"SO6-1-u1-X28"},{"t":"농촌이 도시보다 소득이 높았기 때문에","mis":"SO6-1-u1-X28"}],"explanation":["사람이 몰렸어요.","일자리와 집이 모자랐어요.","그래서 변두리에 모였어요."],"asset":{"type":"passage","lines":["ⓐ 일자리와 집이 모자라 변두리나 높은 지대에 모여 살기도 했다.","ⓑ 도시와 농촌의 소득 차이가 벌어지고 농촌 사람이 줄었다.","ⓒ 근로자들이 열악한 환경에서 오래 일하고 임금은 낮았다."],"title":"산업화의 그늘 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L09_challenge#8','soc',6,1,'u1','L09','g6_1_soc_u1_L09_challenge','lesson_challenge','SO6-1-u1-C16',4,'mc','auto','산업화로 달라진 우리나라의 모습을 가장 균형 있게 정리한 것은 어느 것인가요?',ARRAY['SO6-1-u1-X29','SO6-1-u1-X28']::text[],false,'{"seq":8,"concept":"SO6-1-u1-C16","difficulty":4,"kind":"mc","stem":"산업화로 달라진 우리나라의 모습을 가장 균형 있게 정리한 것은 어느 것인가요?","options":[{"t":"짧은 기간에 놀라운 경제성장으로 생활이 편리해졌지만, 그늘을 고치려는 노력도 함께 필요했다","correct":true},{"t":"경제성장으로 모든 문제가 저절로 사라졌다","mis":"SO6-1-u1-X29"},{"t":"산업화는 어려움만 남긴 실패였다","mis":"SO6-1-u1-X29"},{"t":"경제성장은 사람들의 생활과 관계없었다","mis":"SO6-1-u1-X28"}],"explanation":["밝은 면이 있어요.","그늘도 있어요.","함께 보고 고쳐 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L09_challenge#9','soc',6,1,'u1','L09','g6_1_soc_u1_L09_challenge','lesson_challenge','SO6-1-u1-C17',4,'mc','auto','오늘날 근로자의 권리를 생각할 때 한 근로자의 편지에서 배울 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X30']::text[],false,'{"seq":9,"concept":"SO6-1-u1-C17","difficulty":4,"kind":"mc","stem":"오늘날 근로자의 권리를 생각할 때 한 근로자의 편지에서 배울 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"일하는 사람의 권리는 스스로 말하고 함께 지켜 가야 한다","correct":true},{"t":"일하는 사람은 어떤 환경이든 참아야 한다","mis":"SO6-1-u1-X30"},{"t":"근로자의 권리는 경제성장과 관계없다","mis":"SO6-1-u1-X30"},{"t":"오래 일할수록 언제나 좋다","mis":"SO6-1-u1-X30"}],"explanation":["편지로 바라는 것을 말했어요.","많은 사람이 함께 나섰어요.","권리를 지켜 가요."],"asset":{"type":"passage","lines":["저희는 근로 기준법의 보호를 거의 받지 못하고 있습니다.","많은 근로자가 하루 15시간씩 일합니다.","근무 시간을 줄이고 일요일마다 쉴 수 있기를 바랍니다."],"title":"한 근로자가 대통령에게 보낸 편지(내 말로 줄임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L09_challenge#10','soc',6,1,'u1','L09','g6_1_soc_u1_L09_challenge','lesson_challenge','SO6-1-u1-C16',4,'essay','teacher','산업화로 달라진 생활 모습 두 가지와 산업화로 나타난 문제점 두 가지를 쓰고, 문제점을 해결하려는 노력을 한 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-1-u1-C16","difficulty":4,"kind":"essay","stem":"산업화로 달라진 생활 모습 두 가지와 산업화로 나타난 문제점 두 가지를 쓰고, 문제점을 해결하려는 노력을 한 가지 쓰세요.","answer_guide":{"answer":"예: 산업화로 일자리를 찾아 도시로 사람이 몰려 아파트 단지가 많이 생겼고, 지하철과 고속 국도로 전국이 일일생활권이 되었다. 그러나 도시에 일자리와 주택이 부족해졌고, 근로자들은 오랜 시간 낮은 임금으로 일했다. 그래서 많은 사람이 근무 환경을 개선하고 임금을 올리는 등 근로자의 권리를 보호하려고 노력했다.","scoring_points":["달라진 생활 모습 두 가지를 썼는가","문제점 두 가지를 썼는가","해결하려는 노력을 썼는가"]},"explanation":["도시화와 교통을 떠올려요.","그늘도 함께 써요.","권리를 지키려는 노력이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L10_basic#1','soc',6,1,'u1','L10','g6_1_soc_u1_L10_basic','lesson_basic','SO6-1-u1-C18',1,'mc','auto','숨은 글씨 그림은 어떤 활동인가요?',ARRAY['SO6-1-u1-X32']::text[],false,'{"seq":1,"concept":"SO6-1-u1-C18","difficulty":1,"kind":"mc","stem":"숨은 글씨 그림은 어떤 활동인가요?","options":[{"t":"사건에 어울리는 글씨를 떠올려 장면 속에 숨겨 그리는 활동","correct":true},{"t":"글씨는 쓰지 않고 그림만 크게 그리는 활동","mis":"SO6-1-u1-X32"},{"t":"사건과 상관없는 글씨를 크게 쓰는 활동","mis":"SO6-1-u1-X32"},{"t":"사진을 오려 붙이는 활동","mis":"SO6-1-u1-X32"}],"explanation":["글씨와 그림이 함께예요.","장면 속에 글씨를 숨겨요.","그것이 숨은 글씨 그림이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L10_basic#2','soc',6,1,'u1','L10','g6_1_soc_u1_L10_basic','lesson_basic','SO6-1-u1-C18',1,'mc','auto','숨은 글씨 그림을 그릴 때 가장 먼저 하는 일은 무엇인가요?',ARRAY['SO6-1-u1-X32']::text[],false,'{"seq":2,"concept":"SO6-1-u1-C18","difficulty":1,"kind":"mc","stem":"숨은 글씨 그림을 그릴 때 가장 먼저 하는 일은 무엇인가요?","options":[{"t":"단원에서 공부한 역사적 사건 하나와 관련 있는 낱말을 쓴다","correct":true},{"t":"숨긴 글씨를 진하게 칠한다","mis":"SO6-1-u1-X32"},{"t":"나머지 부분을 색칠한다","mis":"SO6-1-u1-X32"},{"t":"친구 그림에서 숨은 글씨를 찾는다","mis":"SO6-1-u1-X32"}],"explanation":["무엇을 그릴지 먼저 정해요.","사건과 낱말을 떠올려요.","그것이 첫걸음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L10_basic#3','soc',6,1,'u1','L10','g6_1_soc_u1_L10_basic','lesson_basic','SO6-1-u1-C18',1,'sa','auto','숨은 글씨 그림에서 숨긴 글씨는 진하게, 나머지 부분은 어떻게 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO6-1-u1-C18","difficulty":1,"kind":"sa","stem":"숨은 글씨 그림에서 숨긴 글씨는 진하게, 나머지 부분은 어떻게 하나요? 세 글자로 쓰세요.","answer":["색칠해","색칠함","색칠"],"explanation":["글씨는 진하게 해요.","나머지는 색을 칠해요.","색칠해요."],"mis":"SO6-1-u1-X32"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L10_basic#4','soc',6,1,'u1','L10','g6_1_soc_u1_L10_basic','lesson_basic','SO6-1-u1-C18',1,'ox','auto','그림을 완성한 뒤에는 친구 그림에서 숨은 글씨를 찾고 느낀 점을 나눠요.',ARRAY['SO6-1-u1-X32']::text[],false,'{"seq":4,"concept":"SO6-1-u1-C18","difficulty":1,"kind":"ox","stem":"그림을 완성한 뒤에는 친구 그림에서 숨은 글씨를 찾고 느낀 점을 나눠요.","answer":"O","reason_options":[{"t":"친구 작품을 살펴보며 역사적 사건을 다시 생각해 볼 수 있기 때문에","correct":true},{"t":"그림은 혼자만 보고 아무에게도 보여 주지 않기 때문에","mis":"SO6-1-u1-X32"}],"mis":"SO6-1-u1-X32","explanation":["친구 그림을 봐요.","숨은 글씨를 찾아요.","느낀 점을 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L10_basic#5','soc',6,1,'u1','L10','g6_1_soc_u1_L10_basic','lesson_basic','SO6-1-u1-C18',2,'mc','auto','숨은 글씨 그림 계획표에서 「선거」라는 글씨를 고른 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X32','SO6-1-u1-X23']::text[],false,'{"seq":5,"concept":"SO6-1-u1-C18","difficulty":2,"kind":"mc","stem":"숨은 글씨 그림 계획표에서 「선거」라는 글씨를 고른 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"6월 민주 항쟁의 결과 대통령 직선제가 시행되었기 때문에","correct":true},{"t":"사건과 상관없이 쓰기 쉬운 낱말이라서","mis":"SO6-1-u1-X32"},{"t":"6월 민주 항쟁으로 선거가 없어졌기 때문에","mis":"SO6-1-u1-X23"},{"t":"글씨를 흐리게 숨기기 좋아서","mis":"SO6-1-u1-X32"}],"explanation":["사건과 낱말이 이어져야 해요.","6월 민주 항쟁의 결과를 떠올려요.","직선제가 시행됐어요."],"asset":{"type":"passage","lines":["① 사건 — 6월 민주 항쟁 / 떠오르는 낱말 — 시위, 선거, 구호","② 그릴 낱말 — 「선거」","③ 장면 — 투표하려고 줄을 선 사람들의 몸과 팔로 글씨 획을 이룬다.","④ 「선거」 두 글자는 진하게, 나머지는 색칠한다.","⑤ 친구 그림에서 숨은 글씨를 찾고 느낀 점을 적는다."],"title":"숨은 글씨 그림 계획표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L10_basic#6','soc',6,1,'u1','L10','g6_1_soc_u1_L10_basic','lesson_basic','SO6-1-u1-C18',2,'mc','auto','숨은 글씨 그림 계획표 ③처럼 장면 속에 글씨를 숨기는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X32']::text[],false,'{"seq":6,"concept":"SO6-1-u1-C18","difficulty":2,"kind":"mc","stem":"숨은 글씨 그림 계획표 ③처럼 장면 속에 글씨를 숨기는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"장면을 이루는 몸·팔 같은 획이 그대로 글씨의 획이 되게 그린다","correct":true},{"t":"글씨를 그림 바깥 귀퉁이에 따로 적는다","mis":"SO6-1-u1-X32"},{"t":"글씨를 아주 작게 써서 보이지 않게 한다","mis":"SO6-1-u1-X32"},{"t":"글씨 위에 색을 덧칠해 지운다","mis":"SO6-1-u1-X32"}],"explanation":["장면의 획을 써요.","그 획이 글씨가 돼요.","그림이면서 글씨예요."],"asset":{"type":"passage","lines":["① 사건 — 6월 민주 항쟁 / 떠오르는 낱말 — 시위, 선거, 구호","② 그릴 낱말 — 「선거」","③ 장면 — 투표하려고 줄을 선 사람들의 몸과 팔로 글씨 획을 이룬다.","④ 「선거」 두 글자는 진하게, 나머지는 색칠한다.","⑤ 친구 그림에서 숨은 글씨를 찾고 느낀 점을 적는다."],"title":"숨은 글씨 그림 계획표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L10_basic#7','soc',6,1,'u1','L10','g6_1_soc_u1_L10_basic','lesson_basic','SO6-1-u1-C18',2,'mc','auto','4·19 혁명을 떠올려 「혁명」이라는 글씨를 숨길 때 그리기에 알맞은 장면은 어느 것인가요?',ARRAY['SO6-1-u1-X32','SO6-1-u1-X24']::text[],false,'{"seq":7,"concept":"SO6-1-u1-C18","difficulty":2,"kind":"mc","stem":"4·19 혁명을 떠올려 「혁명」이라는 글씨를 숨길 때 그리기에 알맞은 장면은 어느 것인가요?","options":[{"t":"학생들이 거리로 나와 민주주의를 외치는 모습","correct":true},{"t":"공장에서 기계로 배를 만드는 모습","mis":"SO6-1-u1-X32"},{"t":"남북 선수들이 함께 입장하는 모습","mis":"SO6-1-u1-X24"},{"t":"아무 장면이나 마음대로","mis":"SO6-1-u1-X32"}],"explanation":["사건에서 떠오르는 장면이에요.","학생들이 거리로 나왔어요.","민주주의를 외쳤어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L10_basic#8','soc',6,1,'u1','L10','g6_1_soc_u1_L10_basic','lesson_basic','SO6-1-u1-C18',2,'blank','auto','숨은 글씨 그림 계획표 ④처럼 숨긴 글씨는 (    ) 나타내야 친구들이 찾을 수 있어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-1-u1-X32']::text[],false,'{"seq":8,"concept":"SO6-1-u1-C18","difficulty":2,"kind":"blank","stem":"숨은 글씨 그림 계획표 ④처럼 숨긴 글씨는 (    ) 나타내야 친구들이 찾을 수 있어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"진하게","correct":true},{"t":"흐리게","mis":"SO6-1-u1-X32"},{"t":"지워서","mis":"SO6-1-u1-X32"},{"t":"작게만","mis":"SO6-1-u1-X32"}],"explanation":["찾을 수 있어야 해요.","나머지보다 도드라져요.","진하게예요."],"asset":{"type":"passage","lines":["① 사건 — 6월 민주 항쟁 / 떠오르는 낱말 — 시위, 선거, 구호","② 그릴 낱말 — 「선거」","③ 장면 — 투표하려고 줄을 선 사람들의 몸과 팔로 글씨 획을 이룬다.","④ 「선거」 두 글자는 진하게, 나머지는 색칠한다.","⑤ 친구 그림에서 숨은 글씨를 찾고 느낀 점을 적는다."],"title":"숨은 글씨 그림 계획표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L10_basic#9','soc',6,1,'u1','L10','g6_1_soc_u1_L10_basic','lesson_basic','SO6-1-u1-C18',2,'mc','auto','숨은 글씨 그림 활동을 하는 태도로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X32']::text[],false,'{"seq":9,"concept":"SO6-1-u1-C18","difficulty":2,"kind":"mc","stem":"숨은 글씨 그림 활동을 하는 태도로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"친구의 작품을 깎아내리고 내 작품만 자랑한다","correct":true},{"t":"공부한 사건 가운데 인상 깊은 장면을 떠올린다","mis":"SO6-1-u1-X32"},{"t":"친구 작품에서 숨은 글씨를 찾아본다","mis":"SO6-1-u1-X32"},{"t":"친구 작품에서 인상 깊은 점을 말해 준다","mis":"SO6-1-u1-X32"}],"explanation":["친구 작품을 존중해요.","좋은 점을 찾아 말해요.","깎아내리면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L10_basic#10','soc',6,1,'u1','L10','g6_1_soc_u1_L10_basic','lesson_basic','SO6-1-u1-C18',3,'mc','auto','숨은 글씨 그림에서 같은 획이 그림이면서 글씨로도 읽히는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X32']::text[],false,'{"seq":10,"concept":"SO6-1-u1-C18","difficulty":3,"kind":"mc","stem":"숨은 글씨 그림에서 같은 획이 그림이면서 글씨로도 읽히는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"장면을 이루는 획 몇 개가 그대로 글씨의 획이 되도록 그렸기 때문에","correct":true},{"t":"글씨를 그림 옆에 따로 써 두었기 때문에","mis":"SO6-1-u1-X32"},{"t":"글씨 획이 아직 놓이지 않았기 때문에","mis":"SO6-1-u1-X32"},{"t":"그림과 글씨를 서로 다른 종이에 그렸기 때문에","mis":"SO6-1-u1-X32"}],"explanation":["획 하나가 두 가지로 읽혀요.","장면의 획이 글씨가 돼요.","그래서 숨은 글씨예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L10_challenge#1','soc',6,1,'u1','L10','g6_1_soc_u1_L10_challenge','lesson_challenge','SO6-1-u1-C18',2,'sa','auto','6월 민주 항쟁에서 시위하던 시민들의 모습이 생각나 숨긴 글씨로 고를 수 있는 두 글자 낱말을 한 가지 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-1-u1-C18","difficulty":2,"kind":"sa","stem":"6월 민주 항쟁에서 시위하던 시민들의 모습이 생각나 숨긴 글씨로 고를 수 있는 두 글자 낱말을 한 가지 쓰세요.","answer":["시위","구호","선거","직선제"],"explanation":["시민들이 무엇을 했나요?","거리에서 외쳤어요.","시위·구호 같은 낱말이에요."],"mis":"SO6-1-u1-X32"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L10_challenge#2','soc',6,1,'u1','L10','g6_1_soc_u1_L10_challenge','lesson_challenge','SO6-1-u1-C18',2,'ox','auto','숨은 글씨 그림은 사건과 상관없이 쓰기 쉬운 낱말을 고르면 돼요.',ARRAY['SO6-1-u1-X32']::text[],false,'{"seq":2,"concept":"SO6-1-u1-C18","difficulty":2,"kind":"ox","stem":"숨은 글씨 그림은 사건과 상관없이 쓰기 쉬운 낱말을 고르면 돼요.","answer":"X","reason_options":[{"t":"고른 사건과 실제로 이어지는 낱말과 장면을 골라야 하기 때문에","correct":true},{"t":"쓰기 쉬운 낱말이 가장 잘 숨겨지기 때문에","mis":"SO6-1-u1-X32"}],"mis":"SO6-1-u1-X32","explanation":["사건과 이어져야 해요.","떠오르는 장면을 그려요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L10_challenge#3','soc',6,1,'u1','L10','g6_1_soc_u1_L10_challenge','lesson_challenge','SO6-1-u1-C18',3,'mc','auto','숨은 글씨 그림 계획표의 ①~⑤ 가운데 친구와 함께 하는 단계는 어느 것인가요?',ARRAY['SO6-1-u1-X32']::text[],false,'{"seq":3,"concept":"SO6-1-u1-C18","difficulty":3,"kind":"mc","stem":"숨은 글씨 그림 계획표의 ①~⑤ 가운데 친구와 함께 하는 단계는 어느 것인가요?","options":[{"t":"⑤","correct":true},{"t":"①","mis":"SO6-1-u1-X32"},{"t":"③","mis":"SO6-1-u1-X32"},{"t":"④","mis":"SO6-1-u1-X32"}],"explanation":["①~④는 내가 그려요.","⑤는 친구 그림을 봐요.","함께 하는 단계는 ⑤예요."],"asset":{"type":"passage","lines":["① 사건 — 6월 민주 항쟁 / 떠오르는 낱말 — 시위, 선거, 구호","② 그릴 낱말 — 「선거」","③ 장면 — 투표하려고 줄을 선 사람들의 몸과 팔로 글씨 획을 이룬다.","④ 「선거」 두 글자는 진하게, 나머지는 색칠한다.","⑤ 친구 그림에서 숨은 글씨를 찾고 느낀 점을 적는다."],"title":"숨은 글씨 그림 계획표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L10_challenge#4','soc',6,1,'u1','L10','g6_1_soc_u1_L10_challenge','lesson_challenge','SO6-1-u1-C18',3,'mc','auto','모든 획을 같은 진하기로 그렸을 때 숨긴 글씨가 잘 보이지 않는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X32']::text[],false,'{"seq":4,"concept":"SO6-1-u1-C18","difficulty":3,"kind":"mc","stem":"모든 획을 같은 진하기로 그렸을 때 숨긴 글씨가 잘 보이지 않는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"획은 다 있지만 어느 획이 글씨인지 구별되지 않기 때문에","correct":true},{"t":"글씨 획을 하나도 그리지 않았기 때문에","mis":"SO6-1-u1-X32"},{"t":"색칠을 너무 많이 했기 때문에","mis":"SO6-1-u1-X32"},{"t":"사건을 고르지 않았기 때문에","mis":"SO6-1-u1-X32"}],"explanation":["획은 이미 다 있어요.","진하기가 같으면 구별이 안 돼요.","그래서 글씨를 진하게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L10_challenge#5','soc',6,1,'u1','L10','g6_1_soc_u1_L10_challenge','lesson_challenge','SO6-1-u1-C18',3,'mc','auto','「분노」라는 글씨를 숨긴다면 어울리는 사건과 장면으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X32']::text[],false,'{"seq":5,"concept":"SO6-1-u1-C18","difficulty":3,"kind":"mc","stem":"「분노」라는 글씨를 숨긴다면 어울리는 사건과 장면으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"6월 민주 항쟁 — 정부의 독재에 반대하며 직선제를 요구하는 사람들의 모습","correct":true},{"t":"산업의 발달 — 공장에서 즐겁게 일하는 모습","mis":"SO6-1-u1-X32"},{"t":"평화 통일 노력 — 남북 정상이 악수하는 모습","mis":"SO6-1-u1-X32"},{"t":"숨은 글씨 그림 — 색칠 도구를 챙기는 모습","mis":"SO6-1-u1-X32"}],"explanation":["분노가 드러나는 사건이에요.","독재에 반대했어요.","직선제를 요구했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L10_challenge#6','soc',6,1,'u1','L10','g6_1_soc_u1_L10_challenge','lesson_challenge','SO6-1-u1-C18',3,'error','auto','숨은 글씨 그림을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u1-X32']::text[],false,'{"seq":6,"concept":"SO6-1-u1-C18","difficulty":3,"kind":"error","stem":"숨은 글씨 그림을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「숨긴 글씨는 흐리게 칠해야 더 잘 숨겨져.」","correct":true,"mis_target":"SO6-1-u1-X32"},{"t":"친구 가 — 「먼저 사건을 하나 고르고 관련 낱말을 써.」","mis":"SO6-1-u1-X32"},{"t":"친구 다 — 「장면을 이루는 획으로 글씨를 만들어.」","mis":"SO6-1-u1-X32"}],"explanation":["숨긴 글씨는 진하게 해요.","그래야 찾을 수 있어요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L10_challenge#7','soc',6,1,'u1','L10','g6_1_soc_u1_L10_challenge','lesson_challenge','SO6-1-u1-C10',3,'mc','auto','숨은 글씨 그림으로 역사적 사건을 다시 떠올리는 것이 공부에 도움이 되는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X31','SO6-1-u1-X32']::text[],false,'{"seq":7,"concept":"SO6-1-u1-C10","difficulty":3,"kind":"mc","stem":"숨은 글씨 그림으로 역사적 사건을 다시 떠올리는 것이 공부에 도움이 되는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"사건의 장면과 의미를 스스로 생각해 표현하며 다시 되짚기 때문에","correct":true},{"t":"사건의 날짜를 외우게 해 주기 때문에","mis":"SO6-1-u1-X31"},{"t":"사건과 상관없는 그림 실력만 늘기 때문에","mis":"SO6-1-u1-X32"},{"t":"친구 그림을 그대로 따라 그리기 때문에","mis":"SO6-1-u1-X32"}],"explanation":["장면을 떠올려요.","의미를 생각해요.","스스로 표현하며 되짚어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L10_challenge#8','soc',6,1,'u1','L10','g6_1_soc_u1_L10_challenge','lesson_challenge','SO6-1-u1-C18',4,'mc','auto','친구 그림을 보고 느낀 점을 쓴 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X32']::text[],false,'{"seq":8,"concept":"SO6-1-u1-C18","difficulty":4,"kind":"mc","stem":"친구 그림을 보고 느낀 점을 쓴 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"여러 사람의 모습으로 「혁명」 글자를 숨긴 것이 재미있었고, 그날 학생들의 마음을 다시 생각하게 되었다","correct":true},{"t":"친구 그림은 내 그림보다 못하다","mis":"SO6-1-u1-X32"},{"t":"숨은 글씨를 찾지 못했으니 아무 느낌이 없다","mis":"SO6-1-u1-X32"},{"t":"그림이 어떤 사건인지는 상관없다","mis":"SO6-1-u1-X32"}],"explanation":["숨은 글씨를 찾아요.","인상 깊은 점을 말해요.","사건을 다시 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L10_challenge#9','soc',6,1,'u1','L10','g6_1_soc_u1_L10_challenge','lesson_challenge','SO6-1-u1-C18',4,'mc','auto','숨은 글씨 그림의 차례를 가장 바르게 정리한 것은 어느 것인가요?',ARRAY['SO6-1-u1-X32']::text[],false,'{"seq":9,"concept":"SO6-1-u1-C18","difficulty":4,"kind":"mc","stem":"숨은 글씨 그림의 차례를 가장 바르게 정리한 것은 어느 것인가요?","options":[{"t":"사건과 관련 낱말 쓰기 → 그릴 낱말과 숨길 방법 정하기 → 글씨는 진하게·나머지는 색칠 → 친구 그림에서 찾고 느낀 점 나누기","correct":true},{"t":"색칠하기 → 사건 고르기 → 친구 그림 보기 → 낱말 쓰기","mis":"SO6-1-u1-X32"},{"t":"친구 그림 보기 → 색칠하기 → 낱말 쓰기 → 사건 고르기","mis":"SO6-1-u1-X32"},{"t":"낱말 쓰기 → 친구 그림 보기 → 사건 고르기 → 색칠하기","mis":"SO6-1-u1-X32"}],"explanation":["사건과 낱말이 먼저예요.","숨길 방법을 정하고 그려요.","마지막에 친구와 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_L10_challenge#10','soc',6,1,'u1','L10','g6_1_soc_u1_L10_challenge','lesson_challenge','SO6-1-u1-C18',4,'essay','teacher','이 단원에서 공부한 역사적 사건 하나를 골라 숨길 낱말과 그릴 장면을 쓰고, 그 낱말과 장면을 고른 까닭을 사건의 내용과 이어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-1-u1-C18","difficulty":4,"kind":"essay","stem":"이 단원에서 공부한 역사적 사건 하나를 골라 숨길 낱말과 그릴 장면을 쓰고, 그 낱말과 장면을 고른 까닭을 사건의 내용과 이어 쓰세요.","answer_guide":{"answer":"예: 사건은 6월 민주 항쟁이고, 숨길 낱말은 「선거」이다. 투표하려고 길게 줄을 선 사람들의 몸과 팔로 글씨의 획을 만들고 「선거」 두 글자는 진하게 칠하겠다. 6월 민주 항쟁의 결과 국민이 직접 대통령을 뽑는 직선제가 시행되어 많은 사람이 줄지어 투표했기 때문에 이 낱말과 장면을 골랐다.","scoring_points":["사건과 숨길 낱말을 썼는가","그릴 장면과 숨기는 방법을 썼는가","사건의 내용과 이어 까닭을 썼는가"]},"explanation":["사건과 낱말을 골라요.","장면 속에 숨길 방법을 써요.","사건 내용과 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_a#1','soc',6,1,'u1','','g6_1_soc_u1_review_a','unit_review','SO6-1-u1-C2',1,'mc','auto','신문 ①의 할아버지처럼 분단으로 고향을 잃어 고향에 갈 수 없는 사람을 무엇이라고 하나요?',ARRAY['SO6-1-u1-X02']::text[],false,'{"seq":1,"concept":"SO6-1-u1-C2","difficulty":1,"kind":"mc","stem":"신문 ①의 할아버지처럼 분단으로 고향을 잃어 고향에 갈 수 없는 사람을 무엇이라고 하나요?","options":[{"t":"실향민","correct":true},{"t":"관광객","mis":"SO6-1-u1-X02"},{"t":"외교관","mis":"SO6-1-u1-X02"},{"t":"연구자","mis":"SO6-1-u1-X02"}],"explanation":["고향을 잃었어요.","고향에 갈 수 없어요.","실향민이에요."],"asset":{"type":"passage","lines":["우리 반은 이웃에 사시는 실향민 할아버지를 찾아가 이야기를 들었다.","할아버지의 고향은 휴전선 너머라 명절마다 고향 쪽을 바라보신다고 했다.","북쪽에 남은 동생을 지금도 만나지 못하셨다.","「그쪽 사람들도 우리처럼 가족을 그리워하겠지.」 하고 말씀하셨다."],"title":"햇살반 역사 신문 ① 할아버지의 고향"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_a#2','soc',6,1,'u1','','g6_1_soc_u1_review_a','unit_review','SO6-1-u1-C3',1,'mc','auto','전쟁 뒤 피란 왔다가 돌아가지 못한 사람들이 모여 살며 만들어진 곳은 어느 것인가요?',ARRAY['SO6-1-u1-X05','SO6-1-u1-X07']::text[],false,'{"seq":2,"concept":"SO6-1-u1-C3","difficulty":1,"kind":"mc","stem":"전쟁 뒤 피란 왔다가 돌아가지 못한 사람들이 모여 살며 만들어진 곳은 어느 것인가요?","options":[{"t":"아바이 마을","correct":true},{"t":"판문점","mis":"SO6-1-u1-X05"},{"t":"휴전선","mis":"SO6-1-u1-X05"},{"t":"DMZ 평화의 길","mis":"SO6-1-u1-X07"}],"explanation":["피란민이 모였어요.","돌아가지 못했어요.","아바이 마을이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_a#3','soc',6,1,'u1','','g6_1_soc_u1_review_a','unit_review','SO6-1-u1-C6',1,'mc','auto','신문 ③의 ㉮처럼 남북이 함께 만드는 국어사전의 이름은 무엇인가요?',ARRAY['SO6-1-u1-X09']::text[],false,'{"seq":3,"concept":"SO6-1-u1-C6","difficulty":1,"kind":"mc","stem":"신문 ③의 ㉮처럼 남북이 함께 만드는 국어사전의 이름은 무엇인가요?","options":[{"t":"겨레말큰사전","correct":true},{"t":"남북 기본 합의서","mis":"SO6-1-u1-X09"},{"t":"7·4 남북 공동 성명","mis":"SO6-1-u1-X09"},{"t":"개성 만월대","mis":"SO6-1-u1-X09"}],"explanation":["겨레의 말을 모아요.","남북이 함께 만들어요.","『겨레말큰사전』이에요."],"asset":{"type":"passage","lines":["㉮ 남북 국어학자들이 함께 만드는 사전 — 달라진 말을 모아 싣는다.","㉯ 남북 학자들의 문화유산 공동 발굴 — 고려의 궁궐터에서 했다.","㉰ 공업 단지 — 남한의 자본·기술과 북한의 노동력을 합했다.","㉱ 철도·도로 연결 — 끊어진 길을 다시 이으려 했다."],"title":"햇살반 역사 신문 ③ 남북이 함께한 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_a#4','soc',6,1,'u1','','g6_1_soc_u1_review_a','unit_review','SO6-1-u1-C8',1,'mc','auto','신문 ④의 ⓒ처럼 알뜰 시장을 열어 모은 돈을 보내는 것은 어떤 실천인가요?',ARRAY['SO6-1-u1-X14','SO6-1-u1-X09']::text[],false,'{"seq":4,"concept":"SO6-1-u1-C8","difficulty":1,"kind":"mc","stem":"신문 ④의 ⓒ처럼 알뜰 시장을 열어 모은 돈을 보내는 것은 어떤 실천인가요?","options":[{"t":"어려움을 겪는 북한 주민 돕기","correct":true},{"t":"평화 통일의 의미 알리기","mis":"SO6-1-u1-X14"},{"t":"통일 원칙 합의하기","mis":"SO6-1-u1-X09"},{"t":"남북 경제 협력 사업 하기","mis":"SO6-1-u1-X09"}],"explanation":["모은 돈을 보냈어요.","어려운 사람을 도와요.","북한 주민 돕기예요."],"asset":{"type":"passage","lines":["ⓐ 남북 음식을 골라 평화 통일 밥상을 그렸다.","ⓑ 「우리는 한민족, 언제나 함께」를 쓴 종이비행기를 날렸다.","ⓒ 알뜰 시장을 열어 모은 돈을 북한 어린이 돕기에 보냈다.","ⓓ 통일 퀴즈 대회를 열어 다른 반 친구들도 초대했다."],"title":"햇살반 역사 신문 ④ 우리 반 통일 주간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_a#5','soc',6,1,'u1','','g6_1_soc_u1_review_a','unit_review','SO6-1-u1-C9',1,'mc','auto','신문 ⑤에서 4·19 혁명의 원인으로 적힌 것은 무엇인가요?',ARRAY['SO6-1-u1-X24','SO6-1-u1-X15']::text[],false,'{"seq":5,"concept":"SO6-1-u1-C9","difficulty":1,"kind":"mc","stem":"신문 ⑤에서 4·19 혁명의 원인으로 적힌 것은 무엇인가요?","options":[{"t":"3·15 부정 선거","correct":true},{"t":"군인들의 권력 장악","mis":"SO6-1-u1-X24"},{"t":"간선제 유지","mis":"SO6-1-u1-X24"},{"t":"경제 개발 계획","mis":"SO6-1-u1-X15"}],"explanation":["선거가 부정했어요.","3월 15일이었어요.","3·15 부정 선거예요."],"asset":{"type":"passage","lines":["4·19 혁명 — 3·15 부정 선거 → 각계각층의 시위 → 대통령이 물러남","5·18 민주화 운동 — 군인들의 권력 장악 → 광주 시민의 민주화 요구","6월 민주 항쟁 — 독재와 간선제 유지 → 전국의 직선제 요구 → 직선제","세 사건 모두 시민이 민주주의를 지키려고 나선 일이다."],"title":"햇살반 역사 신문 ⑤ 민주화 흐름 코너"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
