INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_a#7','soc',6,1,'u1','','g6_1_soc_u1_review_a','unit_review','SO6-1-u1-C12',1,'mc','auto','6월 민주 항쟁에서 시민들이 요구한 선거 제도는 무엇인가요?',ARRAY['SO6-1-u1-X22','SO6-1-u1-X21','SO6-1-u1-X24']::text[],false,'{"seq":7,"concept":"SO6-1-u1-C12","difficulty":1,"kind":"mc","stem":"6월 민주 항쟁에서 시민들이 요구한 선거 제도는 무엇인가요?","options":[{"t":"대통령 직선제","correct":true},{"t":"간선제","mis":"SO6-1-u1-X22"},{"t":"선거인단 제도","mis":"SO6-1-u1-X21"},{"t":"정부통령 선거","mis":"SO6-1-u1-X24"}],"explanation":["국민이 직접 뽑아요.","헌법을 고쳐야 했어요.","대통령 직선제예요."],"asset":{"type":"passage","lines":["4·19 혁명 — 3·15 부정 선거 → 각계각층의 시위 → 대통령이 물러남","5·18 민주화 운동 — 군인들의 권력 장악 → 광주 시민의 민주화 요구","6월 민주 항쟁 — 독재와 간선제 유지 → 전국의 직선제 요구 → 직선제","세 사건 모두 시민이 민주주의를 지키려고 나선 일이다."],"title":"햇살반 역사 신문 ⑤ 민주화 흐름 코너"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_a#8','soc',6,1,'u1','','g6_1_soc_u1_review_a','unit_review','SO6-1-u1-C14',1,'mc','auto','신문 ⑦에서 할아버지가 청년 때 일한 신발 공장은 어떤 공업에 속하나요?',ARRAY['SO6-1-u1-X25']::text[],false,'{"seq":8,"concept":"SO6-1-u1-C14","difficulty":1,"kind":"mc","stem":"신문 ⑦에서 할아버지가 청년 때 일한 신발 공장은 어떤 공업에 속하나요?","options":[{"t":"경공업","correct":true},{"t":"중화학 공업","mis":"SO6-1-u1-X25"},{"t":"석유 화학 공업","mis":"SO6-1-u1-X25"},{"t":"조선업","mis":"SO6-1-u1-X25"}],"explanation":["신발은 가벼워요.","가벼운 물건을 만들어요.","경공업이에요."],"asset":{"type":"passage","lines":["어릴 때 — 지원받은 밀가루로 만든 국수를 자주 드셨다.","청년 때 — 신발 공장에서 만든 신발이 배에 실려 외국으로 팔렸다.","그 뒤 — 큰 조선소에서 커다란 배를 만드는 일을 하셨다.","아빠가 어릴 때 — 우리 집에 자동차와 컬러텔레비전이 생겼다."],"title":"햇살반 역사 신문 ⑦ 할아버지의 일터"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_a#9','soc',6,1,'u1','','g6_1_soc_u1_review_a','unit_review','SO6-1-u1-C4',2,'mc','auto','신문 ①에서 할아버지의 말 「그쪽 사람들도 우리처럼 가족을 그리워하겠지」에 담긴 생각으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X04','SO6-1-u1-X02']::text[],false,'{"seq":9,"concept":"SO6-1-u1-C4","difficulty":2,"kind":"mc","stem":"신문 ①에서 할아버지의 말 「그쪽 사람들도 우리처럼 가족을 그리워하겠지」에 담긴 생각으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"분단의 아픔은 남과 북 사람 모두가 함께 겪는 것이다","correct":true},{"t":"북한 사람들은 우리와 다른 적이다","mis":"SO6-1-u1-X04"},{"t":"분단은 한쪽 사람들만의 문제다","mis":"SO6-1-u1-X04"},{"t":"가족을 그리워하는 마음은 곧 사라진다","mis":"SO6-1-u1-X02"}],"explanation":["그쪽 사람도 가족이 있어요.","함께 그리워해요.","아픔을 함께 겪어요."],"asset":{"type":"passage","lines":["우리 반은 이웃에 사시는 실향민 할아버지를 찾아가 이야기를 들었다.","할아버지의 고향은 휴전선 너머라 명절마다 고향 쪽을 바라보신다고 했다.","북쪽에 남은 동생을 지금도 만나지 못하셨다.","「그쪽 사람들도 우리처럼 가족을 그리워하겠지.」 하고 말씀하셨다."],"title":"햇살반 역사 신문 ① 할아버지의 고향"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_a#10','soc',6,1,'u1','','g6_1_soc_u1_review_a','unit_review','SO6-1-u1-C4',2,'mc','auto','신문 ②에서 모둠이 누리집에서 살핀 차례로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X08']::text[],false,'{"seq":10,"concept":"SO6-1-u1-C4","difficulty":2,"kind":"mc","stem":"신문 ②에서 모둠이 누리집에서 살핀 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"의미 → 있었던 일 → 주요 시설","correct":true},{"t":"주요 시설 → 의미 → 있었던 일","mis":"SO6-1-u1-X08"},{"t":"있었던 일 → 주요 시설 → 의미","mis":"SO6-1-u1-X08"},{"t":"차례 없이 사진만 보았다","mis":"SO6-1-u1-X08"}],"explanation":["먼저 의미를 알아봐요.","그다음 사건이에요.","마지막에 시설을 봐요."],"asset":{"type":"passage","lines":["우리 모둠은 인터넷으로 DMZ 평화의 길을 답사했다.","누리집에서 그곳의 의미, 있었던 일, 주요 시설을 차례로 살폈다.","희귀한 새와 식물 사진이 많아 모두 놀랐다.","통일 뒤에는 이곳을 평화 생태 학습장으로 만들자고 기사에 썼다."],"title":"햇살반 역사 신문 ② 답사 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_a#11','soc',6,1,'u1','','g6_1_soc_u1_review_a','unit_review','SO6-1-u1-C6',2,'match','auto','신문 ③의 남북이 함께한 일과 그 분야를 알맞게 이으세요.','{}'::text[],false,'{"seq":11,"concept":"SO6-1-u1-C6","difficulty":2,"kind":"match","stem":"신문 ③의 남북이 함께한 일과 그 분야를 알맞게 이으세요.","pairs":[{"l":"㉮ 사전 만들기","r":"사회·문화적 노력"},{"l":"㉰ 공업 단지","r":"경제적 노력"},{"l":"남북 기본 합의서","r":"정치적 노력"}],"mis":"SO6-1-u1-X09","explanation":["사전은 말과 문화예요.","공업 단지는 경제예요.","합의서는 정치예요."],"asset":{"type":"passage","lines":["㉮ 남북 국어학자들이 함께 만드는 사전 — 달라진 말을 모아 싣는다.","㉯ 남북 학자들의 문화유산 공동 발굴 — 고려의 궁궐터에서 했다.","㉰ 공업 단지 — 남한의 자본·기술과 북한의 노동력을 합했다.","㉱ 철도·도로 연결 — 끊어진 길을 다시 이으려 했다."],"title":"햇살반 역사 신문 ③ 남북이 함께한 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_a#12','soc',6,1,'u1','','g6_1_soc_u1_review_a','unit_review','SO6-1-u1-C8',2,'match','auto','신문 ④의 활동과 그 활동이 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":12,"concept":"SO6-1-u1-C8","difficulty":2,"kind":"match","stem":"신문 ④의 활동과 그 활동이 하는 일을 알맞게 이으세요.","pairs":[{"l":"ⓑ 종이비행기","r":"통일을 바라는 마음 키우기"},{"l":"ⓒ 알뜰 시장","r":"북한 주민 돕기"},{"l":"ⓓ 퀴즈 대회","r":"의미와 중요성 알리기"}],"mis":"SO6-1-u1-X14","explanation":["ⓑ는 마음을 담아 날려요.","ⓒ는 도와요.","ⓓ는 알려요."],"asset":{"type":"passage","lines":["ⓐ 남북 음식을 골라 평화 통일 밥상을 그렸다.","ⓑ 「우리는 한민족, 언제나 함께」를 쓴 종이비행기를 날렸다.","ⓒ 알뜰 시장을 열어 모은 돈을 북한 어린이 돕기에 보냈다.","ⓓ 통일 퀴즈 대회를 열어 다른 반 친구들도 초대했다."],"title":"햇살반 역사 신문 ④ 우리 반 통일 주간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_a#13','soc',6,1,'u1','','g6_1_soc_u1_review_a','unit_review','SO6-1-u1-C9',2,'mc','auto','신문 ⑤의 4·19 혁명처럼 국민이 부정 선거에 맞선 까닭과 이어지는 것으로, 부정 선거가 낳는 문제는 어느 것인가요?',ARRAY['SO6-1-u1-X15']::text[],false,'{"seq":13,"concept":"SO6-1-u1-C9","difficulty":2,"kind":"mc","stem":"신문 ⑤의 4·19 혁명처럼 국민이 부정 선거에 맞선 까닭과 이어지는 것으로, 부정 선거가 낳는 문제는 어느 것인가요?","options":[{"t":"국민의 뜻이 제대로 전달되지 않는다","correct":true},{"t":"국민의 뜻이 더 잘 전달된다","mis":"SO6-1-u1-X15"},{"t":"표를 더 빨리 셀 수 있다","mis":"SO6-1-u1-X15"},{"t":"아무 문제가 없다","mis":"SO6-1-u1-X15"}],"explanation":["표가 왜곡돼요.","결과를 믿기 어려워요.","국민의 뜻이 전달되지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_a#14','soc',6,1,'u1','','g6_1_soc_u1_review_a','unit_review','SO6-1-u1-C13',2,'mc','auto','신문 ⑥에서 할머니가 투표소 앞에 길게 줄을 서고도 웃는 얼굴이었던 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X23','SO6-1-u1-X21']::text[],false,'{"seq":14,"concept":"SO6-1-u1-C13","difficulty":2,"kind":"mc","stem":"신문 ⑥에서 할머니가 투표소 앞에 길게 줄을 서고도 웃는 얼굴이었던 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"국민이 직접 대통령을 뽑을 수 있게 되었기 때문에","correct":true},{"t":"투표하면 선물을 받았기 때문에","mis":"SO6-1-u1-X23"},{"t":"선거인단만 투표할 수 있었기 때문에","mis":"SO6-1-u1-X21"},{"t":"투표를 하지 않아도 되었기 때문에","mis":"SO6-1-u1-X23"}],"explanation":["처음 직접 뽑았어요.","주권을 행사했어요.","그래서 기뻤어요."],"asset":{"type":"passage","lines":["할머니는 대통령을 처음 직접 뽑던 날을 또렷이 기억하신다.","투표소 앞에 줄이 길게 늘어섰는데도 모두 웃는 얼굴이었다고 했다.","요즘은 우리 지역의 대표도 주민이 직접 뽑는다.","할머니는 시민 단체에서 하천 지킴이로 활동하신다."],"title":"햇살반 역사 신문 ⑥ 할머니의 투표 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_a#15','soc',6,1,'u1','','g6_1_soc_u1_review_a','unit_review','SO6-1-u1-C14',2,'mc','auto','신문 ⑦에서 할아버지가 어릴 때 지원받은 밀가루로 만든 음식을 드신 시기에 발달한 산업은 어느 것인가요?',ARRAY['SO6-1-u1-X26']::text[],false,'{"seq":15,"concept":"SO6-1-u1-C14","difficulty":2,"kind":"mc","stem":"신문 ⑦에서 할아버지가 어릴 때 지원받은 밀가루로 만든 음식을 드신 시기에 발달한 산업은 어느 것인가요?","options":[{"t":"밀가루·설탕·면직물 같은 생활에 필요한 물건을 만드는 산업","correct":true},{"t":"자동차·전자 제품 산업","mis":"SO6-1-u1-X26"},{"t":"철강·조선 같은 중화학 공업","mis":"SO6-1-u1-X26"},{"t":"신발·가발 수출 산업","mis":"SO6-1-u1-X26"}],"explanation":["전쟁 뒤 물자를 지원받았어요.","생활용품을 만들었어요.","1950년대의 모습이에요."],"asset":{"type":"passage","lines":["어릴 때 — 지원받은 밀가루로 만든 국수를 자주 드셨다.","청년 때 — 신발 공장에서 만든 신발이 배에 실려 외국으로 팔렸다.","그 뒤 — 큰 조선소에서 커다란 배를 만드는 일을 하셨다.","아빠가 어릴 때 — 우리 집에 자동차와 컬러텔레비전이 생겼다."],"title":"햇살반 역사 신문 ⑦ 할아버지의 일터"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_a#16','soc',6,1,'u1','','g6_1_soc_u1_review_a','unit_review','SO6-1-u1-C17',2,'mc','auto','신문 ⑧에서 할머니가 도시로 와서 언덕 위 동네에 사신 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X28','SO6-1-u1-X29']::text[],false,'{"seq":16,"concept":"SO6-1-u1-C17","difficulty":2,"kind":"mc","stem":"신문 ⑧에서 할머니가 도시로 와서 언덕 위 동네에 사신 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"도시로 사람이 몰려 일자리와 집이 부족했기 때문에","correct":true},{"t":"도시에 집이 너무 많이 남았기 때문에","mis":"SO6-1-u1-X28"},{"t":"농촌이 도시보다 일자리가 많았기 때문에","mis":"SO6-1-u1-X28"},{"t":"도시와 농촌의 소득이 같았기 때문에","mis":"SO6-1-u1-X29"}],"explanation":["사람이 몰렸어요.","집이 모자랐어요.","높은 곳에 모여 살았어요."],"asset":{"type":"passage","lines":["할머니는 시골에서 도시로 이사 와 언덕 위 동네에 사셨다.","고속 국도가 생기자 고향에 하루 만에 다녀올 수 있었다.","공장 언니들은 밤늦게까지 일하고 쉬는 날이 적었다.","일하는 사람의 권리를 지키자는 목소리가 점점 커졌다.","우리 반은 이 이야기로 숨은 글씨 그림도 그렸다."],"title":"햇살반 역사 신문 ⑧ 도시로 온 할머니"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_a#17','soc',6,1,'u1','','g6_1_soc_u1_review_a','unit_review','SO6-1-u1-C4',3,'mc','auto','신문 ①과 ②를 함께 볼 때 분단의 아픔을 대하는 우리의 태도로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X07','SO6-1-u1-X04','SO6-1-u1-X13']::text[],false,'{"seq":17,"concept":"SO6-1-u1-C4","difficulty":3,"kind":"mc","stem":"신문 ①과 ②를 함께 볼 때 분단의 아픔을 대하는 우리의 태도로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"아픔을 기억하며 그 장소를 평화를 배우는 곳으로 바꾸어 간다","correct":true},{"t":"아픔은 빨리 잊고 장소도 없앤다","mis":"SO6-1-u1-X07"},{"t":"북한 사람을 탓하며 멀리한다","mis":"SO6-1-u1-X04"},{"t":"분단은 할아버지 세대의 일이라 관계없다","mis":"SO6-1-u1-X13"}],"explanation":["①은 아픔이에요.","②는 평화의 장소예요.","기억하며 평화로 바꾸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_a#18','soc',6,1,'u1','','g6_1_soc_u1_review_a','unit_review','SO6-1-u1-C9',3,'mc','auto','평화 통일을 위한 노력을 분야별로 바르게 짝지은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X09']::text[],false,'{"seq":18,"concept":"SO6-1-u1-C9","difficulty":3,"kind":"mc","stem":"평화 통일을 위한 노력을 분야별로 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"정치 — 남북 기본 합의서 · 사회·문화 — 문화유산 공동 발굴 · 경제 — 공업 단지","correct":true},{"t":"정치 — 공업 단지 · 사회·문화 — 남북 기본 합의서 · 경제 — 문화유산 공동 발굴","mis":"SO6-1-u1-X09"},{"t":"정치 — 문화유산 공동 발굴 · 사회·문화 — 공업 단지 · 경제 — 남북 기본 합의서","mis":"SO6-1-u1-X09"},{"t":"세 노력 모두 경제 분야이다","mis":"SO6-1-u1-X09"}],"explanation":["합의서는 정치예요.","발굴은 사회·문화예요.","공업 단지는 경제예요."],"asset":{"type":"passage","lines":["㉮ 남북 국어학자들이 함께 만드는 사전 — 달라진 말을 모아 싣는다.","㉯ 남북 학자들의 문화유산 공동 발굴 — 고려의 궁궐터에서 했다.","㉰ 공업 단지 — 남한의 자본·기술과 북한의 노동력을 합했다.","㉱ 철도·도로 연결 — 끊어진 길을 다시 이으려 했다."],"title":"햇살반 역사 신문 ③ 남북이 함께한 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_a#19','soc',6,1,'u1','','g6_1_soc_u1_review_a','unit_review','SO6-1-u1-C12',3,'mc','auto','신문 ⑤의 세 사건과 그 결과를 바르게 짝지은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X24']::text[],false,'{"seq":19,"concept":"SO6-1-u1-C12","difficulty":3,"kind":"mc","stem":"신문 ⑤의 세 사건과 그 결과를 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"4·19 혁명 — 대통령이 물러남 · 6월 민주 항쟁 — 대통령 직선제 시행","correct":true},{"t":"4·19 혁명 — 대통령 직선제 시행 · 6월 민주 항쟁 — 대통령이 물러남","mis":"SO6-1-u1-X24"},{"t":"4·19 혁명 — 군인이 권력을 잡음 · 6월 민주 항쟁 — 간선제 유지","mis":"SO6-1-u1-X24"},{"t":"두 사건 모두 아무 결과가 없었다","mis":"SO6-1-u1-X24"}],"explanation":["4·19는 대통령이 물러났어요.","6월 민주 항쟁은 직선제예요.","결과를 바꾸지 말아요."],"asset":{"type":"passage","lines":["4·19 혁명 — 3·15 부정 선거 → 각계각층의 시위 → 대통령이 물러남","5·18 민주화 운동 — 군인들의 권력 장악 → 광주 시민의 민주화 요구","6월 민주 항쟁 — 독재와 간선제 유지 → 전국의 직선제 요구 → 직선제","세 사건 모두 시민이 민주주의를 지키려고 나선 일이다."],"title":"햇살반 역사 신문 ⑤ 민주화 흐름 코너"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_a#20','soc',6,1,'u1','','g6_1_soc_u1_review_a','unit_review','SO6-1-u1-C11',3,'mc','auto','5·18 민주화 운동의 진실을 오늘날 우리가 알 수 있는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X19']::text[],false,'{"seq":20,"concept":"SO6-1-u1-C11","difficulty":3,"kind":"mc","stem":"5·18 민주화 운동의 진실을 오늘날 우리가 알 수 있는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"막혀 있던 광주의 일을 기록하고 세계에 알린 사람들이 있었기 때문에","correct":true},{"t":"그때 방송이 모든 일을 자유롭게 보도했기 때문에","mis":"SO6-1-u1-X19"},{"t":"계엄군이 광주 소식을 널리 알렸기 때문에","mis":"SO6-1-u1-X19"},{"t":"광주가 바깥과 늘 자유롭게 오갔기 때문에","mis":"SO6-1-u1-X19"}],"explanation":["바깥과 막혀 있었어요.","기록하고 알린 사람이 있었어요.","그래서 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_a#21','soc',6,1,'u1','','g6_1_soc_u1_review_a','unit_review','SO6-1-u1-C14',3,'mc','auto','신문 ⑦의 네 장면을 산업 발달의 흐름에 맞게 정리한 것은 어느 것인가요?',ARRAY['SO6-1-u1-X26']::text[],false,'{"seq":21,"concept":"SO6-1-u1-C14","difficulty":3,"kind":"mc","stem":"신문 ⑦의 네 장면을 산업 발달의 흐름에 맞게 정리한 것은 어느 것인가요?","options":[{"t":"생활용품 → 경공업 → 중화학 공업 → 소득이 늘어 생활 수준 향상","correct":true},{"t":"중화학 공업 → 경공업 → 생활용품 → 소득 감소","mis":"SO6-1-u1-X26"},{"t":"경공업 → 생활용품 → 소득 향상 → 중화학 공업","mis":"SO6-1-u1-X26"},{"t":"산업의 변화가 없었다","mis":"SO6-1-u1-X26"}],"explanation":["밀가루가 먼저예요.","신발, 배 순서예요.","마지막에 생활이 넉넉해졌어요."],"asset":{"type":"passage","lines":["어릴 때 — 지원받은 밀가루로 만든 국수를 자주 드셨다.","청년 때 — 신발 공장에서 만든 신발이 배에 실려 외국으로 팔렸다.","그 뒤 — 큰 조선소에서 커다란 배를 만드는 일을 하셨다.","아빠가 어릴 때 — 우리 집에 자동차와 컬러텔레비전이 생겼다."],"title":"햇살반 역사 신문 ⑦ 할아버지의 일터"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_a#22','soc',6,1,'u1','','g6_1_soc_u1_review_a','unit_review','SO6-1-u1-C17',3,'mc','auto','신문 ⑧을 읽고 산업화를 바라보는 생각으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X29','SO6-1-u1-X28']::text[],false,'{"seq":22,"concept":"SO6-1-u1-C17","difficulty":3,"kind":"mc","stem":"신문 ⑧을 읽고 산업화를 바라보는 생각으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"생활이 편리해진 점과 근로자의 어려움 같은 그늘을 함께 보아야 한다","correct":true},{"t":"편리해졌으니 그늘은 생각할 필요가 없다","mis":"SO6-1-u1-X29"},{"t":"그늘이 있으니 산업화는 모두 잘못이다","mis":"SO6-1-u1-X29"},{"t":"산업화는 할머니의 생활과 관계없다","mis":"SO6-1-u1-X28"}],"explanation":["하루 생활권이 좋아졌어요.","공장 언니들은 힘들었어요.","두 면을 함께 봐요."],"asset":{"type":"passage","lines":["할머니는 시골에서 도시로 이사 와 언덕 위 동네에 사셨다.","고속 국도가 생기자 고향에 하루 만에 다녀올 수 있었다.","공장 언니들은 밤늦게까지 일하고 쉬는 날이 적었다.","일하는 사람의 권리를 지키자는 목소리가 점점 커졌다.","우리 반은 이 이야기로 숨은 글씨 그림도 그렸다."],"title":"햇살반 역사 신문 ⑧ 도시로 온 할머니"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_a#23','soc',6,1,'u1','','g6_1_soc_u1_review_a','unit_review','SO6-1-u1-C9',4,'mc','auto','「평화 통일을 위한 노력, 민주화와 산업화」 단원에서 배운 내용을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO6-1-u1-X24','SO6-1-u1-X27','SO6-1-u1-X31']::text[],false,'{"seq":23,"concept":"SO6-1-u1-C9","difficulty":4,"kind":"mc","stem":"「평화 통일을 위한 노력, 민주화와 산업화」 단원에서 배운 내용을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"분단의 아픔을 넘어 평화 통일을 위해 노력하고, 시민의 힘으로 민주화를, 여러 사람의 노력으로 산업화를 이루며 생활이 달라졌다","correct":true},{"t":"분단은 문제가 없고, 민주화와 산업화는 저절로 이루어졌다","mis":"SO6-1-u1-X24"},{"t":"평화 통일은 어른만, 민주화는 군인이, 산업화는 정부만 이루었다","mis":"SO6-1-u1-X27"},{"t":"이 단원은 날짜와 숫자만 외우면 된다","mis":"SO6-1-u1-X31"}],"explanation":["분단과 평화 통일이에요.","시민의 민주화예요.","여러 사람의 산업화예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_a#24','soc',6,1,'u1','','g6_1_soc_u1_review_a','unit_review','SO6-1-u1-C2',4,'essay','teacher','신문 ①을 보고 분단으로 나타난 문제점 두 가지를 쓰고, 신문 ③에서 그 문제를 줄이는 데 도움이 될 남북의 노력을 하나 골라 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO6-1-u1-C2","difficulty":4,"kind":"essay","stem":"신문 ①을 보고 분단으로 나타난 문제점 두 가지를 쓰고, 신문 ③에서 그 문제를 줄이는 데 도움이 될 남북의 노력을 하나 골라 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 분단으로 할아버지처럼 고향과 가족을 만나지 못하는 실향민과 이산가족의 아픔이 생겼고, 남북의 말과 생활 방식의 차이가 커지고 있다. 남북이 함께 만드는 사전은 달라진 말을 서로 이해하게 도와 언어 차이로 생기는 어려움을 줄이고 한민족임을 잊지 않게 해 준다.","scoring_points":["분단의 문제점 두 가지를 썼는가","남북의 노력을 하나 골랐는가","문제를 줄이는 까닭을 썼는가"]},"explanation":["아픔과 차이를 떠올려요.","③에서 하나 골라요.","까닭을 이어 써요."],"asset":{"type":"passage","lines":["우리 반은 이웃에 사시는 실향민 할아버지를 찾아가 이야기를 들었다.","할아버지의 고향은 휴전선 너머라 명절마다 고향 쪽을 바라보신다고 했다.","북쪽에 남은 동생을 지금도 만나지 못하셨다.","「그쪽 사람들도 우리처럼 가족을 그리워하겠지.」 하고 말씀하셨다."],"title":"햇살반 역사 신문 ① 할아버지의 고향"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_a#25','soc',6,1,'u1','','g6_1_soc_u1_review_a','unit_review','SO6-1-u1-C4',4,'essay','teacher','신문 ②의 답사처럼 분단의 아픔이 담긴 장소 한 곳을 답사한다고 생각하고, 답사의 차례와 그곳을 평화의 장소로 바꾸는 방법을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO6-1-u1-C4","difficulty":4,"kind":"essay","stem":"신문 ②의 답사처럼 분단의 아픔이 담긴 장소 한 곳을 답사한다고 생각하고, 답사의 차례와 그곳을 평화의 장소로 바꾸는 방법을 쓰세요.","answer_guide":{"answer":"예: 판문점을 답사하겠다. 먼저 누리집을 방문해 판문점이 정전 협정과 남북 정상 회담의 장소라는 의미를 알아보고, 그곳에서 있었던 일과 주요 시설을 차례로 살핀 뒤 느낀 점을 쓰겠다. 통일이 되면 판문점을 남북 어린이가 함께 평화를 배우는 평화 교실로 만들고 싶다.","scoring_points":["장소를 골랐는가","답사의 차례를 썼는가","평화의 장소로 바꾸는 방법을 썼는가"]},"explanation":["장소를 골라요.","의미 → 사건 → 시설 차례예요.","평화의 장소로 바꿀 방법을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_b#1','soc',6,1,'u1','','g6_1_soc_u1_review_b','unit_review','SO6-1-u1-C1',1,'sa','auto','광복 뒤 남과 북으로 나뉜 우리나라의 분단을 더욱 굳어지게 한 전쟁을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-1-u1-C1","difficulty":1,"kind":"sa","stem":"광복 뒤 남과 북으로 나뉜 우리나라의 분단을 더욱 굳어지게 한 전쟁을 쓰세요.","answer":["6·25 전쟁","6.25 전쟁","6·25전쟁","육이오 전쟁"],"explanation":["광복 뒤에 일어났어요.","분단이 굳어졌어요.","6·25 전쟁이에요."],"mis":"SO6-1-u1-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_b#2','soc',6,1,'u1','','g6_1_soc_u1_review_b','unit_review','SO6-1-u1-C4',1,'mc','auto','신문 ②에서 모둠이 답사한 곳은 아픔이 담긴 장소를 어떻게 바꾼 사례인가요?',ARRAY['SO6-1-u1-X07']::text[],false,'{"seq":2,"concept":"SO6-1-u1-C4","difficulty":1,"kind":"mc","stem":"신문 ②에서 모둠이 답사한 곳은 아픔이 담긴 장소를 어떻게 바꾼 사례인가요?","options":[{"t":"평화의 장소로 바꾼 사례","correct":true},{"t":"군사 시설로 바꾼 사례","mis":"SO6-1-u1-X07"},{"t":"흔적을 모두 없앤 사례","mis":"SO6-1-u1-X07"},{"t":"공장으로 바꾼 사례","mis":"SO6-1-u1-X07"}],"explanation":["남북 합의로 열었어요.","관람할 수 있어요.","평화의 장소예요."],"asset":{"type":"passage","lines":["우리 모둠은 인터넷으로 DMZ 평화의 길을 답사했다.","누리집에서 그곳의 의미, 있었던 일, 주요 시설을 차례로 살폈다.","희귀한 새와 식물 사진이 많아 모두 놀랐다.","통일 뒤에는 이곳을 평화 생태 학습장으로 만들자고 기사에 썼다."],"title":"햇살반 역사 신문 ② 답사 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_b#3','soc',6,1,'u1','','g6_1_soc_u1_review_b','unit_review','SO6-1-u1-C5',1,'mc','auto','분단 이후 처음으로 통일 원칙에 관한 합의를 담아 발표한 것은 무엇인가요?',ARRAY['SO6-1-u1-X10','SO6-1-u1-X09']::text[],false,'{"seq":3,"concept":"SO6-1-u1-C5","difficulty":1,"kind":"mc","stem":"분단 이후 처음으로 통일 원칙에 관한 합의를 담아 발표한 것은 무엇인가요?","options":[{"t":"7·4 남북 공동 성명","correct":true},{"t":"남북 기본 합의서","mis":"SO6-1-u1-X10"},{"t":"남북 철도 연결 사업","mis":"SO6-1-u1-X09"},{"t":"단일팀 구성","mis":"SO6-1-u1-X09"}],"explanation":["처음 한 합의예요.","통일 원칙을 담았어요.","7·4 남북 공동 성명이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_b#4','soc',6,1,'u1','','g6_1_soc_u1_review_b','unit_review','SO6-1-u1-C8',1,'mc','auto','신문 ④의 ⓓ처럼 통일 퀴즈 대회를 여는 것은 어떤 실천인가요?',ARRAY['SO6-1-u1-X14','SO6-1-u1-X09']::text[],false,'{"seq":4,"concept":"SO6-1-u1-C8","difficulty":1,"kind":"mc","stem":"신문 ④의 ⓓ처럼 통일 퀴즈 대회를 여는 것은 어떤 실천인가요?","options":[{"t":"평화 통일의 의미와 중요성 알리기","correct":true},{"t":"북한 주민에게 물건 보내기","mis":"SO6-1-u1-X14"},{"t":"남북의 말을 하나로 정하기","mis":"SO6-1-u1-X14"},{"t":"철도와 도로 잇기","mis":"SO6-1-u1-X09"}],"explanation":["다른 반도 초대했어요.","여럿이 함께 알아요.","의미와 중요성을 알려요."],"asset":{"type":"passage","lines":["ⓐ 남북 음식을 골라 평화 통일 밥상을 그렸다.","ⓑ 「우리는 한민족, 언제나 함께」를 쓴 종이비행기를 날렸다.","ⓒ 알뜰 시장을 열어 모은 돈을 북한 어린이 돕기에 보냈다.","ⓓ 통일 퀴즈 대회를 열어 다른 반 친구들도 초대했다."],"title":"햇살반 역사 신문 ④ 우리 반 통일 주간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_b#5','soc',6,1,'u1','','g6_1_soc_u1_review_b','unit_review','SO6-1-u1-C9',1,'mc','auto','4·19 혁명에 참여한 사람들로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X16']::text[],false,'{"seq":5,"concept":"SO6-1-u1-C9","difficulty":1,"kind":"mc","stem":"4·19 혁명에 참여한 사람들로 알맞은 것은 어느 것인가요?","options":[{"t":"초등학생부터 대학교수까지 각계각층의 사람들","correct":true},{"t":"대학생들만","mis":"SO6-1-u1-X16"},{"t":"외국인들만","mis":"SO6-1-u1-X16"},{"t":"정부의 관리들만","mis":"SO6-1-u1-X16"}],"explanation":["학생과 시민이 나섰어요.","초등학생도 있었어요.","각계각층이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_b#6','soc',6,1,'u1','','g6_1_soc_u1_review_b','unit_review','SO6-1-u1-C11',1,'mc','auto','5·18 민주화 운동 때 광주의 일을 바깥에 알리려고 애쓴 사람들로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X19']::text[],false,'{"seq":6,"concept":"SO6-1-u1-C11","difficulty":1,"kind":"mc","stem":"5·18 민주화 운동 때 광주의 일을 바깥에 알리려고 애쓴 사람들로 알맞은 것은 어느 것인가요?","options":[{"t":"광주 시민과 외국인 기자들","correct":true},{"t":"계엄군","mis":"SO6-1-u1-X19"},{"t":"길을 막은 사람들","mis":"SO6-1-u1-X19"},{"t":"방송을 통제한 사람들","mis":"SO6-1-u1-X19"}],"explanation":["막은 쪽이 있었어요.","알리려 한 쪽도 있었어요.","시민과 기자들이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_b#7','soc',6,1,'u1','','g6_1_soc_u1_review_b','unit_review','SO6-1-u1-C13',1,'mc','auto','신문 ⑥에서 「우리 지역의 대표도 주민이 직접 뽑는다」는 것은 어떤 제도와 이어지나요?',ARRAY['SO6-1-u1-X23','SO6-1-u1-X21']::text[],false,'{"seq":7,"concept":"SO6-1-u1-C13","difficulty":1,"kind":"mc","stem":"신문 ⑥에서 「우리 지역의 대표도 주민이 직접 뽑는다」는 것은 어떤 제도와 이어지나요?","options":[{"t":"지방 자치제","correct":true},{"t":"간선제","mis":"SO6-1-u1-X23"},{"t":"정부통령 선거","mis":"SO6-1-u1-X23"},{"t":"선거인단 제도","mis":"SO6-1-u1-X21"}],"explanation":["지역 주민이 뽑아요.","지역의 일을 처리해요.","지방 자치제예요."],"asset":{"type":"passage","lines":["할머니는 대통령을 처음 직접 뽑던 날을 또렷이 기억하신다.","투표소 앞에 줄이 길게 늘어섰는데도 모두 웃는 얼굴이었다고 했다.","요즘은 우리 지역의 대표도 주민이 직접 뽑는다.","할머니는 시민 단체에서 하천 지킴이로 활동하신다."],"title":"햇살반 역사 신문 ⑥ 할머니의 투표 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_b#8','soc',6,1,'u1','','g6_1_soc_u1_review_b','unit_review','SO6-1-u1-C14',1,'mc','auto','신문 ⑦에서 할아버지가 그 뒤 일한 조선소는 어떤 공업에 속하나요?',ARRAY['SO6-1-u1-X25','SO6-1-u1-X26']::text[],false,'{"seq":8,"concept":"SO6-1-u1-C14","difficulty":1,"kind":"mc","stem":"신문 ⑦에서 할아버지가 그 뒤 일한 조선소는 어떤 공업에 속하나요?","options":[{"t":"중화학 공업","correct":true},{"t":"경공업","mis":"SO6-1-u1-X25"},{"t":"농업","mis":"SO6-1-u1-X26"},{"t":"수산업","mis":"SO6-1-u1-X26"}],"explanation":["배는 아주 무거워요.","높은 기술력이 필요해요.","중화학 공업이에요."],"asset":{"type":"passage","lines":["어릴 때 — 지원받은 밀가루로 만든 국수를 자주 드셨다.","청년 때 — 신발 공장에서 만든 신발이 배에 실려 외국으로 팔렸다.","그 뒤 — 큰 조선소에서 커다란 배를 만드는 일을 하셨다.","아빠가 어릴 때 — 우리 집에 자동차와 컬러텔레비전이 생겼다."],"title":"햇살반 역사 신문 ⑦ 할아버지의 일터"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_b#9','soc',6,1,'u1','','g6_1_soc_u1_review_b','unit_review','SO6-1-u1-C2',2,'mc','auto','분단으로 나타난 문제점을 바르게 묶은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X02','SO6-1-u1-X03']::text[],false,'{"seq":9,"concept":"SO6-1-u1-C2","difficulty":2,"kind":"mc","stem":"분단으로 나타난 문제점을 바르게 묶은 것은 어느 것인가요?","options":[{"t":"이산가족의 아픔, 커지는 언어 차이, 전쟁의 긴장감","correct":true},{"t":"이산가족의 만남, 줄어드는 언어 차이, 평화로운 분위기","mis":"SO6-1-u1-X02"},{"t":"국방비 감소, 같은 언어, 자유로운 왕래","mis":"SO6-1-u1-X03"},{"t":"산업 발달, 도시화, 대중문화","mis":"SO6-1-u1-X03"}],"explanation":["아픔이 이어져요.","말이 달라지고 있어요.","긴장감도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_b#10','soc',6,1,'u1','','g6_1_soc_u1_review_b','unit_review','SO6-1-u1-C4',2,'mc','auto','신문 ②에서 모둠이 통일 뒤 비무장 지대를 평화 생태 학습장으로 만들자고 한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X06','SO6-1-u1-X07']::text[],false,'{"seq":10,"concept":"SO6-1-u1-C4","difficulty":2,"kind":"mc","stem":"신문 ②에서 모둠이 통일 뒤 비무장 지대를 평화 생태 학습장으로 만들자고 한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"자연이 잘 보전되어 희귀한 생물을 공부하기 좋기 때문에","correct":true},{"t":"군사 훈련을 하기 좋기 때문에","mis":"SO6-1-u1-X06"},{"t":"사람이 살기에 가장 붐비는 곳이기 때문에","mis":"SO6-1-u1-X06"},{"t":"아픔을 잊게 흔적을 없애려고","mis":"SO6-1-u1-X07"}],"explanation":["희귀한 새와 식물이 있어요.","자연이 잘 남았어요.","배우기 좋은 곳이에요."],"asset":{"type":"passage","lines":["우리 모둠은 인터넷으로 DMZ 평화의 길을 답사했다.","누리집에서 그곳의 의미, 있었던 일, 주요 시설을 차례로 살폈다.","희귀한 새와 식물 사진이 많아 모두 놀랐다.","통일 뒤에는 이곳을 평화 생태 학습장으로 만들자고 기사에 썼다."],"title":"햇살반 역사 신문 ② 답사 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_b#11','soc',6,1,'u1','','g6_1_soc_u1_review_b','unit_review','SO6-1-u1-C7',2,'mc','auto','신문 ③의 ㉱처럼 남북의 철도와 도로를 다시 이으려 한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X12']::text[],false,'{"seq":11,"concept":"SO6-1-u1-C7","difficulty":2,"kind":"mc","stem":"신문 ③의 ㉱처럼 남북의 철도와 도로를 다시 이으려 한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"끊어진 길을 이어 서로 왕래하기 쉽게 하려고","correct":true},{"t":"남북을 더 멀리 떨어뜨리려고","mis":"SO6-1-u1-X12"},{"t":"한쪽만 길을 쓰게 하려고","mis":"SO6-1-u1-X12"},{"t":"바닷길을 막으려고","mis":"SO6-1-u1-X12"}],"explanation":["길이 끊어졌어요.","다시 이으려 했어요.","오가기 쉽게 하려고요."],"asset":{"type":"passage","lines":["㉮ 남북 국어학자들이 함께 만드는 사전 — 달라진 말을 모아 싣는다.","㉯ 남북 학자들의 문화유산 공동 발굴 — 고려의 궁궐터에서 했다.","㉰ 공업 단지 — 남한의 자본·기술과 북한의 노동력을 합했다.","㉱ 철도·도로 연결 — 끊어진 길을 다시 이으려 했다."],"title":"햇살반 역사 신문 ③ 남북이 함께한 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_b#12','soc',6,1,'u1','','g6_1_soc_u1_review_b','unit_review','SO6-1-u1-C8',2,'mc','auto','신문 ④의 ⓐ에서 남북 음식을 함께 골라 밥상을 그린 뜻으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X04','SO6-1-u1-X14']::text[],false,'{"seq":12,"concept":"SO6-1-u1-C8","difficulty":2,"kind":"mc","stem":"신문 ④의 ⓐ에서 남북 음식을 함께 골라 밥상을 그린 뜻으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"남과 북이 어울려 화합하는 모습을 나타내려고","correct":true},{"t":"한쪽 음식이 더 낫다고 알리려고","mis":"SO6-1-u1-X04"},{"t":"음식 값을 견주려고","mis":"SO6-1-u1-X14"},{"t":"북한 음식을 없애려고","mis":"SO6-1-u1-X04"}],"explanation":["두 곳의 음식을 모았어요.","함께 어울려요.","화합의 뜻이에요."],"asset":{"type":"passage","lines":["ⓐ 남북 음식을 골라 평화 통일 밥상을 그렸다.","ⓑ 「우리는 한민족, 언제나 함께」를 쓴 종이비행기를 날렸다.","ⓒ 알뜰 시장을 열어 모은 돈을 북한 어린이 돕기에 보냈다.","ⓓ 통일 퀴즈 대회를 열어 다른 반 친구들도 초대했다."],"title":"햇살반 역사 신문 ④ 우리 반 통일 주간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_b#13','soc',6,1,'u1','','g6_1_soc_u1_review_b','unit_review','SO6-1-u1-C11',2,'mc','auto','5·18 민주화 운동 때 계엄군이 한 일로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X19','SO6-1-u1-X24']::text[],false,'{"seq":13,"concept":"SO6-1-u1-C11","difficulty":2,"kind":"mc","stem":"5·18 민주화 운동 때 계엄군이 한 일로 알맞은 것은 어느 것인가요?","options":[{"t":"광주로 가는 길을 막고 신문과 방송을 통제했다","correct":true},{"t":"광주 소식을 세계에 알렸다","mis":"SO6-1-u1-X19"},{"t":"시민군을 만들었다","mis":"SO6-1-u1-X19"},{"t":"직선제를 시행했다","mis":"SO6-1-u1-X24"}],"explanation":["바깥과 막았어요.","알리지 못하게 했어요.","길과 방송을 막았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_b#14','soc',6,1,'u1','','g6_1_soc_u1_review_b','unit_review','SO6-1-u1-C13',2,'sa','auto','신문 ⑥의 할머니가 투표로 행사한, 국가의 중요한 일을 결정하는 권리는 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":14,"concept":"SO6-1-u1-C13","difficulty":2,"kind":"sa","stem":"신문 ⑥의 할머니가 투표로 행사한, 국가의 중요한 일을 결정하는 권리는 무엇인가요? 두 글자로 쓰세요.","answer":["주권"],"explanation":["국민이 가진 권리예요.","중요한 일을 정해요.","주권이에요."],"mis":"SO6-1-u1-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_b#15','soc',6,1,'u1','','g6_1_soc_u1_review_b','unit_review','SO6-1-u1-C15',2,'mc','auto','신문 ⑦에서 신발이 배에 실려 외국으로 팔린 것과 관계 깊은 정부의 노력은 어느 것인가요?',ARRAY['SO6-1-u1-X26','SO6-1-u1-X27']::text[],false,'{"seq":15,"concept":"SO6-1-u1-C15","difficulty":2,"kind":"mc","stem":"신문 ⑦에서 신발이 배에 실려 외국으로 팔린 것과 관계 깊은 정부의 노력은 어느 것인가요?","options":[{"t":"수출로 산업화하려는 경제 개발 계획과 항만 건설","correct":true},{"t":"농업 중심으로 되돌아가려는 계획","mis":"SO6-1-u1-X26"},{"t":"수출을 막는 정책","mis":"SO6-1-u1-X27"},{"t":"공장을 모두 닫는 정책","mis":"SO6-1-u1-X27"}],"explanation":["수출을 늘리려 했어요.","배로 실어 보낼 항만이 필요했어요.","경제 개발 계획이에요."],"asset":{"type":"passage","lines":["어릴 때 — 지원받은 밀가루로 만든 국수를 자주 드셨다.","청년 때 — 신발 공장에서 만든 신발이 배에 실려 외국으로 팔렸다.","그 뒤 — 큰 조선소에서 커다란 배를 만드는 일을 하셨다.","아빠가 어릴 때 — 우리 집에 자동차와 컬러텔레비전이 생겼다."],"title":"햇살반 역사 신문 ⑦ 할아버지의 일터"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_b#16','soc',6,1,'u1','','g6_1_soc_u1_review_b','unit_review','SO6-1-u1-C16',2,'mc','auto','신문 ⑧에서 할머니가 고향에 하루 만에 다녀올 수 있게 된 까닭은 무엇인가요?',ARRAY['SO6-1-u1-X28']::text[],false,'{"seq":16,"concept":"SO6-1-u1-C16","difficulty":2,"kind":"mc","stem":"신문 ⑧에서 할머니가 고향에 하루 만에 다녀올 수 있게 된 까닭은 무엇인가요?","options":[{"t":"고속 국도가 생겨 이동 시간이 크게 줄었기 때문에","correct":true},{"t":"고향이 도시로 옮겨 왔기 때문에","mis":"SO6-1-u1-X28"},{"t":"기차가 모두 없어졌기 때문에","mis":"SO6-1-u1-X28"},{"t":"대중 매체가 보급되었기 때문에","mis":"SO6-1-u1-X28"}],"explanation":["길이 빨라졌어요.","이동 시간이 줄었어요.","일일생활권이 되었어요."],"asset":{"type":"passage","lines":["할머니는 시골에서 도시로 이사 와 언덕 위 동네에 사셨다.","고속 국도가 생기자 고향에 하루 만에 다녀올 수 있었다.","공장 언니들은 밤늦게까지 일하고 쉬는 날이 적었다.","일하는 사람의 권리를 지키자는 목소리가 점점 커졌다.","우리 반은 이 이야기로 숨은 글씨 그림도 그렸다."],"title":"햇살반 역사 신문 ⑧ 도시로 온 할머니"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_b#17','soc',6,1,'u1','','g6_1_soc_u1_review_b','unit_review','SO6-1-u1-C2',3,'error','auto','신문 ①을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u1-X04','SO6-1-u1-X02']::text[],false,'{"seq":17,"concept":"SO6-1-u1-C2","difficulty":3,"kind":"error","stem":"신문 ①을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「분단의 아픔은 남쪽 사람들만 겪는 거야.」","correct":true,"mis_target":"SO6-1-u1-X04"},{"t":"친구 가 — 「할아버지는 실향민이면서 이산가족이셔.」","mis":"SO6-1-u1-X02"},{"t":"친구 나 — 「그쪽 사람들도 가족을 그리워할 거야.」","mis":"SO6-1-u1-X04"}],"explanation":["남북 모두 아파요.","할아버지 말씀을 떠올려요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["우리 반은 이웃에 사시는 실향민 할아버지를 찾아가 이야기를 들었다.","할아버지의 고향은 휴전선 너머라 명절마다 고향 쪽을 바라보신다고 했다.","북쪽에 남은 동생을 지금도 만나지 못하셨다.","「그쪽 사람들도 우리처럼 가족을 그리워하겠지.」 하고 말씀하셨다."],"title":"햇살반 역사 신문 ① 할아버지의 고향"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_b#18','soc',6,1,'u1','','g6_1_soc_u1_review_b','unit_review','SO6-1-u1-C7',3,'error','auto','남북 협력을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u1-X12']::text[],false,'{"seq":18,"concept":"SO6-1-u1-C7","difficulty":3,"kind":"error","stem":"남북 협력을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「협력은 한쪽이 다른 쪽을 일방적으로 도와주는 거야.」","correct":true,"mis_target":"SO6-1-u1-X12"},{"t":"친구 나 — 「공업 단지는 두 몫을 합해야 이루어졌어.」","mis":"SO6-1-u1-X12"},{"t":"친구 다 — 「장점을 합하면 더 큰 이익을 만들 수 있어.」","mis":"SO6-1-u1-X12"}],"explanation":["협력은 함께해요.","두 몫이 나란히 있어요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_b#19','soc',6,1,'u1','','g6_1_soc_u1_review_b','unit_review','SO6-1-u1-C11',3,'error','auto','민주화 운동을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u1-X24','SO6-1-u1-X15','SO6-1-u1-X22']::text[],false,'{"seq":19,"concept":"SO6-1-u1-C11","difficulty":3,"kind":"error","stem":"민주화 운동을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「5·18 민주화 운동은 3·15 부정 선거 때문에 일어났어.」","correct":true,"mis_target":"SO6-1-u1-X24"},{"t":"친구 가 — 「4·19 혁명은 3·15 부정 선거가 원인이야.」","mis":"SO6-1-u1-X15"},{"t":"친구 다 — 「6월 민주 항쟁에서는 직선제를 요구했어.」","mis":"SO6-1-u1-X22"}],"explanation":["부정 선거는 4·19의 원인이에요.","5·18은 군인들의 권력 장악이 원인이에요.","친구 나가 섞었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_b#20','soc',6,1,'u1','','g6_1_soc_u1_review_b','unit_review','SO6-1-u1-C10',3,'mc','auto','4·19 혁명이 「민주주의 발전의 밑거름」이라고 불리는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X17']::text[],false,'{"seq":20,"concept":"SO6-1-u1-C10","difficulty":3,"kind":"mc","stem":"4·19 혁명이 「민주주의 발전의 밑거름」이라고 불리는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"시민과 학생의 힘으로 민주적 절차를 무시한 정권을 무너뜨렸기 때문에","correct":true},{"t":"군인들이 새 정부를 세웠기 때문에","mis":"SO6-1-u1-X17"},{"t":"부정 선거 결과가 인정되었기 때문에","mis":"SO6-1-u1-X17"},{"t":"대통령이 더 오래 집권했기 때문에","mis":"SO6-1-u1-X17"}],"explanation":["시민과 학생이 해냈어요.","절차를 무시한 정권이 물러났어요.","민주주의의 밑거름이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_b#21','soc',6,1,'u1','','g6_1_soc_u1_review_b','unit_review','SO6-1-u1-C15',3,'error','auto','산업화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u1-X27']::text[],false,'{"seq":21,"concept":"SO6-1-u1-C15","difficulty":3,"kind":"error","stem":"산업화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「산업화는 정부 혼자 이룬 거라 일하던 사람들은 관계없어.」","correct":true,"mis_target":"SO6-1-u1-X27"},{"t":"친구 나 — 「기업은 세계와 경쟁하려고 기술을 개발했어.」","mis":"SO6-1-u1-X27"},{"t":"친구 다 — 「독일로 간 광부와 간호사의 외화도 밑거름이 되었어.」","mis":"SO6-1-u1-X27"}],"explanation":["정부도 노력했어요.","근로자와 기업도 노력했어요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_b#22','soc',6,1,'u1','','g6_1_soc_u1_review_b','unit_review','SO6-1-u1-C18',3,'mc','auto','신문 ⑧의 이야기로 숨은 글씨 그림을 그릴 때 「권리」라는 글씨를 숨기기에 알맞은 장면은 어느 것인가요?',ARRAY['SO6-1-u1-X32']::text[],false,'{"seq":22,"concept":"SO6-1-u1-C18","difficulty":3,"kind":"mc","stem":"신문 ⑧의 이야기로 숨은 글씨 그림을 그릴 때 「권리」라는 글씨를 숨기기에 알맞은 장면은 어느 것인가요?","options":[{"t":"일하는 사람들이 나란히 서서 근무 시간을 줄여 달라고 말하는 모습","correct":true},{"t":"바닷가에서 물놀이하는 모습","mis":"SO6-1-u1-X32"},{"t":"남북 선수가 함께 입장하는 모습","mis":"SO6-1-u1-X32"},{"t":"아무 장면이나 마음대로","mis":"SO6-1-u1-X32"}],"explanation":["권리와 이어지는 장면이에요.","일하는 사람들이 나섰어요.","그 모습에 글씨를 숨겨요."],"asset":{"type":"passage","lines":["할머니는 시골에서 도시로 이사 와 언덕 위 동네에 사셨다.","고속 국도가 생기자 고향에 하루 만에 다녀올 수 있었다.","공장 언니들은 밤늦게까지 일하고 쉬는 날이 적었다.","일하는 사람의 권리를 지키자는 목소리가 점점 커졌다.","우리 반은 이 이야기로 숨은 글씨 그림도 그렸다."],"title":"햇살반 역사 신문 ⑧ 도시로 온 할머니"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_b#23','soc',6,1,'u1','','g6_1_soc_u1_review_b','unit_review','SO6-1-u1-C8',4,'mc','auto','신문 ①~④를 함께 볼 때 평화 통일에 다가가는 길로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X13','SO6-1-u1-X04','SO6-1-u1-X12']::text[],false,'{"seq":23,"concept":"SO6-1-u1-C8","difficulty":4,"kind":"mc","stem":"신문 ①~④를 함께 볼 때 평화 통일에 다가가는 길로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"분단의 아픔을 이해하고, 나라의 협력과 우리의 작은 실천을 함께 이어 간다","correct":true},{"t":"아픔은 잊고 나라에만 맡긴다","mis":"SO6-1-u1-X13"},{"t":"북한을 이기는 방법만 찾는다","mis":"SO6-1-u1-X04"},{"t":"협력은 하지 않고 각자 지낸다","mis":"SO6-1-u1-X12"}],"explanation":["①은 아픔이에요.","③은 나라의 협력이에요.","④는 우리의 실천이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_b#24','soc',6,1,'u1','','g6_1_soc_u1_review_b','unit_review','SO6-1-u1-C9',4,'essay','teacher','신문 ⑤의 세 민주화 운동 가운데 하나를 골라 원인과 결과를 쓰고, 그 사건이 우리나라 민주주의에 준 의의를 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO6-1-u1-C9","difficulty":4,"kind":"essay","stem":"신문 ⑤의 세 민주화 운동 가운데 하나를 골라 원인과 결과를 쓰고, 그 사건이 우리나라 민주주의에 준 의의를 쓰세요.","answer_guide":{"answer":"예: 4·19 혁명은 이승만 정부가 계속 집권하려고 3·15 부정 선거를 벌인 것이 원인이다. 각계각층의 사람들이 시위에 나서 결국 대통령이 물러나고 부정 선거는 무효가 되었다. 시민과 학생의 힘으로 민주적 절차를 무시한 정권을 무너뜨려 우리나라 민주주의 발전의 밑거름이 되었다.","scoring_points":["사건을 하나 골랐는가","원인과 결과를 바르게 썼는가","민주주의에 준 의의를 썼는가"]},"explanation":["사건을 골라요.","원인 → 결과를 이어요.","의의를 써요."],"asset":{"type":"passage","lines":["4·19 혁명 — 3·15 부정 선거 → 각계각층의 시위 → 대통령이 물러남","5·18 민주화 운동 — 군인들의 권력 장악 → 광주 시민의 민주화 요구","6월 민주 항쟁 — 독재와 간선제 유지 → 전국의 직선제 요구 → 직선제","세 사건 모두 시민이 민주주의를 지키려고 나선 일이다."],"title":"햇살반 역사 신문 ⑤ 민주화 흐름 코너"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_b#25','soc',6,1,'u1','','g6_1_soc_u1_review_b','unit_review','SO6-1-u1-C8',4,'essay','teacher','신문 ④처럼 우리 반이 통일 주간에 할 실천을 하나 정해 차례대로 쓰고, 그 실천이 평화 통일을 위해 할 수 있는 일 가운데 무엇에 해당하는지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO6-1-u1-C8","difficulty":4,"kind":"essay","stem":"신문 ④처럼 우리 반이 통일 주간에 할 실천을 하나 정해 차례대로 쓰고, 그 실천이 평화 통일을 위해 할 수 있는 일 가운데 무엇에 해당하는지 쓰세요.","answer_guide":{"answer":"예: 우리 반은 북한 문화유산 알아보기 행사를 열겠다. 먼저 모둠별로 북한의 문화유산을 하나씩 조사하고, 조사한 내용을 그림과 글로 정리해 복도에 전시한 뒤, 다른 반 친구들을 초대해 설명해 주겠다. 이 실천은 평화 통일의 의미와 중요성을 알리는 일에 해당한다.","scoring_points":["실천을 하나 정했는가","차례대로 썼는가","네 가지 일 가운데 무엇인지 썼는가"]},"explanation":["실천을 정해요.","차례대로 써요.","인식·마음·돕기·알리기 가운데 골라요."],"asset":{"type":"passage","lines":["ⓐ 남북 음식을 골라 평화 통일 밥상을 그렸다.","ⓑ 「우리는 한민족, 언제나 함께」를 쓴 종이비행기를 날렸다.","ⓒ 알뜰 시장을 열어 모은 돈을 북한 어린이 돕기에 보냈다.","ⓓ 통일 퀴즈 대회를 열어 다른 반 친구들도 초대했다."],"title":"햇살반 역사 신문 ④ 우리 반 통일 주간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_c#1','soc',6,1,'u1','','g6_1_soc_u1_review_c','unit_review','SO6-1-u1-C2',1,'ox','auto','신문 ①의 할아버지가 북쪽의 동생을 만나지 못하는 것은 분단으로 생긴 이산가족의 아픔이에요.',ARRAY['SO6-1-u1-X02']::text[],false,'{"seq":1,"concept":"SO6-1-u1-C2","difficulty":1,"kind":"ox","stem":"신문 ①의 할아버지가 북쪽의 동생을 만나지 못하는 것은 분단으로 생긴 이산가족의 아픔이에요.","answer":"O","reason_options":[{"t":"분단 때문에 가족이 자유롭게 오갈 수 없기 때문에","correct":true},{"t":"가족이 일부러 만나지 않기로 했기 때문에","mis":"SO6-1-u1-X02"}],"mis":"SO6-1-u1-X02","explanation":["동생이 북쪽에 있어요.","오갈 수 없어요.","이산가족의 아픔이에요."],"asset":{"type":"passage","lines":["우리 반은 이웃에 사시는 실향민 할아버지를 찾아가 이야기를 들었다.","할아버지의 고향은 휴전선 너머라 명절마다 고향 쪽을 바라보신다고 했다.","북쪽에 남은 동생을 지금도 만나지 못하셨다.","「그쪽 사람들도 우리처럼 가족을 그리워하겠지.」 하고 말씀하셨다."],"title":"햇살반 역사 신문 ① 할아버지의 고향"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_c#2','soc',6,1,'u1','','g6_1_soc_u1_review_c','unit_review','SO6-1-u1-C3',1,'sa','auto','전쟁 뒤 한반도를 가로지르며 설치된 선을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-1-u1-C3","difficulty":1,"kind":"sa","stem":"전쟁 뒤 한반도를 가로지르며 설치된 선을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["휴전선"],"explanation":["한반도를 가로질러요.","전쟁 뒤에 생겼어요.","휴전선이에요."],"mis":"SO6-1-u1-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_c#3','soc',6,1,'u1','','g6_1_soc_u1_review_c','unit_review','SO6-1-u1-C7',1,'sa','auto','신문 ③의 ㉰에서 남한의 자본·기술과 합해진 북한의 몫을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO6-1-u1-C7","difficulty":1,"kind":"sa","stem":"신문 ③의 ㉰에서 남한의 자본·기술과 합해진 북한의 몫을 쓰세요.","answer":["노동력"],"explanation":["일하는 사람의 힘이에요.","◯◯력이에요.","노동력이에요."],"mis":"SO6-1-u1-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_c#4','soc',6,1,'u1','','g6_1_soc_u1_review_c','unit_review','SO6-1-u1-C8',1,'sa','auto','평화 통일 뮤직비디오에 노래를 쓸 때 밝혀야 하는 것은 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SO6-1-u1-C8","difficulty":1,"kind":"sa","stem":"평화 통일 뮤직비디오에 노래를 쓸 때 밝혀야 하는 것은 무엇인가요? 두 글자로 쓰세요.","answer":["출처"],"explanation":["남이 만든 노래예요.","어디서 왔는지 밝혀요.","출처예요."],"mis":"SO6-1-u1-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_c#5','soc',6,1,'u1','','g6_1_soc_u1_review_c','unit_review','SO6-1-u1-C10',1,'sa','auto','4·19 혁명은 우리나라 무엇의 발전에 밑거름이 되었나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"SO6-1-u1-C10","difficulty":1,"kind":"sa","stem":"4·19 혁명은 우리나라 무엇의 발전에 밑거름이 되었나요? 네 글자로 쓰세요.","answer":["민주주의"],"explanation":["국민이 주인이에요.","바른 선거가 바탕이에요.","민주주의예요."],"mis":"SO6-1-u1-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_c#6','soc',6,1,'u1','','g6_1_soc_u1_review_c','unit_review','SO6-1-u1-C11',1,'sa','auto','법에 맞지 않는 방법으로 일어난 정치적인 변화를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"SO6-1-u1-C11","difficulty":1,"kind":"sa","stem":"법에 맞지 않는 방법으로 일어난 정치적인 변화를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["정변"],"explanation":["법에 맞지 않아요.","정치가 바뀌어요.","정변이에요."],"mis":"SO6-1-u1-X18"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_c#7','soc',6,1,'u1','','g6_1_soc_u1_review_c','unit_review','SO6-1-u1-C12',1,'sa','auto','일정 수의 선거인단이 대표를 뽑는 선거 제도를 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"SO6-1-u1-C12","difficulty":1,"kind":"sa","stem":"일정 수의 선거인단이 대표를 뽑는 선거 제도를 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["간선제"],"explanation":["선거인단이 뽑아요.","◯선제예요.","간선제예요."],"mis":"SO6-1-u1-X21"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_c#8','soc',6,1,'u1','','g6_1_soc_u1_review_c','unit_review','SO6-1-u1-C16',1,'sa','auto','신문 ⑧처럼 하루 동안 볼일을 끝내고 되돌아올 수 있는 거리의 범위를 무엇이라고 하나요? 다섯 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO6-1-u1-C16","difficulty":1,"kind":"sa","stem":"신문 ⑧처럼 하루 동안 볼일을 끝내고 되돌아올 수 있는 거리의 범위를 무엇이라고 하나요? 다섯 글자로 쓰세요.","answer":["일일생활권","일일 생활권"],"explanation":["하루 안에 다녀와요.","고속 국도 덕분이에요.","일일생활권이에요."],"mis":"SO6-1-u1-X28"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_c#9','soc',6,1,'u1','','g6_1_soc_u1_review_c','unit_review','SO6-1-u1-C2',2,'ox','auto','분단 비용에는 가족을 만나지 못하는 아픔처럼 돈으로 셀 수 없는 것도 들어가요.',ARRAY['SO6-1-u1-X03']::text[],false,'{"seq":9,"concept":"SO6-1-u1-C2","difficulty":2,"kind":"ox","stem":"분단 비용에는 가족을 만나지 못하는 아픔처럼 돈으로 셀 수 없는 것도 들어가요.","answer":"O","reason_options":[{"t":"분단 비용은 군대 비용뿐 아니라 아픔과 약해진 국력까지 여러 갈래이기 때문에","correct":true},{"t":"분단 비용은 국방비 하나뿐이기 때문에","mis":"SO6-1-u1-X03"}],"mis":"SO6-1-u1-X03","explanation":["여러 갈래가 있어요.","돈으로 다 셀 수 없어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_c#10','soc',6,1,'u1','','g6_1_soc_u1_review_c','unit_review','SO6-1-u1-C4',2,'ox','auto','판문점은 정전 협정을 맺고 남북 정상이 만난 곳이라 분단과 평화의 뜻이 함께 담겨 있어요.',ARRAY['SO6-1-u1-X05']::text[],false,'{"seq":10,"concept":"SO6-1-u1-C4","difficulty":2,"kind":"ox","stem":"판문점은 정전 협정을 맺고 남북 정상이 만난 곳이라 분단과 평화의 뜻이 함께 담겨 있어요.","answer":"O","reason_options":[{"t":"분단의 역사와 평화를 위한 만남이 모두 그곳에서 있었기 때문에","correct":true},{"t":"판문점은 전쟁과 관계없는 놀이 장소이기 때문에","mis":"SO6-1-u1-X05"}],"mis":"SO6-1-u1-X05","explanation":["정전 협정을 맺었어요.","정상이 만났어요.","두 뜻이 함께 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_c#11','soc',6,1,'u1','','g6_1_soc_u1_review_c','unit_review','SO6-1-u1-C7',2,'ox','auto','신문 ③의 ㉰에서 남한은 노동력을, 북한은 자본과 기술을 내놓았어요.',ARRAY['SO6-1-u1-X11']::text[],false,'{"seq":11,"concept":"SO6-1-u1-C7","difficulty":2,"kind":"ox","stem":"신문 ③의 ㉰에서 남한은 노동력을, 북한은 자본과 기술을 내놓았어요.","answer":"X","reason_options":[{"t":"남한이 자본과 기술을, 북한이 노동력을 내놓았기 때문에","correct":true},{"t":"공업 단지는 한쪽이 모든 것을 내놓았기 때문에","mis":"SO6-1-u1-X11"}],"mis":"SO6-1-u1-X11","explanation":["두 몫을 바꾸었어요.","남한은 자본과 기술이에요.","그래서 X예요."],"asset":{"type":"passage","lines":["㉮ 남북 국어학자들이 함께 만드는 사전 — 달라진 말을 모아 싣는다.","㉯ 남북 학자들의 문화유산 공동 발굴 — 고려의 궁궐터에서 했다.","㉰ 공업 단지 — 남한의 자본·기술과 북한의 노동력을 합했다.","㉱ 철도·도로 연결 — 끊어진 길을 다시 이으려 했다."],"title":"햇살반 역사 신문 ③ 남북이 함께한 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_c#12','soc',6,1,'u1','','g6_1_soc_u1_review_c','unit_review','SO6-1-u1-C8',2,'ox','auto','신문 ④의 네 활동은 방법이 서로 달라도 모두 평화 통일을 위한 실천이에요.',ARRAY['SO6-1-u1-X14']::text[],false,'{"seq":12,"concept":"SO6-1-u1-C8","difficulty":2,"kind":"ox","stem":"신문 ④의 네 활동은 방법이 서로 달라도 모두 평화 통일을 위한 실천이에요.","answer":"O","reason_options":[{"t":"방법은 달라도 평화 통일을 바라고 돕고 알리는 같은 목표로 모이기 때문에","correct":true},{"t":"실천은 정해진 한 가지 방법만 있기 때문에","mis":"SO6-1-u1-X14"}],"mis":"SO6-1-u1-X14","explanation":["방법은 달라요.","목표는 같아요.","그래서 O예요."],"asset":{"type":"passage","lines":["ⓐ 남북 음식을 골라 평화 통일 밥상을 그렸다.","ⓑ 「우리는 한민족, 언제나 함께」를 쓴 종이비행기를 날렸다.","ⓒ 알뜰 시장을 열어 모은 돈을 북한 어린이 돕기에 보냈다.","ⓓ 통일 퀴즈 대회를 열어 다른 반 친구들도 초대했다."],"title":"햇살반 역사 신문 ④ 우리 반 통일 주간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_c#13','soc',6,1,'u1','','g6_1_soc_u1_review_c','unit_review','SO6-1-u1-C12',2,'ox','auto','6월 민주 항쟁 때 정부는 시민들의 직선제 요구를 처음부터 바로 받아들였어요.',ARRAY['SO6-1-u1-X22']::text[],false,'{"seq":13,"concept":"SO6-1-u1-C12","difficulty":2,"kind":"ox","stem":"6월 민주 항쟁 때 정부는 시민들의 직선제 요구를 처음부터 바로 받아들였어요.","answer":"X","reason_options":[{"t":"정부는 처음에 거부했고, 시위가 전국으로 퍼진 뒤에야 받아들였기 때문에","correct":true},{"t":"시민들은 직선제를 요구하지 않았기 때문에","mis":"SO6-1-u1-X22"}],"mis":"SO6-1-u1-X22","explanation":["처음에는 거부했어요.","시위가 전국으로 퍼졌어요.","그 뒤 받아들였어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_c#14','soc',6,1,'u1','','g6_1_soc_u1_review_c','unit_review','SO6-1-u1-C13',2,'ox','auto','6월 민주 항쟁 뒤 시민의 영향력이 커지고 민주주의가 더욱 발전했어요.',ARRAY['SO6-1-u1-X23']::text[],false,'{"seq":14,"concept":"SO6-1-u1-C13","difficulty":2,"kind":"ox","stem":"6월 민주 항쟁 뒤 시민의 영향력이 커지고 민주주의가 더욱 발전했어요.","answer":"O","reason_options":[{"t":"직선제·지방 자치제가 자리 잡고 시민 참여가 늘었기 때문에","correct":true},{"t":"6월 민주 항쟁 뒤 선거가 없어졌기 때문에","mis":"SO6-1-u1-X23"}],"mis":"SO6-1-u1-X23","explanation":["제도가 생겼어요.","참여가 늘었어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_c#15','soc',6,1,'u1','','g6_1_soc_u1_review_c','unit_review','SO6-1-u1-C14',2,'ox','auto','할아버지가 신발 공장에서 일하다 조선소로 옮긴 것은 우리나라 산업의 중심이 경공업에서 중화학 공업으로 옮겨 간 흐름과 맞아요.',ARRAY['SO6-1-u1-X26']::text[],false,'{"seq":15,"concept":"SO6-1-u1-C14","difficulty":2,"kind":"ox","stem":"할아버지가 신발 공장에서 일하다 조선소로 옮긴 것은 우리나라 산업의 중심이 경공업에서 중화학 공업으로 옮겨 간 흐름과 맞아요.","answer":"O","reason_options":[{"t":"1960년대 경공업에 이어 1970년대에 중화학 공업이 발달했기 때문에","correct":true},{"t":"중화학 공업이 경공업보다 먼저 발달했기 때문에","mis":"SO6-1-u1-X26"}],"mis":"SO6-1-u1-X26","explanation":["신발은 경공업이에요.","배는 중화학 공업이에요.","흐름과 맞아요."],"asset":{"type":"passage","lines":["어릴 때 — 지원받은 밀가루로 만든 국수를 자주 드셨다.","청년 때 — 신발 공장에서 만든 신발이 배에 실려 외국으로 팔렸다.","그 뒤 — 큰 조선소에서 커다란 배를 만드는 일을 하셨다.","아빠가 어릴 때 — 우리 집에 자동차와 컬러텔레비전이 생겼다."],"title":"햇살반 역사 신문 ⑦ 할아버지의 일터"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_c#16','soc',6,1,'u1','','g6_1_soc_u1_review_c','unit_review','SO6-1-u1-C17',2,'ox','auto','신문 ⑧의 공장 언니들처럼 산업화 시기 근로자들은 오랜 시간 일하고 낮은 임금을 받기도 했어요.',ARRAY['SO6-1-u1-X30']::text[],false,'{"seq":16,"concept":"SO6-1-u1-C17","difficulty":2,"kind":"ox","stem":"신문 ⑧의 공장 언니들처럼 산업화 시기 근로자들은 오랜 시간 일하고 낮은 임금을 받기도 했어요.","answer":"O","reason_options":[{"t":"수출품 가격을 낮추려고 근로자의 임금을 낮게 유지했기 때문에","correct":true},{"t":"근로자들이 스스로 오래 일하기를 원했기 때문에","mis":"SO6-1-u1-X30"}],"mis":"SO6-1-u1-X30","explanation":["밤늦게까지 일했어요.","쉬는 날도 적었어요.","그래서 O예요."],"asset":{"type":"passage","lines":["할머니는 시골에서 도시로 이사 와 언덕 위 동네에 사셨다.","고속 국도가 생기자 고향에 하루 만에 다녀올 수 있었다.","공장 언니들은 밤늦게까지 일하고 쉬는 날이 적었다.","일하는 사람의 권리를 지키자는 목소리가 점점 커졌다.","우리 반은 이 이야기로 숨은 글씨 그림도 그렸다."],"title":"햇살반 역사 신문 ⑧ 도시로 온 할머니"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_c#17','soc',6,1,'u1','','g6_1_soc_u1_review_c','unit_review','SO6-1-u1-C3',3,'mc','auto','휴전선과 아바이 마을, 실향민 할아버지 이야기를 함께 묶을 수 있는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X05']::text[],false,'{"seq":17,"concept":"SO6-1-u1-C3","difficulty":3,"kind":"mc","stem":"휴전선과 아바이 마을, 실향민 할아버지 이야기를 함께 묶을 수 있는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"모두 분단 때문에 생긴 아픔과 이어져 있다","correct":true},{"t":"모두 산업화로 생긴 일이다","mis":"SO6-1-u1-X05"},{"t":"모두 민주화 운동과 관계있다","mis":"SO6-1-u1-X05"},{"t":"모두 분단과 상관없는 관광지다","mis":"SO6-1-u1-X05"}],"explanation":["선이 길을 막았어요.","돌아가지 못한 사람들이에요.","분단의 아픔이에요."],"asset":{"type":"passage","lines":["우리 반은 이웃에 사시는 실향민 할아버지를 찾아가 이야기를 들었다.","할아버지의 고향은 휴전선 너머라 명절마다 고향 쪽을 바라보신다고 했다.","북쪽에 남은 동생을 지금도 만나지 못하셨다.","「그쪽 사람들도 우리처럼 가족을 그리워하겠지.」 하고 말씀하셨다."],"title":"햇살반 역사 신문 ① 할아버지의 고향"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_c#18','soc',6,1,'u1','','g6_1_soc_u1_review_c','unit_review','SO6-1-u1-C5',3,'mc','auto','7·4 남북 공동 성명과 남북 기본 합의서를 바르게 견준 것은 어느 것인가요?',ARRAY['SO6-1-u1-X10','SO6-1-u1-X09']::text[],false,'{"seq":18,"concept":"SO6-1-u1-C5","difficulty":3,"kind":"mc","stem":"7·4 남북 공동 성명과 남북 기본 합의서를 바르게 견준 것은 어느 것인가요?","options":[{"t":"공동 성명은 처음 통일 원칙에 합의했고, 기본 합의서는 화해·교류와 협력을 담았다","correct":true},{"t":"공동 성명은 화해·교류를 담았고, 기본 합의서는 처음 통일 원칙에 합의했다","mis":"SO6-1-u1-X10"},{"t":"둘은 이름만 다르고 내용이 같다","mis":"SO6-1-u1-X10"},{"t":"둘 다 경제 협력 사업이다","mis":"SO6-1-u1-X09"}],"explanation":["공동 성명이 먼저예요.","처음 통일 원칙이에요.","기본 합의서는 화해와 협력이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_c#19','soc',6,1,'u1','','g6_1_soc_u1_review_c','unit_review','SO6-1-u1-C10',3,'mc','auto','세 민주화 운동에 공통으로 담긴 뜻으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X17','SO6-1-u1-X18','SO6-1-u1-X22']::text[],false,'{"seq":19,"concept":"SO6-1-u1-C10","difficulty":3,"kind":"mc","stem":"세 민주화 운동에 공통으로 담긴 뜻으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"시민들이 힘을 모아 민주주의를 지키고 발전시키려 했다","correct":true},{"t":"시민들이 정부를 무조건 따르려 했다","mis":"SO6-1-u1-X17"},{"t":"군인들이 나라를 이끌기를 바랐다","mis":"SO6-1-u1-X18"},{"t":"선거를 없애려 했다","mis":"SO6-1-u1-X22"}],"explanation":["시민이 나섰어요.","민주주의를 지키려 했어요.","그것이 공통점이에요."],"asset":{"type":"passage","lines":["4·19 혁명 — 3·15 부정 선거 → 각계각층의 시위 → 대통령이 물러남","5·18 민주화 운동 — 군인들의 권력 장악 → 광주 시민의 민주화 요구","6월 민주 항쟁 — 독재와 간선제 유지 → 전국의 직선제 요구 → 직선제","세 사건 모두 시민이 민주주의를 지키려고 나선 일이다."],"title":"햇살반 역사 신문 ⑤ 민주화 흐름 코너"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_c#20','soc',6,1,'u1','','g6_1_soc_u1_review_c','unit_review','SO6-1-u1-C13',3,'error','auto','6월 민주 항쟁의 결과를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u1-X23']::text[],false,'{"seq":20,"concept":"SO6-1-u1-C13","difficulty":3,"kind":"error","stem":"6월 민주 항쟁의 결과를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「6월 민주 항쟁 뒤에는 시민이 사회문제에 참여할 길이 막혔어.」","correct":true,"mis_target":"SO6-1-u1-X23"},{"t":"친구 가 — 「국민이 직접 대통령을 뽑게 되었어.」","mis":"SO6-1-u1-X23"},{"t":"친구 나 — 「지역 대표도 주민이 뽑게 되었어.」","mis":"SO6-1-u1-X23"}],"explanation":["시민 참여는 넓어졌어요.","시민 단체가 늘었어요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["할머니는 대통령을 처음 직접 뽑던 날을 또렷이 기억하신다.","투표소 앞에 줄이 길게 늘어섰는데도 모두 웃는 얼굴이었다고 했다.","요즘은 우리 지역의 대표도 주민이 직접 뽑는다.","할머니는 시민 단체에서 하천 지킴이로 활동하신다."],"title":"햇살반 역사 신문 ⑥ 할머니의 투표 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_c#21','soc',6,1,'u1','','g6_1_soc_u1_review_c','unit_review','SO6-1-u1-C15',3,'mc','auto','1970년대 정부가 교육 시설과 연구소를 세운 것이 중화학 공업 발달에 필요했던 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X25','SO6-1-u1-X27']::text[],false,'{"seq":21,"concept":"SO6-1-u1-C15","difficulty":3,"kind":"mc","stem":"1970년대 정부가 교육 시설과 연구소를 세운 것이 중화학 공업 발달에 필요했던 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"중화학 공업은 높은 기술력이 필요하기 때문에","correct":true},{"t":"중화학 공업은 손으로만 만드는 공업이기 때문에","mis":"SO6-1-u1-X25"},{"t":"중화학 공업은 가벼운 물건만 만들기 때문에","mis":"SO6-1-u1-X25"},{"t":"연구소가 있으면 수출을 안 해도 되기 때문에","mis":"SO6-1-u1-X27"}],"explanation":["무겁고 복잡한 물건이에요.","기술이 필요해요.","그래서 사람을 길렀어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_c#22','soc',6,1,'u1','','g6_1_soc_u1_review_c','unit_review','SO6-1-u1-C18',3,'error','auto','신문 ⑧로 숨은 글씨 그림을 그리며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u1-X32']::text[],false,'{"seq":22,"concept":"SO6-1-u1-C18","difficulty":3,"kind":"error","stem":"신문 ⑧로 숨은 글씨 그림을 그리며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「숨긴 글씨는 다른 부분보다 흐리게 칠해야 해.」","correct":true,"mis_target":"SO6-1-u1-X32"},{"t":"친구 나 — 「사건과 이어지는 낱말을 골라야 해.」","mis":"SO6-1-u1-X32"},{"t":"친구 다 — 「장면의 획이 글씨의 획이 되게 그려.」","mis":"SO6-1-u1-X32"}],"explanation":["숨긴 글씨는 진하게 해요.","찾을 수 있어야 해요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_c#23','soc',6,1,'u1','','g6_1_soc_u1_review_c','unit_review','SO6-1-u1-C12',4,'mc','auto','신문 ⑤와 ⑥을 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X22','SO6-1-u1-X23']::text[],false,'{"seq":23,"concept":"SO6-1-u1-C12","difficulty":4,"kind":"mc","stem":"신문 ⑤와 ⑥을 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"시민들이 민주주의를 지키려고 나선 노력이 이어져 오늘날 직접 선거와 시민 참여가 자리 잡았다","correct":true},{"t":"민주주의는 정부가 처음부터 모두 마련해 주었다","mis":"SO6-1-u1-X22"},{"t":"세 사건은 오늘날 우리 생활과 관계없다","mis":"SO6-1-u1-X23"},{"t":"시민 참여는 6월 민주 항쟁 뒤 오히려 줄었다","mis":"SO6-1-u1-X23"}],"explanation":["⑤는 시민의 노력이에요.","⑥은 오늘의 모습이에요.","노력이 이어져 왔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_c#24','soc',6,1,'u1','','g6_1_soc_u1_review_c','unit_review','SO6-1-u1-C13',4,'essay','teacher','신문 ⑥을 보고 6월 민주 항쟁으로 달라진 모습 세 가지를 쓰고, 그 가운데 하나가 오늘날 우리 생활에 어떻게 이어지는지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO6-1-u1-C13","difficulty":4,"kind":"essay","stem":"신문 ⑥을 보고 6월 민주 항쟁으로 달라진 모습 세 가지를 쓰고, 그 가운데 하나가 오늘날 우리 생활에 어떻게 이어지는지 쓰세요.","answer_guide":{"answer":"예: 6월 민주 항쟁으로 국민이 직접 대통령을 뽑는 직선제가 시행되었고, 지역 주민이 뽑은 대표가 지역 일을 처리하는 지방 자치제가 다시 시행되었으며, 시민 단체를 통한 시민 참여가 늘었다. 지방 자치제 덕분에 오늘날 우리 동네의 대표도 주민이 직접 뽑아 지역의 일을 주민의 뜻에 맞게 처리한다.","scoring_points":["달라진 모습 세 가지를 썼는가","하나를 골랐는가","오늘날 생활과 이어 썼는가"]},"explanation":["직선제·지방 자치제·시민 참여예요.","하나를 골라요.","오늘의 생활과 이어요."],"asset":{"type":"passage","lines":["할머니는 대통령을 처음 직접 뽑던 날을 또렷이 기억하신다.","투표소 앞에 줄이 길게 늘어섰는데도 모두 웃는 얼굴이었다고 했다.","요즘은 우리 지역의 대표도 주민이 직접 뽑는다.","할머니는 시민 단체에서 하천 지킴이로 활동하신다."],"title":"햇살반 역사 신문 ⑥ 할머니의 투표 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_c#25','soc',6,1,'u1','','g6_1_soc_u1_review_c','unit_review','SO6-1-u1-C17',4,'essay','teacher','신문 ⑧을 보고 산업화로 좋아진 점과 산업화의 그늘을 하나씩 쓰고, 그늘을 고치려고 사람들이 한 노력을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO6-1-u1-C17","difficulty":4,"kind":"essay","stem":"신문 ⑧을 보고 산업화로 좋아진 점과 산업화의 그늘을 하나씩 쓰고, 그늘을 고치려고 사람들이 한 노력을 쓰세요.","answer_guide":{"answer":"예: 고속 국도가 생겨 할머니가 고향에 하루 만에 다녀올 수 있게 된 것은 좋아진 점이다. 그러나 공장 언니들은 밤늦게까지 일하고 쉬는 날이 적었다. 그래서 많은 사람이 근무 환경을 고치고 임금을 올려 일하는 사람의 권리를 지키려고 노력했다.","scoring_points":["좋아진 점을 썼는가","그늘을 썼는가","그늘을 고치려는 노력을 썼는가"]},"explanation":["좋아진 점을 써요.","그늘도 써요.","고치려는 노력을 써요."],"asset":{"type":"passage","lines":["할머니는 시골에서 도시로 이사 와 언덕 위 동네에 사셨다.","고속 국도가 생기자 고향에 하루 만에 다녀올 수 있었다.","공장 언니들은 밤늦게까지 일하고 쉬는 날이 적었다.","일하는 사람의 권리를 지키자는 목소리가 점점 커졌다.","우리 반은 이 이야기로 숨은 글씨 그림도 그렸다."],"title":"햇살반 역사 신문 ⑧ 도시로 온 할머니"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_d#1','soc',6,1,'u1','','g6_1_soc_u1_review_d','unit_review','SO6-1-u1-C2',1,'mc','auto','나라가 분단되지 않았으면 치르지 않아도 될 비용을 무엇이라고 하나요?',ARRAY['SO6-1-u1-X03']::text[],false,'{"seq":1,"concept":"SO6-1-u1-C2","difficulty":1,"kind":"mc","stem":"나라가 분단되지 않았으면 치르지 않아도 될 비용을 무엇이라고 하나요?","options":[{"t":"분단 비용","correct":true},{"t":"교통 비용","mis":"SO6-1-u1-X03"},{"t":"관람 비용","mis":"SO6-1-u1-X03"},{"t":"급식 비용","mis":"SO6-1-u1-X03"}],"explanation":["분단 때문에 생겨요.","여러 갈래가 있어요.","분단 비용이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_d#2','soc',6,1,'u1','','g6_1_soc_u1_review_d','unit_review','SO6-1-u1-C3',1,'ox','auto','비무장 지대는 군사 충돌을 막으려고 정한 곳이라 자연환경이 잘 보전되어 있어요.',ARRAY['SO6-1-u1-X06']::text[],false,'{"seq":2,"concept":"SO6-1-u1-C3","difficulty":1,"kind":"ox","stem":"비무장 지대는 군사 충돌을 막으려고 정한 곳이라 자연환경이 잘 보전되어 있어요.","answer":"O","reason_options":[{"t":"사람의 손이 거의 닿지 않아 희귀한 생물이 살기 때문에","correct":true},{"t":"군대가 가장 많이 모여 싸우는 곳이기 때문에","mis":"SO6-1-u1-X06"}],"mis":"SO6-1-u1-X06","explanation":["충돌을 막으려 정했어요.","자연이 잘 남았어요.","그래서 O예요."],"asset":{"type":"passage","lines":["우리 모둠은 인터넷으로 DMZ 평화의 길을 답사했다.","누리집에서 그곳의 의미, 있었던 일, 주요 시설을 차례로 살폈다.","희귀한 새와 식물 사진이 많아 모두 놀랐다.","통일 뒤에는 이곳을 평화 생태 학습장으로 만들자고 기사에 썼다."],"title":"햇살반 역사 신문 ② 답사 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_d#3','soc',6,1,'u1','','g6_1_soc_u1_review_d','unit_review','SO6-1-u1-C5',1,'ox','auto','남북 기본 합의서에는 남북 화해, 평화, 교류와 협력 등의 내용이 담겨 있어요.',ARRAY['SO6-1-u1-X10']::text[],false,'{"seq":3,"concept":"SO6-1-u1-C5","difficulty":1,"kind":"ox","stem":"남북 기본 합의서에는 남북 화해, 평화, 교류와 협력 등의 내용이 담겨 있어요.","answer":"O","reason_options":[{"t":"남과 북이 서로 화해하고 교류하며 협력하기로 약속했기 때문에","correct":true},{"t":"남과 북이 서로 만나지 않기로 약속했기 때문에","mis":"SO6-1-u1-X10"}],"mis":"SO6-1-u1-X10","explanation":["화해와 평화를 담았어요.","교류와 협력도 담았어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_d#4','soc',6,1,'u1','','g6_1_soc_u1_review_d','unit_review','SO6-1-u1-C8',1,'ox','auto','평화 통일은 어른들만 할 수 있는 일이라 어린이가 할 일은 없어요.',ARRAY['SO6-1-u1-X13']::text[],false,'{"seq":4,"concept":"SO6-1-u1-C8","difficulty":1,"kind":"ox","stem":"평화 통일은 어른들만 할 수 있는 일이라 어린이가 할 일은 없어요.","answer":"X","reason_options":[{"t":"관심 갖기, 마음 키우기, 돕기, 알리기처럼 어린이도 할 수 있는 일이 많기 때문에","correct":true},{"t":"평화 통일은 나라끼리만 정하는 일이기 때문에","mis":"SO6-1-u1-X13"}],"mis":"SO6-1-u1-X13","explanation":["어린이도 할 수 있어요.","신문 ④처럼 실천해요.","그래서 X예요."],"asset":{"type":"passage","lines":["ⓐ 남북 음식을 골라 평화 통일 밥상을 그렸다.","ⓑ 「우리는 한민족, 언제나 함께」를 쓴 종이비행기를 날렸다.","ⓒ 알뜰 시장을 열어 모은 돈을 북한 어린이 돕기에 보냈다.","ⓓ 통일 퀴즈 대회를 열어 다른 반 친구들도 초대했다."],"title":"햇살반 역사 신문 ④ 우리 반 통일 주간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_d#5','soc',6,1,'u1','','g6_1_soc_u1_review_d','unit_review','SO6-1-u1-C10',1,'ox','auto','4·19 혁명의 결과 3·15 부정 선거는 그대로 인정되었어요.',ARRAY['SO6-1-u1-X17']::text[],false,'{"seq":5,"concept":"SO6-1-u1-C10","difficulty":1,"kind":"ox","stem":"4·19 혁명의 결과 3·15 부정 선거는 그대로 인정되었어요.","answer":"X","reason_options":[{"t":"대통령이 물러나고 3·15 부정 선거는 무효가 되었기 때문에","correct":true},{"t":"시위가 아무 결과도 남기지 못했기 때문에","mis":"SO6-1-u1-X17"}],"mis":"SO6-1-u1-X17","explanation":["대통령이 물러났어요.","선거는 무효가 됐어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_d#6','soc',6,1,'u1','','g6_1_soc_u1_review_d','unit_review','SO6-1-u1-C11',1,'ox','auto','5·18 민주화 운동은 세계 여러 나라의 민주화 운동에도 영향을 주었어요.',ARRAY['SO6-1-u1-X20']::text[],false,'{"seq":6,"concept":"SO6-1-u1-C11","difficulty":1,"kind":"ox","stem":"5·18 민주화 운동은 세계 여러 나라의 민주화 운동에도 영향을 주었어요.","answer":"O","reason_options":[{"t":"민주주의를 지키려는 시민의 의지가 세계에 알려졌기 때문에","correct":true},{"t":"광주 안에서만 알려지고 끝난 일이기 때문에","mis":"SO6-1-u1-X20"}],"mis":"SO6-1-u1-X20","explanation":["진실이 알려졌어요.","세계에 영향을 주었어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_d#7','soc',6,1,'u1','','g6_1_soc_u1_review_d','unit_review','SO6-1-u1-C13',1,'ox','auto','신문 ⑥의 할머니처럼 시민 단체에서 활동하는 것은 6월 민주 항쟁 뒤 커진 시민 참여의 모습이에요.',ARRAY['SO6-1-u1-X23']::text[],false,'{"seq":7,"concept":"SO6-1-u1-C13","difficulty":1,"kind":"ox","stem":"신문 ⑥의 할머니처럼 시민 단체에서 활동하는 것은 6월 민주 항쟁 뒤 커진 시민 참여의 모습이에요.","answer":"O","reason_options":[{"t":"시민들이 시민 단체를 만들어 사회문제 해결에 참여하게 되었기 때문에","correct":true},{"t":"시민 단체는 정부가 만든 기관이기 때문에","mis":"SO6-1-u1-X23"}],"mis":"SO6-1-u1-X23","explanation":["시민 단체가 늘었어요.","사회문제에 참여해요.","시민 참여가 커졌어요."],"asset":{"type":"passage","lines":["할머니는 대통령을 처음 직접 뽑던 날을 또렷이 기억하신다.","투표소 앞에 줄이 길게 늘어섰는데도 모두 웃는 얼굴이었다고 했다.","요즘은 우리 지역의 대표도 주민이 직접 뽑는다.","할머니는 시민 단체에서 하천 지킴이로 활동하신다."],"title":"햇살반 역사 신문 ⑥ 할머니의 투표 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_d#8','soc',6,1,'u1','','g6_1_soc_u1_review_d','unit_review','SO6-1-u1-C16',1,'ox','auto','산업화 과정에서 많은 사람이 일자리를 찾아 농촌으로 몰려들었어요.',ARRAY['SO6-1-u1-X28']::text[],false,'{"seq":8,"concept":"SO6-1-u1-C16","difficulty":1,"kind":"ox","stem":"산업화 과정에서 많은 사람이 일자리를 찾아 농촌으로 몰려들었어요.","answer":"X","reason_options":[{"t":"많은 사람이 일자리를 찾아 도시로 몰려들었기 때문에","correct":true},{"t":"도시에는 일자리가 하나도 없었기 때문에","mis":"SO6-1-u1-X28"}],"mis":"SO6-1-u1-X28","explanation":["일자리는 도시에 많았어요.","신문 ⑧의 할머니도 도시로 왔어요.","그래서 X예요."],"asset":{"type":"passage","lines":["할머니는 시골에서 도시로 이사 와 언덕 위 동네에 사셨다.","고속 국도가 생기자 고향에 하루 만에 다녀올 수 있었다.","공장 언니들은 밤늦게까지 일하고 쉬는 날이 적었다.","일하는 사람의 권리를 지키자는 목소리가 점점 커졌다.","우리 반은 이 이야기로 숨은 글씨 그림도 그렸다."],"title":"햇살반 역사 신문 ⑧ 도시로 온 할머니"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_d#9','soc',6,1,'u1','','g6_1_soc_u1_review_d','unit_review','SO6-1-u1-C2',2,'mc','auto','분단이 오래 이어지면 남북의 말에 생길 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X02']::text[],false,'{"seq":9,"concept":"SO6-1-u1-C2","difficulty":2,"kind":"mc","stem":"분단이 오래 이어지면 남북의 말에 생길 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"같은 것을 다르게 부르는 말이 늘어 서로 알아듣기 어려워진다","correct":true},{"t":"말이 저절로 하나로 합쳐진다","mis":"SO6-1-u1-X02"},{"t":"말에는 아무 변화가 없다","mis":"SO6-1-u1-X02"},{"t":"한쪽 말이 저절로 사라진다","mis":"SO6-1-u1-X02"}],"explanation":["70여 년이 흘렀어요.","차이가 커지고 있어요.","소통이 어려워져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_d#10','soc',6,1,'u1','','g6_1_soc_u1_review_d','unit_review','SO6-1-u1-C3',2,'mc','auto','분단의 아픔이 담긴 장소를 설명한 것으로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X05']::text[],false,'{"seq":10,"concept":"SO6-1-u1-C3","difficulty":2,"kind":"mc","stem":"분단의 아픔이 담긴 장소를 설명한 것으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"사람들이 쉬려고 새로 만든 놀이공원","correct":true},{"t":"전쟁의 흔적이 남아 있는 곳","mis":"SO6-1-u1-X05"},{"t":"분단으로 생긴 곳","mis":"SO6-1-u1-X05"},{"t":"희생된 군인을 기리는 기념관이 있는 곳","mis":"SO6-1-u1-X05"}],"explanation":["전쟁과 분단과 이어져요.","놀이공원은 아니에요.","알맞지 않은 것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_d#11','soc',6,1,'u1','','g6_1_soc_u1_review_d','unit_review','SO6-1-u1-C6',2,'mc','auto','신문 ③의 ㉮처럼 남북이 함께 사전을 만드는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X04','SO6-1-u1-X09']::text[],false,'{"seq":11,"concept":"SO6-1-u1-C6","difficulty":2,"kind":"mc","stem":"신문 ③의 ㉮처럼 남북이 함께 사전을 만드는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"달라진 말을 서로 이해하고 한민족임을 잊지 않으며 통일을 준비하려고","correct":true},{"t":"한쪽 말을 없애려고","mis":"SO6-1-u1-X04"},{"t":"외국어를 배우려고","mis":"SO6-1-u1-X09"},{"t":"경제적 이익만 얻으려고","mis":"SO6-1-u1-X09"}],"explanation":["말이 달라지고 있어요.","서로 이해해야 해요.","통일을 준비해요."],"asset":{"type":"passage","lines":["㉮ 남북 국어학자들이 함께 만드는 사전 — 달라진 말을 모아 싣는다.","㉯ 남북 학자들의 문화유산 공동 발굴 — 고려의 궁궐터에서 했다.","㉰ 공업 단지 — 남한의 자본·기술과 북한의 노동력을 합했다.","㉱ 철도·도로 연결 — 끊어진 길을 다시 이으려 했다."],"title":"햇살반 역사 신문 ③ 남북이 함께한 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_d#12','soc',6,1,'u1','','g6_1_soc_u1_review_d','unit_review','SO6-1-u1-C8',2,'mc','auto','북한 연구자에게 필요한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X04','SO6-1-u1-X13']::text[],false,'{"seq":12,"concept":"SO6-1-u1-C8","difficulty":2,"kind":"mc","stem":"북한 연구자에게 필요한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"남북의 차이를 이해하고 받아들이는 포용력","correct":true},{"t":"북한을 이기려는 마음","mis":"SO6-1-u1-X04"},{"t":"새로운 문화에 대한 무관심","mis":"SO6-1-u1-X13"},{"t":"한쪽 말만 옳다는 생각","mis":"SO6-1-u1-X04"}],"explanation":["차이를 이해해요.","받아들여요.","포용력이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_d#13','soc',6,1,'u1','','g6_1_soc_u1_review_d','unit_review','SO6-1-u1-C12',2,'mc','auto','신문 ⑤의 세 사건을 일어난 차례대로 바르게 늘어놓은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X24']::text[],false,'{"seq":13,"concept":"SO6-1-u1-C12","difficulty":2,"kind":"mc","stem":"신문 ⑤의 세 사건을 일어난 차례대로 바르게 늘어놓은 것은 어느 것인가요?","options":[{"t":"4·19 혁명 → 5·18 민주화 운동 → 6월 민주 항쟁","correct":true},{"t":"5·18 민주화 운동 → 4·19 혁명 → 6월 민주 항쟁","mis":"SO6-1-u1-X24"},{"t":"6월 민주 항쟁 → 5·18 민주화 운동 → 4·19 혁명","mis":"SO6-1-u1-X24"},{"t":"4·19 혁명 → 6월 민주 항쟁 → 5·18 민주화 운동","mis":"SO6-1-u1-X24"}],"explanation":["부정 선거가 먼저예요.","정변 뒤 광주의 일이에요.","직선제 요구가 마지막이에요."],"asset":{"type":"passage","lines":["4·19 혁명 — 3·15 부정 선거 → 각계각층의 시위 → 대통령이 물러남","5·18 민주화 운동 — 군인들의 권력 장악 → 광주 시민의 민주화 요구","6월 민주 항쟁 — 독재와 간선제 유지 → 전국의 직선제 요구 → 직선제","세 사건 모두 시민이 민주주의를 지키려고 나선 일이다."],"title":"햇살반 역사 신문 ⑤ 민주화 흐름 코너"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_d#14','soc',6,1,'u1','','g6_1_soc_u1_review_d','unit_review','SO6-1-u1-C13',2,'mc','auto','6월 민주 항쟁으로 달라진 모습으로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X23']::text[],false,'{"seq":14,"concept":"SO6-1-u1-C13","difficulty":2,"kind":"mc","stem":"6월 민주 항쟁으로 달라진 모습으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"대통령을 선거인단만 뽑게 되었다","correct":true},{"t":"대통령 직선제가 시행되었다","mis":"SO6-1-u1-X23"},{"t":"지방 자치제가 다시 시행되었다","mis":"SO6-1-u1-X23"},{"t":"시민 단체의 참여가 늘었다","mis":"SO6-1-u1-X23"}],"explanation":["선거인단이 뽑는 건 전의 방식이에요.","나머지는 달라진 모습이에요.","알맞지 않은 것을 골라요."],"asset":{"type":"passage","lines":["할머니는 대통령을 처음 직접 뽑던 날을 또렷이 기억하신다.","투표소 앞에 줄이 길게 늘어섰는데도 모두 웃는 얼굴이었다고 했다.","요즘은 우리 지역의 대표도 주민이 직접 뽑는다.","할머니는 시민 단체에서 하천 지킴이로 활동하신다."],"title":"햇살반 역사 신문 ⑥ 할머니의 투표 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_d#15','soc',6,1,'u1','','g6_1_soc_u1_review_d','unit_review','SO6-1-u1-C15',2,'mc','auto','1960년대에 경공업 제품을 만들어 수출할 수 있었던 바탕은 무엇인가요?',ARRAY['SO6-1-u1-X26']::text[],false,'{"seq":15,"concept":"SO6-1-u1-C15","difficulty":2,"kind":"mc","stem":"1960년대에 경공업 제품을 만들어 수출할 수 있었던 바탕은 무엇인가요?","options":[{"t":"풍부한 노동력","correct":true},{"t":"높은 기술력","mis":"SO6-1-u1-X26"},{"t":"큰 연구소","mis":"SO6-1-u1-X26"},{"t":"넓은 자동차 공장","mis":"SO6-1-u1-X26"}],"explanation":["일할 사람이 많았어요.","손이 많이 가는 물건이에요.","풍부한 노동력이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_d#16','soc',6,1,'u1','','g6_1_soc_u1_review_d','unit_review','SO6-1-u1-C16',2,'mc','auto','라디오와 텔레비전이 널리 보급되면서 성장한 것은 무엇인가요?',ARRAY['SO6-1-u1-X28']::text[],false,'{"seq":16,"concept":"SO6-1-u1-C16","difficulty":2,"kind":"mc","stem":"라디오와 텔레비전이 널리 보급되면서 성장한 것은 무엇인가요?","options":[{"t":"가요·영화·드라마·스포츠 같은 대중문화","correct":true},{"t":"농촌 인구","mis":"SO6-1-u1-X28"},{"t":"달동네","mis":"SO6-1-u1-X28"},{"t":"간선제","mis":"SO6-1-u1-X28"}],"explanation":["대중 매체가 보급됐어요.","많은 사람이 함께 즐겨요.","대중문화가 성장했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_d#17','soc',6,1,'u1','','g6_1_soc_u1_review_d','unit_review','SO6-1-u1-C4',3,'ox','auto','신문 ②의 모둠처럼 답사를 마친 뒤 알게 된 것과 처음 짐작을 견주어 보는 것이 좋아요.',ARRAY['SO6-1-u1-X08']::text[],false,'{"seq":17,"concept":"SO6-1-u1-C4","difficulty":3,"kind":"ox","stem":"신문 ②의 모둠처럼 답사를 마친 뒤 알게 된 것과 처음 짐작을 견주어 보는 것이 좋아요.","answer":"O","reason_options":[{"t":"답사는 가서 알게 되는 일이라 짐작이 어떻게 바뀌었는지 확인할 수 있기 때문에","correct":true},{"t":"처음 짐작은 언제나 틀리기 때문에","mis":"SO6-1-u1-X08"}],"mis":"SO6-1-u1-X08","explanation":["답사는 알게 되는 일이에요.","짐작이 바뀌어요.","견주어 봐요."],"asset":{"type":"passage","lines":["우리 모둠은 인터넷으로 DMZ 평화의 길을 답사했다.","누리집에서 그곳의 의미, 있었던 일, 주요 시설을 차례로 살폈다.","희귀한 새와 식물 사진이 많아 모두 놀랐다.","통일 뒤에는 이곳을 평화 생태 학습장으로 만들자고 기사에 썼다."],"title":"햇살반 역사 신문 ② 답사 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_d#18','soc',6,1,'u1','','g6_1_soc_u1_review_d','unit_review','SO6-1-u1-C7',3,'ox','auto','남북 경제 협력 사업은 평화 통일을 이루는 밑바탕이 될 수 있어요.',ARRAY['SO6-1-u1-X12']::text[],false,'{"seq":18,"concept":"SO6-1-u1-C7","difficulty":3,"kind":"ox","stem":"남북 경제 협력 사업은 평화 통일을 이루는 밑바탕이 될 수 있어요.","answer":"O","reason_options":[{"t":"함께 일하며 서로 잘 살게 되면 믿음이 쌓이기 때문에","correct":true},{"t":"경제 협력은 통일과 아무 관계가 없기 때문에","mis":"SO6-1-u1-X12"}],"mis":"SO6-1-u1-X12","explanation":["함께 일해요.","믿음이 쌓여요.","통일의 밑바탕이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_d#19','soc',6,1,'u1','','g6_1_soc_u1_review_d','unit_review','SO6-1-u1-C9',3,'ox','auto','세 민주화 운동은 날짜와 숫자만 외우면 충분히 이해할 수 있어요.',ARRAY['SO6-1-u1-X31']::text[],false,'{"seq":19,"concept":"SO6-1-u1-C9","difficulty":3,"kind":"ox","stem":"세 민주화 운동은 날짜와 숫자만 외우면 충분히 이해할 수 있어요.","answer":"X","reason_options":[{"t":"각 사건이 왜 일어나 어떤 결과를 낳았는지 원인과 결과를 이어야 이해할 수 있기 때문에","correct":true},{"t":"민주화 운동에는 원인이 없기 때문에","mis":"SO6-1-u1-X31"}],"mis":"SO6-1-u1-X31","explanation":["외우기만으로는 부족해요.","원인과 결과를 이어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_d#20','soc',6,1,'u1','','g6_1_soc_u1_review_d','unit_review','SO6-1-u1-C13',3,'ox','auto','신문 ⑥에서 할머니가 하천 지킴이로 활동하시는 것은 시민이 사회문제 해결에 참여하는 모습이에요.',ARRAY['SO6-1-u1-X23']::text[],false,'{"seq":20,"concept":"SO6-1-u1-C13","difficulty":3,"kind":"ox","stem":"신문 ⑥에서 할머니가 하천 지킴이로 활동하시는 것은 시민이 사회문제 해결에 참여하는 모습이에요.","answer":"O","reason_options":[{"t":"시민 단체를 통해 지역의 문제를 함께 해결하려는 활동이기 때문에","correct":true},{"t":"하천 지킴이는 대통령을 뽑는 일이기 때문에","mis":"SO6-1-u1-X23"}],"mis":"SO6-1-u1-X23","explanation":["시민 단체 활동이에요.","하천 문제를 함께 풀어요.","시민 참여예요."],"asset":{"type":"passage","lines":["할머니는 대통령을 처음 직접 뽑던 날을 또렷이 기억하신다.","투표소 앞에 줄이 길게 늘어섰는데도 모두 웃는 얼굴이었다고 했다.","요즘은 우리 지역의 대표도 주민이 직접 뽑는다.","할머니는 시민 단체에서 하천 지킴이로 활동하신다."],"title":"햇살반 역사 신문 ⑥ 할머니의 투표 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_d#21','soc',6,1,'u1','','g6_1_soc_u1_review_d','unit_review','SO6-1-u1-C15',3,'ox','auto','같은 라면이라도 먹을거리가 모자라던 때와 오늘날 만든 목적이 달라요.',ARRAY['SO6-1-u1-X27']::text[],false,'{"seq":21,"concept":"SO6-1-u1-C15","difficulty":3,"kind":"ox","stem":"같은 라면이라도 먹을거리가 모자라던 때와 오늘날 만든 목적이 달라요.","answer":"O","reason_options":[{"t":"옛날에는 식량 부족을 해결하려고, 오늘날에는 수출 상품으로 만들기 때문에","correct":true},{"t":"라면은 언제나 같은 목적으로만 만들기 때문에","mis":"SO6-1-u1-X27"}],"mis":"SO6-1-u1-X27","explanation":["시대 상황이 달라요.","목적도 달라졌어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_d#22','soc',6,1,'u1','','g6_1_soc_u1_review_d','unit_review','SO6-1-u1-C17',3,'ox','auto','산업화 시기에 많은 사람이 근무 환경 개선과 임금 인상 등 근로자의 권리를 보호하려고 노력했어요.',ARRAY['SO6-1-u1-X30']::text[],false,'{"seq":22,"concept":"SO6-1-u1-C17","difficulty":3,"kind":"ox","stem":"산업화 시기에 많은 사람이 근무 환경 개선과 임금 인상 등 근로자의 권리를 보호하려고 노력했어요.","answer":"O","reason_options":[{"t":"근로자들이 열악한 환경에서 오래 일하자 그 권리를 지키려는 목소리가 커졌기 때문에","correct":true},{"t":"근로자의 권리는 아무도 관심을 두지 않았기 때문에","mis":"SO6-1-u1-X30"}],"mis":"SO6-1-u1-X30","explanation":["어려움이 있었어요.","목소리가 커졌어요.","권리를 지키려 했어요."],"asset":{"type":"passage","lines":["할머니는 시골에서 도시로 이사 와 언덕 위 동네에 사셨다.","고속 국도가 생기자 고향에 하루 만에 다녀올 수 있었다.","공장 언니들은 밤늦게까지 일하고 쉬는 날이 적었다.","일하는 사람의 권리를 지키자는 목소리가 점점 커졌다.","우리 반은 이 이야기로 숨은 글씨 그림도 그렸다."],"title":"햇살반 역사 신문 ⑧ 도시로 온 할머니"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_d#23','soc',6,1,'u1','','g6_1_soc_u1_review_d','unit_review','SO6-1-u1-C16',4,'mc','auto','신문 ⑦과 ⑧을 함께 볼 때 산업화에 대한 결론으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u1-X27','SO6-1-u1-X28','SO6-1-u1-X29']::text[],false,'{"seq":23,"concept":"SO6-1-u1-C16","difficulty":4,"kind":"mc","stem":"신문 ⑦과 ⑧을 함께 볼 때 산업화에 대한 결론으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"여러 사람의 노력으로 산업이 발달해 생활이 크게 달라졌지만 그늘도 있어 함께 고쳐 왔다","correct":true},{"t":"산업화는 정부 혼자 이루었고 그늘은 없었다","mis":"SO6-1-u1-X27"},{"t":"산업이 발달해도 생활은 달라지지 않았다","mis":"SO6-1-u1-X28"},{"t":"산업화는 그늘만 남긴 일이다","mis":"SO6-1-u1-X29"}],"explanation":["⑦은 산업의 발달이에요.","⑧은 생활과 그늘이에요.","함께 고쳐 왔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_d#24','soc',6,1,'u1','','g6_1_soc_u1_review_d','unit_review','SO6-1-u1-C14',4,'essay','teacher','신문 ⑦을 보고 할아버지가 일한 곳을 산업 발달의 흐름과 이어 쓰고, 산업화를 이끈 사람들의 노력을 두 가지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO6-1-u1-C14","difficulty":4,"kind":"essay","stem":"신문 ⑦을 보고 할아버지가 일한 곳을 산업 발달의 흐름과 이어 쓰고, 산업화를 이끈 사람들의 노력을 두 가지 쓰세요.","answer_guide":{"answer":"예: 할아버지는 1960년대 경공업이 발달할 때 신발 공장에서 일했고, 1970년대 중화학 공업이 발달할 때 조선소에서 배를 만들었다. 정부는 경제 개발 계획을 세우고 고속 국도와 항만, 연구소를 지었고, 독일로 간 광부와 간호사는 외화를 벌어 산업화의 밑거름을 만들었다.","scoring_points":["할아버지의 일터를 시대·산업과 이어 썼는가","경공업에서 중화학 공업으로의 흐름이 드러났는가","사람들의 노력 두 가지를 썼는가"]},"explanation":["신발은 경공업이에요.","배는 중화학 공업이에요.","여러 사람의 노력을 써요."],"asset":{"type":"passage","lines":["어릴 때 — 지원받은 밀가루로 만든 국수를 자주 드셨다.","청년 때 — 신발 공장에서 만든 신발이 배에 실려 외국으로 팔렸다.","그 뒤 — 큰 조선소에서 커다란 배를 만드는 일을 하셨다.","아빠가 어릴 때 — 우리 집에 자동차와 컬러텔레비전이 생겼다."],"title":"햇살반 역사 신문 ⑦ 할아버지의 일터"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u1_review_d#25','soc',6,1,'u1','','g6_1_soc_u1_review_d','unit_review','SO6-1-u1-C18',4,'essay','teacher','이 단원에서 공부한 사건 하나로 숨은 글씨 그림을 그린다고 생각하고, 사건·숨길 낱말·그릴 장면을 쓴 뒤 그 장면을 고른 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO6-1-u1-C18","difficulty":4,"kind":"essay","stem":"이 단원에서 공부한 사건 하나로 숨은 글씨 그림을 그린다고 생각하고, 사건·숨길 낱말·그릴 장면을 쓴 뒤 그 장면을 고른 까닭을 쓰세요.","answer_guide":{"answer":"예: 사건은 5·18 민주화 운동이고 숨길 낱말은 「알리다」이다. 카메라를 든 기자와 편지를 쓰는 시민들의 팔과 몸으로 글씨의 획을 만들고, 숨긴 글씨는 진하게 칠하겠다. 바깥과 막혀 있던 광주의 일을 시민과 기자들이 알리려 애썼기 때문에 진실을 알린 사람들의 모습을 골랐다.","scoring_points":["사건과 낱말을 썼는가","장면과 숨기는 방법을 썼는가","사건 내용과 이어 까닭을 썼는가"]},"explanation":["사건을 골라요.","장면 속에 숨겨요.","사건과 이어 까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
